INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C1','kor',3,2,'u4',2,'높임 표현과 대화 예절 — 이 단원의 두 가지로, 같은 부탁이라도 말을 건네는 상대·상황이 달라지면 쓰는 말이 달라지며, 둘 다 상대를 존중하는 일임',ARRAY['[4국01-06][4국04-04]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C2','kor',3,2,'u4',2,'높임 표현의 뜻 — 말하는 사람이 어떤 대상을 높이려고 쓰는 표현이고, 그 안에 상대를 존중하는 마음이 담김(말을 길게 늘이거나 어려운 낱말을 쓰는 방법이 아님)',ARRAY['[4국04-04]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C3','kor',3,2,'u4',2,'높임 표현을 쓰는 상황 — 웃어른께 말씀드릴 때뿐 아니라 학급 회의처럼 여러 사람 앞에서·처음 만난 사이에서도 쓰고, 어른이 더 어린 사람에게 쓰기도 함; 나이만이 아니라 어떤 곳에서·어떤 사이로·어떤 마음을 나타내려는지를 함께 살핌(높임 표현은 나이표가 아님)',ARRAY['[4국04-04]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C4','kor',3,2,'u4',3,'‘-시-’로 높이기 — 움직임을 나타내는 말 안에 ‘-시-’를 넣으면 그 움직임을 하는 사람을 높임(오다 → 오시다, 읽다 → 읽으시다)',ARRAY['[4국04-04]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C5','kor',3,2,'u4',3,'‘께’와 ‘께서’로 높이기 — ‘이/가’ 대신 ‘께서’, ‘에게’ 대신 ‘께’를 써서 높임',ARRAY['[4국04-04]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C6','kor',3,2,'u4',3,'높임의 뜻이 있는 낱말 — 낱말 자체에 높임의 뜻이 담긴 것(집-댁 · 나이-연세 · 이름-성함 · 있다-계시다 · 자다-주무시다 · 사람-분 · 아프다-편찮으시다 · 묻다-여쭈어보다 · 보다-뵙다)',ARRAY['[4국04-04]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C7','kor',3,2,'u4',3,'‘-습니다’와 ‘요’로 듣는 사람 높이기 — 말끝에 ‘-습니다’나 ‘요’를 붙이면 그 말을 듣는 사람을 높임(앞의 셋은 말 속의 사람을 높임)',ARRAY['[4국04-04]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C8','kor',3,2,'u4',3,'높임은 사람에게 — 높이는 대상은 사람이고 물건이나 일에는 높임말을 쓰지 않으며, ‘-시-’를 말끝마다 붙인다고 더 바른 말이 되지도, 어렵다고 아예 쓰지 않아도 되는 것도 아님',ARRAY['[4국04-04]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C9','kor',3,2,'u4',3,'잘못 쓴 높임 표현 바로잡기 — 누구를 높여야 하는지(말 속의 사람·듣는 사람)를 먼저 찾아, 물건이나 나를 높인 곳·높여야 할 분을 높이지 않은 곳을 바르게 고침',ARRAY['[4국04-04]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C10','kor',3,2,'u4',5,'서툴러도 말을 건네는 마음 — 「서툰 인사」의 민결이처럼 틀릴까 봐 말을 건네지 않는 것보다, 조금 서툴러도 말을 건네는 것이 상대를 살피는 일임(부끄러움이 아니라 알아차림)',ARRAY['[4국04-04][4국01-06]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C11','kor',3,2,'u4',5,'말을 옮길 때의 높임 — 웃어른의 말씀을 다른 사람에게 옮길 때에도 높여야 할 분은 그대로 높임(“선생님께서 너 오라고 하셔.”); 말을 옮겨 받는 친구를 높이지는 않음',ARRAY['[4국04-04][4국01-06]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C12','kor',3,2,'u4',5,'낱말 사이의 관계 — 한 낱말이 다른 낱말의 뜻을 포함하는 관계(신발-운동화), 서로 뜻이 반대인 관계(묻다-대답하다), 서로 뜻이 비슷한 관계(돕다-거들다)',ARRAY['[4국04-01](자기주도 l05_06 머리 표기)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C13','kor',3,2,'u4',7,'대화 예절의 뜻 — 말하는 사람과 듣는 사람이 말을 주고받을 때 지키는 것으로, 가장 먼저 상대를 배려하고 존중하려는 마음이 필요하며 그 마음은 말투·표정·듣는 태도에도 드러남(부탁을 다 들어주는 것이 아님)',ARRAY['[4국01-06]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C14','kor',3,2,'u4',7,'부르는 말·부탁하는 말·말하는 태도 — 같은 부탁도 상대를 부르는 말, 시키지 않고 묻는 부탁하는 말, 상대를 보며 말하는 태도에 따라 대답이 달라짐(예절은 내용이 아니라 이 세 가지에 드러남)',ARRAY['[4국01-06]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C15','kor',3,2,'u4',7,'거절할 때의 대화 예절 — 부탁을 들어줄 수 없을 때 거절하는 것은 잘못이 아니며, 미안한 마음과 도와줄 수 없는 까닭(할 수 있는 만큼)을 함께 말함; 웃어른의 부탁이어도 거짓으로 하겠다고 하지 않음',ARRAY['[4국01-06]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C16','kor',3,2,'u4',8,'상황을 이루는 것 — 대화 상대(누구와)·시간과 장소(언제 어디에서)·목적과 방식(무엇을 하려고 어떻게)이 달라지면 알맞은 예절도 달라짐(운동장과 도서관의 목소리)',ARRAY['[4국01-06]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C17','kor',3,2,'u4',8,'상황에 알맞은 대화 예절 — 웃어른이 물으실 때는 말끝뿐 아니라 자세와 대답하는 태도로, 모둠 활동에서는 함께 정하는 것과 이어지는 말로, 여럿이 함께 있을 때는 한 사람을 빼는 귓속말 없이 말함',ARRAY['[4국01-06]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C18','kor',3,2,'u4',8,'전화 예절 — 얼굴이 보이지 않으니 내가 누구인지 밝히고 상대를 확인하며, 지금 통화해도 되는지 묻고, 끊기 전에 끝인사를 함(받을 때까지 다시 걸기·바로 끊기·받자마자 내 말부터 하기는 알맞지 않음)',ARRAY['[4국01-06]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C19','kor',3,2,'u4',8,'모둠 대화에서 지킬 것 — 모둠 대화는 이기려는 것이 아니라 함께 답을 찾는 것이라 다른 사람의 말을 끝까지 듣고 내 생각도 말함(밀고 가기도, 아무 말 안 하기도 모둠 대화가 아님)',ARRAY['[4국01-06]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C20','kor',3,2,'u4',10,'상황을 살피고 대화하기 — 대화 상대·목적·방식을 먼저 살펴 대본에 들어갈 말(전화라면 누구인지 밝히기·통화해도 되는지 묻기·끝인사)을 정하고, 높임 표현과 대화 예절을 한 대화 안에서 함께 씀',ARRAY['[4국01-06][4국04-04]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C21','kor',3,2,'u4',10,'표정·몸짓·말투 — 같은 말이라도 표정·몸짓·말투에 따라 듣는 사람의 마음이 달라지고, 상대를 바라보기·고개 끄덕이기·하던 일 멈추기도 듣고 있다는 말이 되며, 전화에서는 “응.”·“그렇구나.” 같은 짧은 말이 그것을 대신함',ARRAY['[4국01-06][4국04-04]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C22','kor',3,2,'u4',10,'점검하고 되돌아보기 — 점검표·되돌아보기 표는 칸을 채우거나 점수를 고치려는 것이 아니라 다음에 고칠 점을 찾으려고 보는 것',ARRAY['[4국01-06][4국04-04]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C23','kor',3,2,'u4',12,'지킬 수 있는 다짐 쓰기 — 다짐 카드에는 언제·무엇을 할지 드러나게 한 가지만 적어야 실천할 수 있고(막연한 다짐·여러 개는 지키기 어려움), 어떤 예절을 고를지는 사람마다 다름',ARRAY['[4국04-04][4국01-06]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C24','kor',3,2,'u4',12,'실천 활동을 고르는 기준 — 우리 반에서 할 활동은 가장 재미있어 보이거나 빨리 끝나는 것이 아니라 이 단원에서 배운 것을 실제로 써 보는 것으로 고름',ARRAY['[4국04-04][4국01-06]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C25','kor',3,2,'u4',12,'방언 — 어느 한 지역에서만 쓰는, 표준어가 아닌 말로 같은 것을 지역마다 다르게 부르는 것이며 틀린 말이 아님; 실제 예는 지어내지 않고 둘레 어른께 여쭈어 알아봄(기초 다지기)',ARRAY['[4국04-04][4국01-06](케이티처 l14 표기)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u4-C26','kor',3,2,'u4',12,'모음자 ㅐ·ㅔ·ㅒ·ㅖ 바르게 쓰기 — ㅐ와 ㅔ는 가로획의 자리가 다르고, ㅒ와 ㅖ는 짧은 획이 두 개임(새해·세배·얘들아·계절, 기초 다지기)',ARRAY['[4국04-04][4국01-06](케이티처 l14 표기)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X01','kor',3,'u4',ARRAY['K3-2-u4-C1','K3-2-u4-C3']::text[],'같은 부탁인데 말이 달라진 까닭을 물건·시간처럼 말의 내용에서 찾고, 말을 건네는 상대와 곳이 달라졌다는 것을 놓친다','무엇이 그대로이고 누가 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X02','kor',3,'u4',ARRAY['K3-2-u4-C3']::text[],'높임 표현을 나보다 나이가 많은 사람에게만 쓰는 말(나이표)로 여겨, 학급 회의·처음 만난 사이·어른이 더 어린 사람에게 쓰는 높임을 틀렸다고 여긴다','어떤 곳에서, 어떤 사이로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X03','kor',3,'u4',ARRAY['K3-2-u4-C3']::text[],'한 번 높인 친구나 친구 사이에도 언제 어디서나 높임 표현을 써야 한다고 여긴다','쉬는 시간 짝과 학급 회의는 같은 곳일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X04','kor',3,'u4',ARRAY['K3-2-u4-C2']::text[],'높임 표현을 말을 길게 늘이거나 어려운 낱말을 많이 쓰는 방법으로 여긴다','높임 표현에 담긴 것은 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X05','kor',3,'u4',ARRAY['K3-2-u4-C4']::text[],'‘-시-’가 높이는 사람을 말하는 나나 장소로 여겨, 그 움직임을 하는 사람을 높인다는 것을 놓친다','그 일을 하는 사람이 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X06','kor',3,'u4',ARRAY['K3-2-u4-C5','K3-2-u4-C9']::text[],'높여야 할 분에게 ‘께’·‘께서’ 대신 ‘에게’·‘이/가’를 그대로 쓰거나, ‘께’와 ‘께서’를 엇갈려 쓴다','‘이/가’ 자리엔 께서, ‘에게’ 자리엔 께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X07','kor',3,'u4',ARRAY['K3-2-u4-C6']::text[],'높임의 뜻이 있는 낱말의 짝(나이-연세·이름-성함·있다-계시다·자다-주무시다·사람-분·아프다-편찮으시다·묻다-여쭈어보다·보다-뵙다)을 엇갈리게 잇는다','뜻은 같고 웃어른께 쓰는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X08','kor',3,'u4',ARRAY['K3-2-u4-C7','K3-2-u4-C9']::text[],'말끝의 ‘-습니다’·‘요’가 그 말을 듣는 사람을 높인다는 것을 모르고, 말 속의 사람을 높이는 방법과 듣는 사람을 높이는 방법을 섞는다','말을 듣는 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X09','kor',3,'u4',ARRAY['K3-2-u4-C8']::text[],'높임말은 많이 붙일수록 공손하다고 여겨 물건이나 일(우산·칠판·공책·숙제)에도 ‘-시-’나 ‘계시다’를 쓴다','높이는 것은 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X10','kor',3,'u4',ARRAY['K3-2-u4-C8','K3-2-u4-C9']::text[],'높임 표현이 어렵다며 아예 쓰지 않거나, 웃어른이 듣는 말인데도 말끝을 낮춘다','높일 사람만 찾으면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X11','kor',3,'u4',ARRAY['K3-2-u4-C9']::text[],'높이지 않아야 할 사람(말하는 나·친구·동생)에게 ‘-시-’나 ‘계시다’를 써서 높인다','그 일을 하는 사람이 나라면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X12','kor',3,'u4',ARRAY['K3-2-u4-C10']::text[],'높임말이 헷갈리거나 틀릴 것 같으면 말을 건네지 않는 것이 낫다고 여긴다','말을 건네지 않으면 상대는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X13','kor',3,'u4',ARRAY['K3-2-u4-C10']::text[],'한 글자도 틀리지 않아야 인사를 할 수 있다고 여기거나, 서툰 인사를 부끄러운 일로만 여긴다','어른은 무엇이 고맙다고 하셨지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X14','kor',3,'u4',ARRAY['K3-2-u4-C11']::text[],'웃어른의 말씀을 옮길 때 높여야 할 분을 빼 버리거나(“선생님이 너 오래”), 말을 옮겨 받는 친구 쪽을 높인다(“오시래”)','그 말씀을 처음 하신 분은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X15','kor',3,'u4',ARRAY['K3-2-u4-C12']::text[],'포함하는 관계·반대인 관계·비슷한 관계를 엇갈리게 안다','한 가지인가, 반대인가, 비슷한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X16','kor',3,'u4',ARRAY['K3-2-u4-C13','K3-2-u4-C15']::text[],'대화 예절을 남의 부탁을 모두 들어주는 것·시키는 대로 하는 것으로 여겨, 거절하면 예절을 어긴 것이라고 여긴다','예절은 들어주기가 아니라 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X17','kor',3,'u4',ARRAY['K3-2-u4-C13','K3-2-u4-C19']::text[],'말하지 않고 가만히 있으면 끼어들 일도 다툼도 없으니 예절을 가장 잘 지킨 것이라고 여긴다','내 생각은 어디에?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X18','kor',3,'u4',ARRAY['K3-2-u4-C14']::text[],'예절을 부탁한 내용·물건·친한 정도에서 찾고, 부르는 말·부탁하는 말·말하는 태도에 드러난다는 것을 놓친다','내용이 같았는데 무엇이 달랐나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X19','kor',3,'u4',ARRAY['K3-2-u4-C15']::text[],'부탁을 들어줄 수 없을 때 까닭 없이 “안 돼.”라고 짧게만 말하거나 말없이 피한다','상대가 “나를 싫어하나?” 하지 않으려면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X20','kor',3,'u4',ARRAY['K3-2-u4-C15']::text[],'웃어른의 부탁은 들어드릴 수 없어도 하겠다고 거짓으로 대답해야 한다고 여긴다','못 하는데 하겠다고 하면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X21','kor',3,'u4',ARRAY['K3-2-u4-C16','K3-2-u4-C17']::text[],'목소리 크기·말 빠르기를 예절로 여겨, 어디에서든 크게 말하면 좋다고 여긴다','운동장과 도서관은 같은 곳일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X22','kor',3,'u4',ARRAY['K3-2-u4-C16','K3-2-u4-C20']::text[],'상황을 이루는 것(대화 상대·시간과 장소·목적과 방식)을 엇갈리게 짝짓거나, 상황이 달라져도 말은 같아야 한다고 여긴다','누구와, 어디에서, 무엇을 하려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X23','kor',3,'u4',ARRAY['K3-2-u4-C17']::text[],'말끝에 ‘요’만 붙이면 예절을 다 지킨 것이라 여겨 누운 채·화면만 보며 대답하는 자세와 태도를 놓친다','말끝 말고 몸은 어땠나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X24','kor',3,'u4',ARRAY['K3-2-u4-C17']::text[],'여럿이 함께 있을 때 한 사람을 빼는 귓속말이나 함께 정하는 일과 상관없는 말을 해도 괜찮다고 여긴다','함께 있는 사람의 마음은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X25','kor',3,'u4',ARRAY['K3-2-u4-C18','K3-2-u4-C20']::text[],'전화에서 내가 누구인지 밝히지 않거나, 받을 때까지 다시 걸거나, 끝인사 없이 바로 끊거나, 받자마자 내 할 말부터 한다','상대는 나를 볼 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X26','kor',3,'u4',ARRAY['K3-2-u4-C19']::text[],'모둠 대화를 이기는 일로 여겨 다른 생각은 듣지 않고 내 생각만 끝까지 밀고 간다','함께 답을 찾는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X27','kor',3,'u4',ARRAY['K3-2-u4-C21']::text[],'표정·몸짓·말투는 말이 아니라 아무 뜻이 없다고 여기거나, 전화처럼 보이지 않으면 듣고 있다는 것을 알릴 방법이 없다고 여긴다','같은 말, 다른 말투') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X28','kor',3,'u4',ARRAY['K3-2-u4-C22']::text[],'점검표·되돌아보기 표를 칸을 채우거나 점수를 높여 적는 일로 여긴다','고치려고 보는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X29','kor',3,'u4',ARRAY['K3-2-u4-C23']::text[],'다짐을 “착하게 살겠습니다”처럼 언제·무엇을 할지 드러나지 않게 쓰거나 여러 개를 한꺼번에 적고, 남과 같은 예절을 골라야 한다고 여긴다','내일 해 보았는지 알 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X30','kor',3,'u4',ARRAY['K3-2-u4-C24']::text[],'우리 반 실천 활동을 가장 재미있어 보이거나 빨리 끝나는 것으로 고른다','실천 시간은 무엇을 하려고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X31','kor',3,'u4',ARRAY['K3-2-u4-C25']::text[],'방언을 잘못 배운 틀린 말이나 옛날에만 쓰던 말로 여기거나, 확인하지 않고 지어낸 낱말을 방언이라고 여긴다','다른 것은 틀린 것이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X32','kor',3,'u4',ARRAY['K3-2-u4-C26']::text[],'ㅐ와 ㅔ, ㅒ와 ㅖ의 모양을 섞어 새해·세배·얘들아·계절을 틀리게 쓴다','가로획 자리, 짧은 획 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u4-X33','kor',3,'u4',ARRAY['K3-2-u4-C10','K3-2-u4-C15']::text[],'이야기나 대화에서 인물의 마음·행동의 까닭을 글에 없는 내용으로 짐작해 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#1','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C1',1,'mc','auto','친구에게 한 말과 선생님께 한 말이 달라진 까닭은 무엇인가요?',ARRAY['K3-2-u4-X01']::text[],false,'{"seq":1,"concept":"K3-2-u4-C1","difficulty":1,"kind":"mc","stem":"친구에게 한 말과 선생님께 한 말이 달라진 까닭은 무엇인가요?","options":[{"t":"말을 건네는 상대가 달라져서","correct":true},{"t":"빌리려는 물건이 달라져서","mis":"K3-2-u4-X01"},{"t":"말한 시간이 달라져서","mis":"K3-2-u4-X01"},{"t":"지우개가 더 비싸져서","mis":"K3-2-u4-X01"}],"explanation":["빌리려는 것은 지우개 그대로예요.","바뀐 것은 말을 듣는 사람이에요.","상대가 달라지면 말도 달라져요."],"asset":{"type":"speech","turns":[{"who":"친구에게","text":"“민결아, 지우개 좀 빌려줄래?”"},{"who":"선생님께","text":"“선생님, 지우개 좀 빌려주시겠어요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#2','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C1',1,'ox','auto','높임 표현과 대화 예절은 둘 다 상대를 존중하는 일이에요.',ARRAY['K3-2-u4-X04']::text[],false,'{"seq":2,"concept":"K3-2-u4-C1","difficulty":1,"kind":"ox","stem":"높임 표현과 대화 예절은 둘 다 상대를 존중하는 일이에요.","answer":"O","reason_options":[{"t":"상대를 높이고 상대의 마음을 살피는 일이기 때문에","correct":true},{"t":"둘 다 말을 길게 하는 방법이기 때문에","mis":"K3-2-u4-X04"}],"mis":"K3-2-u4-X04","explanation":["이 단원에서 배울 두 가지예요.","하나는 높이고, 하나는 살펴요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#3','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C2',1,'mc','auto','“높임 표현”은 무엇을 나타내는 말인가요?',ARRAY['K3-2-u4-X04','K3-2-u4-X02']::text[],false,'{"seq":3,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"“높임 표현”은 무엇을 나타내는 말인가요?","options":[{"t":"어떤 대상을 높이려는 마음을 나타내는 말","correct":true},{"t":"말을 길게 늘이는 방법","mis":"K3-2-u4-X04"},{"t":"어려운 낱말을 많이 쓰는 방법","mis":"K3-2-u4-X04"},{"t":"나이를 알려 주는 말","mis":"K3-2-u4-X02"}],"explanation":["‘댁’, ‘어디세요’를 떠올려요.","상대를 높이려고 썼어요.","그 안에 존중하는 마음이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#4','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',1,'mc','auto','높임 표현은 누구에게 쓰는 말일까요?',ARRAY['K3-2-u4-X02','K3-2-u4-X03']::text[],false,'{"seq":4,"concept":"K3-2-u4-C3","difficulty":1,"kind":"mc","stem":"높임 표현은 누구에게 쓰는 말일까요?","options":[{"t":"어떤 곳에서 어떤 사이로 말하는지 살펴서 쓴다","correct":true},{"t":"나보다 나이가 많은 사람에게만 쓴다","mis":"K3-2-u4-X02"},{"t":"친구에게는 한 번도 쓰지 않는다","mis":"K3-2-u4-X02"},{"t":"친구에게도 언제나 쓴다","mis":"K3-2-u4-X03"}],"explanation":["학급 회의에서도 높임말을 써요.","처음 만난 사이에서도 써요.","나이표가 아니라 곳과 사이를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#5','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C6',2,'blank','auto','이웃 어른께 물을 때 “(　)이 어디세요?”의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":5,"concept":"K3-2-u4-C6","difficulty":2,"kind":"blank","stem":"이웃 어른께 물을 때 “(　)이 어디세요?”의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"댁","correct":true},{"t":"집","mis":"K3-2-u4-X07"},{"t":"방","mis":"K3-2-u4-X07"},{"t":"곳","mis":"K3-2-u4-X07"}],"explanation":["친구에게는 “집이 어디야?”라고 했어요.","어른께는 ‘집’을 높인 낱말을 써요.","‘댁’이에요."],"asset":{"type":"speech","turns":[{"who":"친구에게","text":"“희찬아, 집이 어디야?”"},{"who":"이웃 어른께","text":"“댁이 어디세요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#6','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'match','auto','장면과 높임 표현을 쓴 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u4-C3","difficulty":2,"kind":"match","stem":"장면과 높임 표현을 쓴 까닭을 알맞게 이으세요.","pairs":[{"l":"㉮ 할머니께 편지를 드릴 때","r":"웃어른께 말씀드려서"},{"l":"㉯ 학급 회의에서 친구에게","r":"여러 사람 앞에서 하는 회의라서"},{"l":"㉰ 처음 만난 친구들 앞에서","r":"아직 가깝지 않은 사이라서"},{"l":"㉱ 할머니께서 선생님께","r":"나이와 관계없이 존중을 나타내려고"}],"mis":"K3-2-u4-X02","explanation":["넷 가운데 웃어른은 하나뿐이에요.","곳과 사이가 까닭인 것도 있어요.","나이만 보지 않아요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#7','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','㉯에서 친구에게 높임말을 쓴 것이 알맞은 까닭은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X03','K3-2-u4-X04']::text[],false,'{"seq":7,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"㉯에서 친구에게 높임말을 쓴 것이 알맞은 까닭은 무엇인가요?","options":[{"t":"여러 사람 앞에서 하는 회의라서","correct":true},{"t":"그 친구가 나보다 나이가 많아서","mis":"K3-2-u4-X02"},{"t":"친구에게도 언제나 높임말을 써야 해서","mis":"K3-2-u4-X03"},{"t":"높임말을 쓰면 말이 길어져서","mis":"K3-2-u4-X04"}],"explanation":["그 친구의 나이가 바뀐 것은 아니에요.","바뀐 것은 말하는 곳이에요.","회의라서 높임말을 써요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#8','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'ox','auto','㉱에서 할머니께서 선생님께 높임 표현을 쓰신 것은 선생님이 할머니보다 나이가 많으시기 때문이에요.',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":8,"concept":"K3-2-u4-C3","difficulty":2,"kind":"ox","stem":"㉱에서 할머니께서 선생님께 높임 표현을 쓰신 것은 선생님이 할머니보다 나이가 많으시기 때문이에요.","answer":"X","reason_options":[{"t":"나이가 아니라 어떤 사이인지 살펴 존중을 나타내신 것이기 때문에","correct":true},{"t":"높임 표현은 나이가 많은 사람에게만 쓰기 때문에","mis":"K3-2-u4-X02"}],"mis":"K3-2-u4-X02","explanation":["선생님은 할머니보다 어리세요.","그래도 높임 표현을 쓰셨어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#9','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','높임 표현을 쓰면 좋은 때로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X10']::text[],false,'{"seq":9,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"높임 표현을 쓰면 좋은 때로 알맞지 않은 것은 무엇인가요?","options":[{"t":"나보다 키가 큰 사람에게 말할 때","correct":true},{"t":"학급 회의에서 의견을 말할 때","mis":"K3-2-u4-X02"},{"t":"처음 만난 사람과 이야기할 때","mis":"K3-2-u4-X02"},{"t":"웃어른께 말씀드릴 때","mis":"K3-2-u4-X10"}],"explanation":["곳·사이·마음을 떠올려요.","키는 그 셋에 들지 않아요.","키 큰 사람이 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_basic#10','kor',3,2,'u4','L02','g3_2_kor_u4_L02_basic','lesson_basic','K3-2-u4-C3',3,'error','auto','높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":10,"concept":"K3-2-u4-C3","difficulty":3,"kind":"error","stem":"높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「높임말은 나보다 나이 많은 사람에게만 쓰는 말이야.」","correct":true,"mis_target":"K3-2-u4-X02"},{"t":"친구 가 — 「학급 회의에서는 친구에게도 높임말을 써.」","mis":"K3-2-u4-X02"},{"t":"친구 나 — 「처음 만난 사이에서도 높임 표현을 써.」","mis":"K3-2-u4-X02"}],"explanation":["높임말은 나이표가 아니에요.","회의와 처음 만난 사이에도 써요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#1','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C6',2,'sa','auto','‘집’을 높여 이르는 한 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C6","difficulty":2,"kind":"sa","stem":"‘집’을 높여 이르는 한 글자 낱말을 쓰세요.","answer":["댁"],"explanation":["이웃 어른께 물을 때 썼어요.","“○이 어디세요?”","‘댁’이에요."],"mis":"K3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#2','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C1',2,'mc','auto','“야, 그거 이리 줘. 빨리.”와 “지웅아, 혹시 손이 비어 있어? 같이 옮겨 줄 수 있을까?”에서 달랐던 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X16']::text[],false,'{"seq":2,"concept":"K3-2-u4-C1","difficulty":2,"kind":"mc","stem":"“야, 그거 이리 줘. 빨리.”와 “지웅아, 혹시 손이 비어 있어? 같이 옮겨 줄 수 있을까?”에서 달랐던 것은 무엇인가요?","options":[{"t":"부탁하는 말과 상대를 대하는 마음","correct":true},{"t":"부탁하는 내용","mis":"K3-2-u4-X18"},{"t":"옮기려는 상자의 크기","mis":"K3-2-u4-X18"},{"t":"지웅이가 들어주었는지 아닌지","mis":"K3-2-u4-X16"}],"explanation":["둘 다 상자를 옮겨 달라고 했어요.","부르는 말과 부탁하는 말이 달라요.","마음이 말에 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#3','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'mc','auto','높임 표현을 쓸지 고를 때 함께 살피는 세 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X21','K3-2-u4-X04']::text[],false,'{"seq":3,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"높임 표현을 쓸지 고를 때 함께 살피는 세 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"어떤 곳에서 · 어떤 사이로 · 어떤 마음을","correct":true},{"t":"나이 · 키 · 힘","mis":"K3-2-u4-X02"},{"t":"시간 · 날씨 · 목소리 크기","mis":"K3-2-u4-X21"},{"t":"말 길이 · 낱말 수 · 글씨","mis":"K3-2-u4-X04"}],"explanation":["회의·발표는 곳이에요.","웃어른·처음 만난 사이는 사이예요.","존중은 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#4','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'ox','auto','학급 회의에서 친구에게 높임말을 썼다면, 쉬는 시간에도 그 친구에게 언제나 높임말을 써야 해요.',ARRAY['K3-2-u4-X03']::text[],false,'{"seq":4,"concept":"K3-2-u4-C3","difficulty":3,"kind":"ox","stem":"학급 회의에서 친구에게 높임말을 썼다면, 쉬는 시간에도 그 친구에게 언제나 높임말을 써야 해요.","answer":"X","reason_options":[{"t":"높임 표현은 곳과 사이에 따라 달라져, 쉬는 시간 친구 사이에는 쓰지 않아도 되기 때문에","correct":true},{"t":"한 번 높인 사람은 언제나 높여야 하기 때문에","mis":"K3-2-u4-X03"}],"mis":"K3-2-u4-X03","explanation":["회의는 여러 사람 앞이에요.","쉬는 시간은 친구 사이예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#5','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',3,'error','auto','㉰에서 은후가 높임 표현을 쓴 까닭을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":5,"concept":"K3-2-u4-C3","difficulty":3,"kind":"error","stem":"㉰에서 은후가 높임 표현을 쓴 까닭을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「은후가 우리보다 나이가 많아서 높임 표현을 썼어.」","correct":true,"mis_target":"K3-2-u4-X02"},{"t":"친구 가 — 「처음 만난 사이라서 높임 표현을 썼어.」","mis":"K3-2-u4-X02"},{"t":"친구 다 — 「여러 친구 앞에서 하는 인사라서이기도 해.」","mis":"K3-2-u4-X02"}],"explanation":["은후는 같은 반에 온 친구예요.","처음 만난 사이이고 여럿 앞이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#6','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C2',3,'mc','auto','㉮~㉱의 높임 표현에 공통으로 담겨 있는 마음은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X04']::text[],false,'{"seq":6,"concept":"K3-2-u4-C2","difficulty":3,"kind":"mc","stem":"㉮~㉱의 높임 표현에 공통으로 담겨 있는 마음은 무엇인가요?","options":[{"t":"상대를 존중하는 마음","correct":true},{"t":"나이를 알리려는 마음","mis":"K3-2-u4-X02"},{"t":"말을 길게 하려는 마음","mis":"K3-2-u4-X04"},{"t":"어려운 말을 자랑하려는 마음","mis":"K3-2-u4-X04"}],"explanation":["네 장면의 상대는 다 달라요.","그래도 모두 상대를 높였어요.","존중하는 마음이에요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#7','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C1',3,'match','auto','이 단원에서 배울 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C1","difficulty":3,"kind":"match","stem":"이 단원에서 배울 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"높임 표현","r":"“빌려주시겠어요?”처럼 상대를 높이는 말"},{"l":"대화 예절","r":"상대의 마음을 살피며 말하고 듣는 것"},{"l":"상황","r":"어떤 곳에서 어떤 사이로 말하는가"}],"mis":"K3-2-u4-X01","explanation":["두 가지를 배워요.","둘 다 상황을 살펴요.","셋을 하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#8','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',4,'mc','auto','원준이의 할머니께서 담임 선생님께 높임 표현을 쓰신 것을 보고 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X03']::text[],false,'{"seq":8,"concept":"K3-2-u4-C3","difficulty":4,"kind":"mc","stem":"원준이의 할머니께서 담임 선생님께 높임 표현을 쓰신 것을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"높임 표현은 나이가 많고 적음만이 아니라 어떤 사이인지를 살펴 쓰는 말이다","correct":true},{"t":"담임 선생님이 할머니보다 나이가 많으시다","mis":"K3-2-u4-X02"},{"t":"할머니께서 높임 표현을 잘못 쓰셨다","mis":"K3-2-u4-X02"},{"t":"높임 표현은 어른끼리만 쓰는 말이다","mis":"K3-2-u4-X03"}],"explanation":["할머니께서 더 나이가 많으세요.","그래도 선생님을 높이셨어요.","사이를 살핀 거예요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#9','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C3',4,'essay','teacher','「높임말은 나보다 나이 많은 사람에게만 쓰는 말이야.」라고 말한 친구에게 내 생각을 쓰고, ㉯와 ㉱ 가운데 하나를 예로 들어 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C3","difficulty":4,"kind":"essay","stem":"「높임말은 나보다 나이 많은 사람에게만 쓰는 말이야.」라고 말한 친구에게 내 생각을 쓰고, ㉯와 ㉱ 가운데 하나를 예로 들어 까닭을 쓰세요.","answer_guide":{"answer":"예: 나이 많은 사람에게만 쓰는 말이 아니다. 높임 표현은 어떤 곳에서 어떤 사이로 말하는지를 살펴 쓴다. ㉯에서는 나이가 같은 친구에게도 여러 사람 앞에서 하는 학급 회의라서 높임말을 썼다. ㉱에서는 할머니께서 할머니보다 나이가 어린 선생님께 존중을 나타내려고 높임 표현을 쓰셨다.","scoring_points":["나이 많은 사람에게만 쓰는 말이 아니라고 썼는가","곳·사이·마음을 살핀다고 썼는가","㉯나 ㉱를 예로 들어 까닭을 썼는가"]},"explanation":["높임말은 나이표가 아니에요.","곳과 사이를 떠올려요.","장면 하나로 까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 집에서 — “할머니께 보내 드릴 편지를 썼어요. 잘 받으실까요?”","㉯ 학급 회의에서 — “혜온 친구, 이 문제를 어떻게 생각하시는지","말씀해 주세요.” / “네, 제 생각을 말씀드리겠습니다.”","㉰ 처음 만난 날 — “안녕하세요? 오늘부터 우리 반에서 함께 지내게 된","은후입니다. 잘 부탁드립니다.”","㉱ 복도에서 — 원준이의 할머니께서 담임 선생님을 만나셨어요.","“선생님, 안녕하세요? 원준이 할머니입니다. 늘 애쓰시지요?”"],"title":"높임 표현이 쓰인 장면 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L02_challenge#10','kor',3,2,'u4','L02','g3_2_kor_u4_L02_challenge','lesson_challenge','K3-2-u4-C1',4,'essay','teacher','지우개를 빌리는 두 말이 달라진 까닭을 쓰고, 같은 부탁을 처음 만난 옆 반 친구에게 한다면 어떻게 말할지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C1","difficulty":4,"kind":"essay","stem":"지우개를 빌리는 두 말이 달라진 까닭을 쓰고, 같은 부탁을 처음 만난 옆 반 친구에게 한다면 어떻게 말할지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 말을 건네는 상대가 친구와 선생님으로 달라져서 말이 달라졌다. 처음 만난 옆 반 친구에게는 “안녕? 혹시 지우개 좀 빌려줄 수 있어요?”처럼 부드럽게 묻는다. 아직 가깝지 않은 사이라 상대를 존중하는 마음을 나타내고 싶기 때문이다.","scoring_points":["상대가 달라져서라고 썼는가","처음 만난 친구에게 할 말을 썼는가","아직 가깝지 않은 사이라는 까닭을 썼는가"]},"explanation":["바뀐 것은 상대예요.","처음 만난 사이를 떠올려요.","존중하는 마음을 담아요."],"asset":{"type":"speech","turns":[{"who":"친구에게","text":"“민결아, 지우개 좀 빌려줄래?”"},{"who":"선생님께","text":"“선생님, 지우개 좀 빌려주시겠어요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#1','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C4',1,'mc','auto','“할머니께서 오신다”에서 ‘-시-’는 누구를 높이나요?',ARRAY['K3-2-u4-X05','K3-2-u4-X08']::text[],false,'{"seq":1,"concept":"K3-2-u4-C4","difficulty":1,"kind":"mc","stem":"“할머니께서 오신다”에서 ‘-시-’는 누구를 높이나요?","options":[{"t":"오는 일을 하는 할머니","correct":true},{"t":"말하는 나","mis":"K3-2-u4-X05"},{"t":"할머니께서 오시는 곳","mis":"K3-2-u4-X05"},{"t":"이 말을 듣는 친구","mis":"K3-2-u4-X08"}],"explanation":["‘-시-’는 움직임 안에 들어가요.","오는 사람이 누구인지 봐요.","할머니를 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#2','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C5',1,'blank','auto','“이 편지를 할머니(　) 보내 드릴 거예요.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X06']::text[],false,'{"seq":2,"concept":"K3-2-u4-C5","difficulty":1,"kind":"blank","stem":"“이 편지를 할머니(　) 보내 드릴 거예요.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"께","correct":true},{"t":"에게","mis":"K3-2-u4-X06"},{"t":"가","mis":"K3-2-u4-X06"},{"t":"께서","mis":"K3-2-u4-X06"}],"explanation":["편지를 받는 분은 할머니예요.","‘에게’ 대신 쓰는 말이 있어요.","‘께’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#3','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C6',1,'match','auto','보통 쓰는 말과 높임의 뜻이 있는 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u4-C6","difficulty":1,"kind":"match","stem":"보통 쓰는 말과 높임의 뜻이 있는 말을 알맞게 이으세요.","pairs":[{"l":"나이","r":"연세"},{"l":"이름","r":"성함"},{"l":"있다","r":"계시다"},{"l":"자다","r":"주무시다"}],"mis":"K3-2-u4-X07","explanation":["뜻은 같아요.","웃어른께 쓰는 말이 따로 있어요.","통째로 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#4','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C7',1,'ox','auto','“먼저 갈게”를 “먼저 갈게요”로 바꾸면 이 말을 듣는 사람을 높여요.',ARRAY['K3-2-u4-X09']::text[],false,'{"seq":4,"concept":"K3-2-u4-C7","difficulty":1,"kind":"ox","stem":"“먼저 갈게”를 “먼저 갈게요”로 바꾸면 이 말을 듣는 사람을 높여요.","answer":"O","reason_options":[{"t":"말끝의 ‘요’는 듣는 사람을 높이기 때문에","correct":true},{"t":"‘요’는 말 속에 나오는 물건을 높이기 때문에","mis":"K3-2-u4-X09"}],"mis":"K3-2-u4-X09","explanation":["말끝에 ‘요’가 붙었어요.","듣는 사람을 높이는 방법이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#5','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C8',2,'mc','auto','높임 표현은 어떻게 써야 바르게 쓰는 것일까요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":5,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"높임 표현은 어떻게 써야 바르게 쓰는 것일까요?","options":[{"t":"높이는 대상이 사람일 때 쓴다","correct":true},{"t":"말끝마다 ‘-시-’를 빠짐없이 붙인다","mis":"K3-2-u4-X09"},{"t":"어려우니까 아예 쓰지 않는다","mis":"K3-2-u4-X10"},{"t":"비싼 물건일수록 높여 말한다","mis":"K3-2-u4-X09"}],"explanation":["높이는 것은 사람이에요.","많이 붙인다고 바른 말이 아니에요.","안 쓰는 것도 답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#6','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','쪽지의 “우산이 있으세요?”가 어색한 까닭은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X09','K3-2-u4-X08']::text[],false,'{"seq":6,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"쪽지의 “우산이 있으세요?”가 어색한 까닭은 무엇인가요?","options":[{"t":"사람이 아닌 우산을 높였기 때문에","correct":true},{"t":"선생님을 높였기 때문에","mis":"K3-2-u4-X10"},{"t":"‘-시-’를 하나만 붙였기 때문에","mis":"K3-2-u4-X09"},{"t":"말끝에 ‘요’를 붙였기 때문에","mis":"K3-2-u4-X08"}],"explanation":["‘있으세요’의 주인을 찾아요.","있는 것은 우산이에요.","물건은 높이지 않아요."],"asset":{"type":"passage","lines":["“선생님, 교실에 우산이 있으세요? 제가 두고 갔어.”"],"title":"어딘가 어색한 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#7','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',2,'mc','auto','쪽지의 “제가 두고 갔어.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X10','K3-2-u4-X08']::text[],false,'{"seq":7,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"쪽지의 “제가 두고 갔어.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“제가 두고 갔어요.”","correct":true},{"t":"“제가 두고 가셨어요.”","mis":"K3-2-u4-X11"},{"t":"그대로 둔다 — 내가 한 일이라서","mis":"K3-2-u4-X10"},{"t":"“제가 두고 갔음.”","mis":"K3-2-u4-X08"}],"explanation":["듣는 분은 선생님이에요.","말끝을 높여요.","나는 높이지 않아요."],"asset":{"type":"passage","lines":["“선생님, 교실에 우산이 있으세요? 제가 두고 갔어.”"],"title":"어딘가 어색한 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#8','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C7',2,'mc','auto','말을 듣는 사람을 높이는 방법은 무엇인가요?',ARRAY['K3-2-u4-X08','K3-2-u4-X09']::text[],false,'{"seq":8,"concept":"K3-2-u4-C7","difficulty":2,"kind":"mc","stem":"말을 듣는 사람을 높이는 방법은 무엇인가요?","options":[{"t":"말끝에 ‘-습니다’나 ‘요’를 붙인다","correct":true},{"t":"‘이/가’ 대신 ‘께서’를 쓴다","mis":"K3-2-u4-X08"},{"t":"움직임을 나타내는 말에 ‘-시-’를 넣는다","mis":"K3-2-u4-X08"},{"t":"물건 이름 뒤에 ‘님’을 붙인다","mis":"K3-2-u4-X09"}],"explanation":["네 방법 가운데 하나만 달라요.","셋은 말 속의 사람을 높여요.","말끝은 듣는 사람을 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#9','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C6',2,'mc','auto','“할머니께서 방에서 주무시고 계세요.”에서 높임 표현이 아닌 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X07','K3-2-u4-X08']::text[],false,'{"seq":9,"concept":"K3-2-u4-C6","difficulty":2,"kind":"mc","stem":"“할머니께서 방에서 주무시고 계세요.”에서 높임 표현이 아닌 것은 무엇인가요?","options":[{"t":"방에서","correct":true},{"t":"께서","mis":"K3-2-u4-X06"},{"t":"주무시고","mis":"K3-2-u4-X07"},{"t":"계세요","mis":"K3-2-u4-X08"}],"explanation":["한 문장에 여러 방법이 있어요.","께서·주무시고·계세요가 그래요.","‘방에서’는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_basic#10','kor',3,2,'u4','L03','g3_2_kor_u4_L03_basic','lesson_basic','K3-2-u4-C9',3,'error','auto','기현이의 쪽지를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X06','K3-2-u4-X07']::text[],false,'{"seq":10,"concept":"K3-2-u4-C9","difficulty":3,"kind":"error","stem":"기현이의 쪽지를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「4번 “두셨어요”는 선생님을 높인 말이라 그대로 두면 돼.」","correct":true,"mis_target":"K3-2-u4-X11"},{"t":"친구 가 — 「3번 “선생님이”는 “선생님께서”로 고쳐야 해.」","mis":"K3-2-u4-X06"},{"t":"친구 나 — 「5번 “안녕히 있어요”는 “안녕히 계세요”로 고쳐야 해.」","mis":"K3-2-u4-X07"}],"explanation":["줄넘기를 둔 사람은 기현이예요.","나를 높이면 안 돼요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 선생님, 안녕하세요? 저는 3학년 기현입니다.","2 어제 빌려주신 줄넘기를 돌려드리러 왔어요.","3 그런데 선생님이 교실에 안 계셔서 쪽지를 써서 놓고 가요.","4 줄넘기는 사물함 위에 두셨어요.","5 빌려주셔서 고맙습니다. 안녕히 있어요."],"title":"기현이가 옆 반 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#1','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C6',2,'sa','auto','‘자다’를 높여 이르는 낱말을 ‘-다’로 끝나게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C6","difficulty":2,"kind":"sa","stem":"‘자다’를 높여 이르는 낱말을 ‘-다’로 끝나게 쓰세요.","answer":["주무시다"],"explanation":["할머니께서 방에서 ○○○고 계세요.","웃어른께 쓰는 말이에요.","‘주무시다’예요."],"mis":"K3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#2','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C5',2,'mc','auto','“형이 말했다”를 아버지로 바꾸어 높일 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X10']::text[],false,'{"seq":2,"concept":"K3-2-u4-C5","difficulty":2,"kind":"mc","stem":"“형이 말했다”를 아버지로 바꾸어 높일 때 알맞은 것은 무엇인가요?","options":[{"t":"“아버지께서 말씀하셨다”","correct":true},{"t":"“아버지가 말했다”","mis":"K3-2-u4-X06"},{"t":"“아버지께 말했다”","mis":"K3-2-u4-X06"},{"t":"“아버지께서 말했다”","mis":"K3-2-u4-X10"}],"explanation":["‘이/가’ 대신 ‘께서’를 써요.","움직임에도 높임을 넣어요.","둘 다 들어간 것이 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#3','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C8',3,'ox','auto','“칠판이 깨끗하시네요”는 칠판까지 높였으니 더 공손한 말이에요.',ARRAY['K3-2-u4-X09']::text[],false,'{"seq":3,"concept":"K3-2-u4-C8","difficulty":3,"kind":"ox","stem":"“칠판이 깨끗하시네요”는 칠판까지 높였으니 더 공손한 말이에요.","answer":"X","reason_options":[{"t":"높이는 것은 사람이고 물건에는 높임말을 쓰지 않기 때문에","correct":true},{"t":"높임말은 많이 붙일수록 공손하기 때문에","mis":"K3-2-u4-X09"}],"mis":"K3-2-u4-X09","explanation":["깨끗한 것은 칠판이에요.","칠판은 사람이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#4','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C9',3,'mc','auto','기현이의 쪽지에서 고쳐야 할 곳을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X09','K3-2-u4-X08']::text[],false,'{"seq":4,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"기현이의 쪽지에서 고쳐야 할 곳을 바르게 모은 것은 무엇인가요?","options":[{"t":"3번 ‘선생님이’, 4번 ‘두셨어요’, 5번 ‘안녕히 있어요’","correct":true},{"t":"3번 ‘선생님이’ 하나뿐","mis":"K3-2-u4-X11"},{"t":"2번 ‘돌려드리러’와 5번 ‘고맙습니다’","mis":"K3-2-u4-X09"},{"t":"1번 ‘안녕하세요’와 4번 ‘두셨어요’","mis":"K3-2-u4-X08"}],"explanation":["줄마다 누구를 높이는지 봐요.","선생님·나·헤어질 때 남는 분.","셋을 고쳐요."],"asset":{"type":"passage","lines":["1 선생님, 안녕하세요? 저는 3학년 기현입니다.","2 어제 빌려주신 줄넘기를 돌려드리러 왔어요.","3 그런데 선생님이 교실에 안 계셔서 쪽지를 써서 놓고 가요.","4 줄넘기는 사물함 위에 두셨어요.","5 빌려주셔서 고맙습니다. 안녕히 있어요."],"title":"기현이가 옆 반 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#5','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C4',3,'mc','auto','‘-시-’를 넣어 고쳐야 하는 문장은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X09']::text[],false,'{"seq":5,"concept":"K3-2-u4-C4","difficulty":3,"kind":"mc","stem":"‘-시-’를 넣어 고쳐야 하는 문장은 무엇인가요?","options":[{"t":"“할아버지께서 신문을 읽는다.”","correct":true},{"t":"“동생이 신문을 읽는다.”","mis":"K3-2-u4-X11"},{"t":"“내가 신문을 읽는다.”","mis":"K3-2-u4-X11"},{"t":"“신문이 탁자 위에 있다.”","mis":"K3-2-u4-X09"}],"explanation":["읽는 사람이 누구인지 봐요.","높일 분은 할아버지예요.","‘읽으신다’로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#6','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C7',3,'error','auto','높임을 나타내는 네 가지 방법을 정리했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X08','K3-2-u4-X06','K3-2-u4-X07']::text[],false,'{"seq":6,"concept":"K3-2-u4-C7","difficulty":3,"kind":"error","stem":"높임을 나타내는 네 가지 방법을 정리했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘-습니다’도 ‘-시-’처럼 움직이는 사람을 높여.」","correct":true,"mis_target":"K3-2-u4-X08"},{"t":"친구 가 — 「‘께서’는 ‘이/가’ 대신 써서 높여.」","mis":"K3-2-u4-X06"},{"t":"친구 나 — 「‘성함’처럼 낱말 자체에 높임이 담긴 것도 있어.」","mis":"K3-2-u4-X07"}],"explanation":["‘-습니다’는 말끝에 붙어요.","말끝은 듣는 사람을 높여요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#7','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C8',3,'mc','auto','쪽지의 “교실에 우산이 있으세요?”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":7,"concept":"K3-2-u4-C8","difficulty":3,"kind":"mc","stem":"쪽지의 “교실에 우산이 있으세요?”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“교실에 우산이 있나요?”","correct":true},{"t":"“교실에 우산이 계세요?”","mis":"K3-2-u4-X09"},{"t":"“교실에 우산님이 있으세요?”","mis":"K3-2-u4-X09"},{"t":"“교실에 우산 있어?”","mis":"K3-2-u4-X10"}],"explanation":["우산은 높이지 않아요.","듣는 선생님은 말끝으로 높여요.","‘있나요’가 알맞아요."],"asset":{"type":"passage","lines":["“선생님, 교실에 우산이 있으세요? 제가 두고 갔어.”"],"title":"어딘가 어색한 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#8','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C9',4,'mc','auto','한 친구가 「높임 표현은 어려우니까 웃어른께도 친구에게 말하듯 할래.」라고 했어요. 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10','K3-2-u4-X04']::text[],false,'{"seq":8,"concept":"K3-2-u4-C9","difficulty":4,"kind":"mc","stem":"한 친구가 「높임 표현은 어려우니까 웃어른께도 친구에게 말하듯 할래.」라고 했어요. 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“높일 사람이 누구인지 먼저 찾고, 그 사람에게 맞는 방법을 쓰면 돼.”","correct":true},{"t":"“말끝마다 ‘-시-’를 다 붙이면 틀릴 일이 없어.”","mis":"K3-2-u4-X09"},{"t":"“맞아, 안 쓰는 게 제일 안 틀려.”","mis":"K3-2-u4-X10"},{"t":"“어려운 낱말을 많이 쓰면 높임이 돼.”","mis":"K3-2-u4-X04"}],"explanation":["양쪽 끝은 다 답이 아니에요.","높일 사람을 먼저 찾아요.","그 사람에게만 맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#9','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C8',4,'essay','teacher','「높임말은 많이 붙일수록 공손한 말이야.」라는 말에 대한 내 생각을 쓰고, “칠판이 깨끗하시네요”를 예로 들어 바르게 쓰는 방법을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C8","difficulty":4,"kind":"essay","stem":"「높임말은 많이 붙일수록 공손한 말이야.」라는 말에 대한 내 생각을 쓰고, “칠판이 깨끗하시네요”를 예로 들어 바르게 쓰는 방법을 쓰세요.","answer_guide":{"answer":"예: 많이 붙일수록 공손한 것이 아니다. 높이는 것은 사람이라 물건이나 일에는 높임말을 쓰지 않는다. “칠판이 깨끗하시네요”는 사람이 아닌 칠판을 높여서 어색하다. “칠판이 깨끗하네요”처럼 칠판은 높이지 않고, 듣는 사람은 말끝의 ‘요’로 높이면 바르다.","scoring_points":["많이 붙인다고 공손한 것이 아니라고 썼는가","사람만 높인다고 썼는가","칠판 문장을 바르게 고쳤는가"]},"explanation":["높이는 것은 사람이에요.","칠판은 사람이 아니에요.","듣는 분은 말끝으로 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L03_challenge#10','kor',3,2,'u4','L03','g3_2_kor_u4_L03_challenge','lesson_challenge','K3-2-u4-C9',4,'essay','teacher','기현이의 쪽지에서 고쳐야 할 곳 세 군데를 찾아 바르게 고치고, 각각 누구를 높여야(높이지 않아야) 하기 때문인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"기현이의 쪽지에서 고쳐야 할 곳 세 군데를 찾아 바르게 고치고, 각각 누구를 높여야(높이지 않아야) 하기 때문인지 쓰세요.","answer_guide":{"answer":"예: 3번 “선생님이” → “선생님께서” — 말 속의 선생님을 높여야 하기 때문이다. 4번 “두셨어요” → “두었어요” — 줄넘기를 둔 사람은 기현이 자신이라 높이지 않아야 하기 때문이다. 5번 “안녕히 있어요” → “안녕히 계세요” — 남아 있는 분이 선생님이라 ‘있다’ 대신 높임의 뜻이 있는 ‘계시다’를 써야 하기 때문이다.","scoring_points":["고칠 곳 세 군데를 찾았는가","바르게 고쳤는가","누구를 높이는지로 까닭을 썼는가"]},"explanation":["줄마다 누구를 높일지 봐요.","나를 높인 곳도 있어요.","높임 낱말도 떠올려요."],"asset":{"type":"passage","lines":["1 선생님, 안녕하세요? 저는 3학년 기현입니다.","2 어제 빌려주신 줄넘기를 돌려드리러 왔어요.","3 그런데 선생님이 교실에 안 계셔서 쪽지를 써서 놓고 가요.","4 줄넘기는 사물함 위에 두셨어요.","5 빌려주셔서 고맙습니다. 안녕히 있어요."],"title":"기현이가 옆 반 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#1','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C10',1,'mc','auto','민결이가 그날부터 고개만 숙이고 빠르게 지나간 까닭은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":1,"concept":"K3-2-u4-C10","difficulty":1,"kind":"mc","stem":"민결이가 그날부터 고개만 숙이고 빠르게 지나간 까닭은 무엇인가요?","options":[{"t":"말이 틀릴까 봐 건네지 않기로 해서","correct":true},{"t":"옆집 어른이 미워져서","mis":"K3-2-u4-X33"},{"t":"학교에 늦어서 뛰어가느라","mis":"K3-2-u4-X33"},{"t":"희찬이와 다투어서","mis":"K3-2-u4-X33"}],"explanation":["민결이는 얼굴이 뜨거워졌어요.","그다음에 인사를 그만두었어요.","틀릴까 봐 말을 안 건넨 거예요."],"asset":{"type":"passage","lines":["민결이는 아침마다 신발장 앞에서 옆집 어른을 만났어요.","어른은 늘 먼저 웃어 주셨어요.","“안녕하세요? 지금 어디 가?” 민결이가 말했어요. 말끝이 그만 툭 떨어졌어요.","옆에 있던 희찬이가 큭 웃었어요. “너 말이 좀 이상해.”","민결이는 얼굴이 뜨거워졌어요.","그날부터 민결이는 고개만 꾸벅 숙이고 빠르게 지나갔어요.","인사를 안 하니 마음이 편할 줄 알았는데,","신발장 앞을 지날 때마다 자꾸 걸음이 빨라졌어요."],"title":"이야기 「서툰 인사」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#2','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C9',1,'mc','auto','민결이가 처음 옆집 어른께 한 말 가운데 어긋난 곳은 어디인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X12','K3-2-u4-X33']::text[],false,'{"seq":2,"concept":"K3-2-u4-C9","difficulty":1,"kind":"mc","stem":"민결이가 처음 옆집 어른께 한 말 가운데 어긋난 곳은 어디인가요?","options":[{"t":"“지금 어디 가?”","correct":true},{"t":"“안녕하세요?”","mis":"K3-2-u4-X10"},{"t":"어른께 먼저 인사한 것","mis":"K3-2-u4-X12"},{"t":"신발장 앞에서 말한 것","mis":"K3-2-u4-X33"}],"explanation":["듣는 분은 어른이에요.","말끝이 툭 떨어졌어요.","“어디 가세요?”로 고쳐요."],"asset":{"type":"passage","lines":["민결이는 아침마다 신발장 앞에서 옆집 어른을 만났어요.","어른은 늘 먼저 웃어 주셨어요.","“안녕하세요? 지금 어디 가?” 민결이가 말했어요. 말끝이 그만 툭 떨어졌어요.","옆에 있던 희찬이가 큭 웃었어요. “너 말이 좀 이상해.”","민결이는 얼굴이 뜨거워졌어요.","그날부터 민결이는 고개만 꾸벅 숙이고 빠르게 지나갔어요.","인사를 안 하니 마음이 편할 줄 알았는데,","신발장 앞을 지날 때마다 자꾸 걸음이 빨라졌어요."],"title":"이야기 「서툰 인사」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#3','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C11',1,'mc','auto','선생님의 말씀을 기현이에게 옮길 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X14']::text[],false,'{"seq":3,"concept":"K3-2-u4-C11","difficulty":1,"kind":"mc","stem":"선생님의 말씀을 기현이에게 옮길 때 알맞은 것은 무엇인가요?","options":[{"t":"“선생님께서 너 오라고 하셔.”","correct":true},{"t":"“선생님이 너 오래.”","mis":"K3-2-u4-X14"},{"t":"“선생님께서 너 오시래.”","mis":"K3-2-u4-X14"},{"t":"“선생님이 너 오셔.”","mis":"K3-2-u4-X14"}],"explanation":["부르신 분은 선생님이에요.","옮길 때에도 선생님을 높여요.","오는 사람은 기현이에요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"선생님께서 기현이를 부르셨어요. 그 말을 기현이에게 옮겨 주었어요."},{"who":"옮겨 준 친구","text":"“기현아, 선생님이 너 오래.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#4','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C12',1,'match','auto','「서툰 인사」에 나온 낱말 짝과 그 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C12","difficulty":1,"kind":"match","stem":"「서툰 인사」에 나온 낱말 짝과 그 관계를 알맞게 이으세요.","pairs":[{"l":"운동화 — 신발","r":"한 낱말이 다른 낱말의 뜻을 포함하는 관계"},{"l":"묻다 — 대답하다","r":"서로 뜻이 반대인 관계"},{"l":"돕다 — 거들다","r":"서로 뜻이 비슷한 관계"}],"mis":"K3-2-u4-X15","explanation":["운동화는 신발의 한 가지예요.","묻고 대답하는 것은 반대예요.","돕다와 거들다는 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#5','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C10',2,'mc','auto','“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”라는 어른의 말씀에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u4-X13','K3-2-u4-X12','K3-2-u4-X33']::text[],false,'{"seq":5,"concept":"K3-2-u4-C10","difficulty":2,"kind":"mc","stem":"“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”라는 어른의 말씀에서 알 수 있는 것은 무엇인가요?","options":[{"t":"서툴러도 말을 건네는 것이 상대를 살피는 일이다","correct":true},{"t":"한 글자도 틀리지 않아야 인사를 해도 된다","mis":"K3-2-u4-X13"},{"t":"헷갈릴 때에는 말하지 않는 것이 가장 낫다","mis":"K3-2-u4-X12"},{"t":"어른께는 인사를 하지 않아도 된다","mis":"K3-2-u4-X33"}],"explanation":["어른은 무엇이 고맙다고 하셨나요?","바르게 말해서가 아니에요.","말을 건네서예요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#6','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C3',2,'mc','auto','학급 회의에서 민결이가 친구 혜온이에게 높임말을 쓴 까닭은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X33','K3-2-u4-X03']::text[],false,'{"seq":6,"concept":"K3-2-u4-C3","difficulty":2,"kind":"mc","stem":"학급 회의에서 민결이가 친구 혜온이에게 높임말을 쓴 까닭은 무엇인가요?","options":[{"t":"여럿이 모여 회의를 하는 곳이라서","correct":true},{"t":"혜온이가 갑자기 나이가 많아져서","mis":"K3-2-u4-X02"},{"t":"친구들에게 잘 보이고 싶어서","mis":"K3-2-u4-X33"},{"t":"친구에게는 언제나 높임말을 써야 해서","mis":"K3-2-u4-X03"}],"explanation":["민결이가 속으로 한 생각을 읽어요.","나이가 바뀐 것이 아니에요.","말하는 곳이 바뀌었어요."],"asset":{"type":"passage","lines":["며칠 뒤, 민결이가 학급 회의에서 이야기를 이끄는 일을 맡았어요.","“혜온 친구, 어떻게 생각하시는지 말씀해 주세요.”","민결이는 제 목소리가 낯설었어요. 늘 같이 뛰노는 친구인데요.","친구들이 손을 들고 차례를 기다렸어요.","민결이가 묻고 친구들이 대답하는 동안, 교실이 조용하고 단단해졌어요.","‘혜온이가 갑자기 나보다 나이가 많아진 것도 아닌데.’","민결이는 속으로 생각했어요."],"title":"이야기 「서툰 인사」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#7','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C9',2,'ox','auto','민결이가 한 말 “우리 엄마가 이거 갖다주래요.”는 고쳐야 해요.',ARRAY['K3-2-u4-X09']::text[],false,'{"seq":7,"concept":"K3-2-u4-C9","difficulty":2,"kind":"ox","stem":"민결이가 한 말 “우리 엄마가 이거 갖다주래요.”는 고쳐야 해요.","answer":"O","reason_options":[{"t":"말 속에 나오는 어머니를 높이지 않았기 때문에","correct":true},{"t":"떡 봉지를 높이지 않았기 때문에","mis":"K3-2-u4-X09"}],"mis":"K3-2-u4-X09","explanation":["말끝은 ‘요’로 높였어요.","말 속의 어머니는 높이지 않았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#8','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C12',2,'mc','auto','「서툰 인사」에서 ‘돕다’와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":8,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"「서툰 인사」에서 ‘돕다’와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"거들다","correct":true},{"t":"묻다","mis":"K3-2-u4-X15"},{"t":"대답하다","mis":"K3-2-u4-X15"},{"t":"신발","mis":"K3-2-u4-X15"}],"explanation":["민결이가 짐을 보고 한 말을 봐요.","“제가 좀 ○○ 드릴까요?”","‘거들다’예요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#9','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C11',2,'blank','auto','선생님께서 기현이를 부르셨어요. “기현아, 선생님(　) 너 오라고 하셔.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X06']::text[],false,'{"seq":9,"concept":"K3-2-u4-C11","difficulty":2,"kind":"blank","stem":"선생님께서 기현이를 부르셨어요. “기현아, 선생님(　) 너 오라고 하셔.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"께서","correct":true},{"t":"이","mis":"K3-2-u4-X14"},{"t":"께","mis":"K3-2-u4-X06"},{"t":"에게","mis":"K3-2-u4-X06"}],"explanation":["부르신 분을 높여요.","‘이/가’ 자리에 들어가요.","‘께서’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_basic#10','kor',3,2,'u4','L05','g3_2_kor_u4_L05_basic','lesson_basic','K3-2-u4-C10',3,'error','auto','「서툰 인사」를 읽고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X12','K3-2-u4-X33','K3-2-u4-X13']::text[],false,'{"seq":10,"concept":"K3-2-u4-C10","difficulty":3,"kind":"error","stem":"「서툰 인사」를 읽고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「민결이는 또 틀렸으니 다음부터 인사하지 않는 게 나아.」","correct":true,"mis_target":"K3-2-u4-X12"},{"t":"친구 가 — 「민결이는 틀릴까 봐 말을 안 건넸다가 다시 건넸어.」","mis":"K3-2-u4-X33"},{"t":"친구 다 — 「어른께서는 말을 건넨 것을 고마워하셨어.」","mis":"K3-2-u4-X13"}],"explanation":["이야기는 알아차림으로 끝나요.","서툴러도 건네는 것이 살피는 일이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#1','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C12',2,'sa','auto','「서툰 인사」에서 ‘운동화’의 뜻을 포함하는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C12","difficulty":2,"kind":"sa","stem":"「서툰 인사」에서 ‘운동화’의 뜻을 포함하는 두 글자 낱말을 쓰세요.","answer":["신발"],"explanation":["운동화는 무엇의 한 가지일까요?","민결이는 ○○장 앞에서 어른을 만났어요.","‘신발’이에요."],"mis":"K3-2-u4-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#2','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C11',2,'mc','auto','“기현아, 선생님이 너 오래.”에서 빠진 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X08','K3-2-u4-X33']::text[],false,'{"seq":2,"concept":"K3-2-u4-C11","difficulty":2,"kind":"mc","stem":"“기현아, 선생님이 너 오래.”에서 빠진 것은 무엇인가요?","options":[{"t":"높여야 할 선생님을 높이는 말","correct":true},{"t":"기현이를 높이는 말","mis":"K3-2-u4-X14"},{"t":"말끝의 ‘요’","mis":"K3-2-u4-X08"},{"t":"기현이가 와야 하는 곳","mis":"K3-2-u4-X33"}],"explanation":["부르신 분은 선생님이에요.","옮기면서 높임이 빠졌어요.","선생님을 높여야 해요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"선생님께서 기현이를 부르셨어요. 그 말을 기현이에게 옮겨 주었어요."},{"who":"옮겨 준 친구","text":"“기현아, 선생님이 너 오래.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#3','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C3',3,'mc','auto','민결이가 속으로 한 생각 ‘혜온이가 갑자기 나보다 나이가 많아진 것도 아닌데.’에서 민결이가 알아차린 것은 무엇인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X17']::text[],false,'{"seq":3,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"민결이가 속으로 한 생각 ‘혜온이가 갑자기 나보다 나이가 많아진 것도 아닌데.’에서 민결이가 알아차린 것은 무엇인가요?","options":[{"t":"높임말은 나이가 아니라 어떤 곳에서 어떤 사이로 말하는지에 따라 달라진다","correct":true},{"t":"친구에게 높임말을 쓰는 것은 틀렸다","mis":"K3-2-u4-X02"},{"t":"혜온이가 사실은 나이가 많다","mis":"K3-2-u4-X02"},{"t":"회의에서는 아무 말도 하지 않아야 한다","mis":"K3-2-u4-X17"}],"explanation":["혜온이는 그대로예요.","바뀐 것은 회의라는 곳이에요.","나이표가 아니라는 거예요."],"asset":{"type":"passage","lines":["며칠 뒤, 민결이가 학급 회의에서 이야기를 이끄는 일을 맡았어요.","“혜온 친구, 어떻게 생각하시는지 말씀해 주세요.”","민결이는 제 목소리가 낯설었어요. 늘 같이 뛰노는 친구인데요.","친구들이 손을 들고 차례를 기다렸어요.","민결이가 묻고 친구들이 대답하는 동안, 교실이 조용하고 단단해졌어요.","‘혜온이가 갑자기 나보다 나이가 많아진 것도 아닌데.’","민결이는 속으로 생각했어요."],"title":"이야기 「서툰 인사」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#4','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C10',3,'ox','auto','민결이처럼 서툰 인사를 할 바에는 인사를 하지 않는 편이 상대를 더 존중하는 거예요.',ARRAY['K3-2-u4-X12']::text[],false,'{"seq":4,"concept":"K3-2-u4-C10","difficulty":3,"kind":"ox","stem":"민결이처럼 서툰 인사를 할 바에는 인사를 하지 않는 편이 상대를 더 존중하는 거예요.","answer":"X","reason_options":[{"t":"서툴러도 말을 건네는 것이 상대를 살피는 일이기 때문에","correct":true},{"t":"틀린 말은 상대를 언짢게 하니 하지 않는 것이 낫기 때문에","mis":"K3-2-u4-X12"}],"mis":"K3-2-u4-X12","explanation":["어른은 건넨 말을 고마워하셨어요.","인사를 안 하니 마음이 불편했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#5','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',3,'mc','auto','“우리 엄마가 이거 갖다주래요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X06','K3-2-u4-X10']::text[],false,'{"seq":5,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"“우리 엄마가 이거 갖다주래요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“저희 어머니께서 갖다드리라고 하셨어요.”","correct":true},{"t":"“우리 엄마가 이거 갖다주셨어요.”","mis":"K3-2-u4-X11"},{"t":"“저희 어머니가 갖다주래요.”","mis":"K3-2-u4-X06"},{"t":"“우리 엄마가 이거 갖다주래.”","mis":"K3-2-u4-X10"}],"explanation":["어머니를 높여요.","받으시는 분은 옆집 어른이에요.","듣는 분께는 말끝도 높여요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#6','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C9',3,'match','auto','민결이가 한 말과 바르게 고친 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u4-C9","difficulty":3,"kind":"match","stem":"민결이가 한 말과 바르게 고친 말을 알맞게 이으세요.","pairs":[{"l":"“지금 어디 가?”","r":"“어디 가세요?”"},{"l":"“우리 엄마가”","r":"“저희 어머니께서”"},{"l":"“갖다주래요”","r":"“갖다드리라고 하셨어요”"}],"mis":"K3-2-u4-X08","explanation":["듣는 분은 어른이에요.","말 속의 어머니도 높여요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#7','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C12',3,'error','auto','「서툰 인사」의 낱말 관계를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":7,"concept":"K3-2-u4-C12","difficulty":3,"kind":"error","stem":"「서툰 인사」의 낱말 관계를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘묻다’와 ‘대답하다’는 뜻이 비슷한 관계야.」","correct":true,"mis_target":"K3-2-u4-X15"},{"t":"친구 가 — 「‘돕다’와 ‘거들다’는 뜻이 비슷해.」","mis":"K3-2-u4-X15"},{"t":"친구 나 — 「‘신발’은 ‘운동화’의 뜻을 포함해.」","mis":"K3-2-u4-X15"}],"explanation":["묻는 것과 대답하는 것은 반대예요.","비슷한 관계가 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#8','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C11',4,'mc','auto','짝이 “교장 선생님께서 우리 반에 오신대.”라고 알려 주었어요. 이 말을 어머니께 옮길 때 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X08','K3-2-u4-X33']::text[],false,'{"seq":8,"concept":"K3-2-u4-C11","difficulty":4,"kind":"mc","stem":"짝이 “교장 선생님께서 우리 반에 오신대.”라고 알려 주었어요. 이 말을 어머니께 옮길 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"“교장 선생님께서 우리 반에 오신대요.”","correct":true},{"t":"“교장 선생님이 우리 반에 온대요.”","mis":"K3-2-u4-X14"},{"t":"“교장 선생님께서 우리 반에 오신대.”","mis":"K3-2-u4-X08"},{"t":"“교장 선생님께서 우리 반에 오셨어요.”","mis":"K3-2-u4-X33"}],"explanation":["교장 선생님은 그대로 높여요.","듣는 분은 어머니예요.","말끝도 ‘요’로 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#9','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C10',4,'essay','teacher','「서툰 인사」의 처음과 끝에서 민결이가 어떻게 달라졌는지 쓰고, 이 이야기에서 알게 된 것을 내 생각과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C10","difficulty":4,"kind":"essay","stem":"「서툰 인사」의 처음과 끝에서 민결이가 어떻게 달라졌는지 쓰고, 이 이야기에서 알게 된 것을 내 생각과 함께 쓰세요.","answer_guide":{"answer":"예: 처음에 민결이는 인사말이 틀리자 부끄러워서 고개만 숙이고 지나갔다. 끝에서는 짐이 많은 어른께 먼저 말을 건네며 도와드리겠다고 했다. 조금 서툴러도 말을 건네는 것이 상대를 살피는 일이라는 것을 알게 되었다. 나도 헷갈릴 때 말을 안 하기보다 먼저 건네 보고 싶다.","scoring_points":["처음 모습을 썼는가","끝에서 달라진 모습을 썼는가","서툴러도 말을 건네는 것의 뜻을 썼는가"]},"explanation":["처음과 끝의 신발장 앞을 견줘요.","민결이가 다시 한 일을 찾아요.","어른의 말씀을 떠올려요."],"asset":{"type":"passage","lines":["집으로 가는 길, 민결이는 신발장 앞에서 옆집 어른을 또 만났어요.","어른은 짐이 많아 보였어요. 민결이는 걸음을 늦췄어요.","“안녕하세요? 제가 좀 거들어 드릴까요?”","“우리 엄마가 이거 갖다주래요.” 민결이가 떡 봉지를 내밀며 말했어요.","말하고 나서 또 어딘가 어긋난 것 같았어요.","어른이 고개를 끄덕이셨어요.","“말을 건네 주어 고맙구나. 조금 서툴러도 괜찮다.”","민결이는 천천히 걸어 나왔어요. 운동화 끈이 풀린 줄도 몰랐어요."],"title":"이야기 「서툰 인사」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L05_challenge#10','kor',3,2,'u4','L05','g3_2_kor_u4_L05_challenge','lesson_challenge','K3-2-u4-C12',4,'essay','teacher','「서툰 인사」에 나온 낱말 짝 셋의 관계를 쓰고, 관계마다 내가 아는 다른 낱말 짝을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C12","difficulty":4,"kind":"essay","stem":"「서툰 인사」에 나온 낱말 짝 셋의 관계를 쓰고, 관계마다 내가 아는 다른 낱말 짝을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 운동화 — 신발은 한 낱말이 다른 낱말의 뜻을 포함하는 관계, 묻다 — 대답하다는 뜻이 반대인 관계, 돕다 — 거들다는 뜻이 비슷한 관계이다. 내가 만든 짝 — 포함: 과일 — 사과, 반대: 열다 — 닫다, 비슷: 기쁘다 — 즐겁다.","scoring_points":["세 짝의 관계를 바르게 썼는가","관계마다 새 짝을 만들었는가","새 짝의 관계가 맞는가"]},"explanation":["포함·반대·비슷이에요.","이야기 속 짝부터 써요.","새 짝도 관계가 맞아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#1','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',1,'mc','auto','지웅이가 준오와 온서에게 한 대답이 달랐던 까닭은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X33']::text[],false,'{"seq":1,"concept":"K3-2-u4-C14","difficulty":1,"kind":"mc","stem":"지웅이가 준오와 온서에게 한 대답이 달랐던 까닭은 무엇인가요?","options":[{"t":"부탁하는 방법이 달라서","correct":true},{"t":"부탁한 내용이 달라서","mis":"K3-2-u4-X18"},{"t":"부탁한 시간이 달라서","mis":"K3-2-u4-X18"},{"t":"지웅이가 온서와 더 친해서","mis":"K3-2-u4-X33"}],"explanation":["두 사람이 옮겨 달라고 한 것은 같은 상자예요.","말하는 방법이 달랐어요.","그래서 대답도 달랐어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#2','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',1,'mc','auto','“대화 예절”은 무엇인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X17','K3-2-u4-X21']::text[],false,'{"seq":2,"concept":"K3-2-u4-C13","difficulty":1,"kind":"mc","stem":"“대화 예절”은 무엇인가요?","options":[{"t":"말을 주고받을 때 상대를 배려하고 존중하며 지키는 것","correct":true},{"t":"남의 부탁을 모두 들어주는 것","mis":"K3-2-u4-X16"},{"t":"내 생각은 말하지 않는 것","mis":"K3-2-u4-X17"},{"t":"목소리를 가장 크게 내는 것","mis":"K3-2-u4-X21"}],"explanation":["말하는 사람과 듣는 사람이 있어요.","서로 주고받을 때 지켜요.","배려하고 존중하는 마음이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#3','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C15',1,'ox','auto','부탁을 들어줄 수 없을 때 거절하는 것은 예절을 어기는 것이에요.',ARRAY['K3-2-u4-X16']::text[],false,'{"seq":3,"concept":"K3-2-u4-C15","difficulty":1,"kind":"ox","stem":"부탁을 들어줄 수 없을 때 거절하는 것은 예절을 어기는 것이에요.","answer":"X","reason_options":[{"t":"거절할 때에도 미안한 마음과 까닭을 말하면 예절을 지키는 것이기 때문에","correct":true},{"t":"예절을 지키려면 부탁은 모두 들어주어야 하기 때문에","mis":"K3-2-u4-X16"}],"mis":"K3-2-u4-X16","explanation":["들어줄 수 없을 때도 있어요.","거절은 잘못이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#4','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',1,'match','auto','온서가 한 말·행동과 그것이 보여 준 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u4-C14","difficulty":1,"kind":"match","stem":"온서가 한 말·행동과 그것이 보여 준 것을 알맞게 이으세요.","pairs":[{"l":"“지웅아”","r":"상대를 부르는 말"},{"l":"“줄 수 있을까?”","r":"시키지 않고 묻는 부탁하는 말"},{"l":"상대를 보며 말함","r":"말하는 태도"}],"mis":"K3-2-u4-X18","explanation":["이름을 불렀어요.","시키지 않고 물었어요.","상대를 보았어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#5','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C15',2,'mc','auto','부탁을 들어줄 수 없을 때에는 어떻게 말할까요?',ARRAY['K3-2-u4-X16','K3-2-u4-X19']::text[],false,'{"seq":5,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"부탁을 들어줄 수 없을 때에는 어떻게 말할까요?","options":[{"t":"미안한 마음과 까닭을 함께 말한다","correct":true},{"t":"예절을 지키려면 부탁은 모두 들어준다","mis":"K3-2-u4-X16"},{"t":"“안 돼.”라고 짧게만 말한다","mis":"K3-2-u4-X19"},{"t":"못 들은 척하고 지나간다","mis":"K3-2-u4-X19"}],"explanation":["상대가 오해하지 않게 해요.","미안한 마음을 말해요.","왜 못 하는지도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#6','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C13',2,'mc','auto','대화할 때 지킬 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X26']::text[],false,'{"seq":6,"concept":"K3-2-u4-C13","difficulty":2,"kind":"mc","stem":"대화할 때 지킬 것으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 사람의 마음을 헤아리며 말하기","correct":true},{"t":"목소리를 가장 크게 내기","mis":"K3-2-u4-X21"},{"t":"말을 가장 빨리 끝내기","mis":"K3-2-u4-X21"},{"t":"내 말만 먼저 다 하기","mis":"K3-2-u4-X26"}],"explanation":["예절은 상대를 살피는 일이에요.","크기와 빠르기가 아니에요.","마음을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#7','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',2,'mc','auto','지웅이가 준오에게 “네가 나한테 시키듯이 말해서 들어 주고 싶지 않았어.”라고 했어요. 준오의 부탁에서 문제였던 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X21']::text[],false,'{"seq":7,"concept":"K3-2-u4-C14","difficulty":2,"kind":"mc","stem":"지웅이가 준오에게 “네가 나한테 시키듯이 말해서 들어 주고 싶지 않았어.”라고 했어요. 준오의 부탁에서 문제였던 것은 무엇인가요?","options":[{"t":"시키듯이 한 부탁하는 말","correct":true},{"t":"상자를 옮겨 달라고 한 것","mis":"K3-2-u4-X18"},{"t":"지웅이를 부른 시간","mis":"K3-2-u4-X18"},{"t":"목소리가 작았던 것","mis":"K3-2-u4-X21"}],"explanation":["지웅이의 말에 답이 있어요.","부탁 내용은 괜찮았어요.","시키듯이 말한 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#8','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C14',2,'ox','auto','말하는 태도는 말이 아니니 대화 예절과 상관없어요.',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":8,"concept":"K3-2-u4-C14","difficulty":2,"kind":"ox","stem":"말하는 태도는 말이 아니니 대화 예절과 상관없어요.","answer":"X","reason_options":[{"t":"턱을 들거나 상대를 보며 말하는 태도에도 마음이 드러나기 때문에","correct":true},{"t":"대화 예절은 말의 내용에만 드러나기 때문에","mis":"K3-2-u4-X18"}],"mis":"K3-2-u4-X18","explanation":["준오는 턱을 들고 말했어요.","온서는 상대를 보며 말했어요.","태도도 예절이라 X예요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#9','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C15',2,'mc','auto','지웅이가 온서에게 “복도 끝까지만 들어 줘도 될까?”라고 한 것은 어떤 말인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X33','K3-2-u4-X18']::text[],false,'{"seq":9,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"지웅이가 온서에게 “복도 끝까지만 들어 줘도 될까?”라고 한 것은 어떤 말인가요?","options":[{"t":"할 수 있는 만큼과 그 까닭을 말한 것","correct":true},{"t":"예절을 어기고 거절한 것","mis":"K3-2-u4-X16"},{"t":"온서가 싫어서 피한 것","mis":"K3-2-u4-X33"},{"t":"시키듯이 말한 것","mis":"K3-2-u4-X18"}],"explanation":["지웅이는 곧 급식 당번이에요.","그래서 복도 끝까지만이라고 했어요.","할 수 있는 만큼을 말했어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_basic#10','kor',3,2,'u4','L07','g3_2_kor_u4_L07_basic','lesson_basic','K3-2-u4-C15',3,'error','auto','들어줄 수 없는 부탁을 받았을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X19']::text[],false,'{"seq":10,"concept":"K3-2-u4-C15","difficulty":3,"kind":"error","stem":"들어줄 수 없는 부탁을 받았을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「예절 바른 사람은 부탁을 다 들어줘야 해.」","correct":true,"mis_target":"K3-2-u4-X16"},{"t":"친구 나 — 「미안한 마음을 먼저 말하면 좋아.」","mis":"K3-2-u4-X19"},{"t":"친구 다 — 「왜 도와줄 수 없는지도 말해야 해.」","mis":"K3-2-u4-X19"}],"explanation":["거절은 잘못이 아니에요.","마음과 까닭을 말하면 돼요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#1','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',2,'sa','auto','예절이 드러나는 세 가지는 부르는 말, 부탁하는 말, 말하는 (　)예요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C14","difficulty":2,"kind":"sa","stem":"예절이 드러나는 세 가지는 부르는 말, 부탁하는 말, 말하는 (　)예요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["태도"],"explanation":["턱을 들고 / 상대를 보며","말이 아닌 모습이에요.","‘태도’예요."],"mis":"K3-2-u4-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#2','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C13',2,'mc','auto','대화 예절에서 가장 먼저 필요한 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X04','K3-2-u4-X16']::text[],false,'{"seq":2,"concept":"K3-2-u4-C13","difficulty":2,"kind":"mc","stem":"대화 예절에서 가장 먼저 필요한 것은 무엇인가요?","options":[{"t":"상대를 배려하고 존중하려는 마음","correct":true},{"t":"큰 목소리","mis":"K3-2-u4-X21"},{"t":"어려운 낱말","mis":"K3-2-u4-X04"},{"t":"부탁을 다 들어주는 버릇","mis":"K3-2-u4-X16"}],"explanation":["그 마음이 말에 드러나요.","말투와 표정에도 드러나요.","배려하고 존중하는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#3','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',3,'mc','auto','준오의 “야, 그거 이리 줘. 빨리.”를 예절 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X03']::text[],false,'{"seq":3,"concept":"K3-2-u4-C14","difficulty":3,"kind":"mc","stem":"준오의 “야, 그거 이리 줘. 빨리.”를 예절 바르게 고친 것은 무엇인가요?","options":[{"t":"“지웅아, 바쁘지 않으면 이것 좀 같이 옮겨 줄 수 있어?”","correct":true},{"t":"“지웅아, 그거 이리 줘. 빨리.”","mis":"K3-2-u4-X18"},{"t":"“야, 그거 이리 주시겠어요?”","mis":"K3-2-u4-X03"},{"t":"“그거.” 하고 손가락으로 가리킨다","mis":"K3-2-u4-X18"}],"explanation":["부르는 말을 바꿔요.","시키지 말고 물어요.","친구에게 높임말까지는 필요 없어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#4','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',3,'ox','auto','지웅이가 “복도 끝까지만”이라고 말한 것은 부탁을 다 들어주지 않았으니 예절에 어긋나요.',ARRAY['K3-2-u4-X16']::text[],false,'{"seq":4,"concept":"K3-2-u4-C15","difficulty":3,"kind":"ox","stem":"지웅이가 “복도 끝까지만”이라고 말한 것은 부탁을 다 들어주지 않았으니 예절에 어긋나요.","answer":"X","reason_options":[{"t":"할 수 있는 만큼과 까닭을 말해 상대를 살폈기 때문에","correct":true},{"t":"예절은 부탁을 남김없이 들어주는 것이기 때문에","mis":"K3-2-u4-X16"}],"mis":"K3-2-u4-X16","explanation":["지웅이에게는 급식 당번이 있었어요.","할 수 있는 만큼을 말했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#5','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',3,'mc','auto','짝이 “쉬는 시간에 내 그림 좀 대신 색칠해 줄래?”라고 했는데 들어줄 수 없어요. 가장 알맞은 대답은 무엇인가요?',ARRAY['K3-2-u4-X19','K3-2-u4-X16']::text[],false,'{"seq":5,"concept":"K3-2-u4-C15","difficulty":3,"kind":"mc","stem":"짝이 “쉬는 시간에 내 그림 좀 대신 색칠해 줄래?”라고 했는데 들어줄 수 없어요. 가장 알맞은 대답은 무엇인가요?","options":[{"t":"“미안해, 쉬는 시간에 우유 당번이라 어려워. 색칠할 곳은 같이 봐 줄게.”","correct":true},{"t":"“싫어.”","mis":"K3-2-u4-X19"},{"t":"“응…….” 하고 억지로 해 준다","mis":"K3-2-u4-X16"},{"t":"대답하지 않고 자리를 뜬다","mis":"K3-2-u4-X19"}],"explanation":["미안한 마음을 말해요.","까닭을 말해요.","할 수 있는 만큼도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#6','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',3,'error','auto','준오와 온서의 부탁을 견주어 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":6,"concept":"K3-2-u4-C14","difficulty":3,"kind":"error","stem":"준오와 온서의 부탁을 견주어 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「지웅이는 온서랑 더 친해서 들어준 거야.」","correct":true,"mis_target":"K3-2-u4-X18"},{"t":"친구 가 — 「온서는 이름을 불러 주었어.」","mis":"K3-2-u4-X18"},{"t":"친구 나 — 「온서는 시키지 않고 물어보았어.」","mis":"K3-2-u4-X18"}],"explanation":["지웅이가 까닭을 말했어요.","시키듯이 말해서라고 했어요.","친구 다가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#7','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',3,'match','auto','지웅이가 온서에게 한 말과 그 말에 담긴 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C15","difficulty":3,"kind":"match","stem":"지웅이가 온서에게 한 말과 그 말에 담긴 것을 알맞게 이으세요.","pairs":[{"l":"“응, 그럴게.”","r":"들어줄 수 있다는 마음"},{"l":"“나 곧 급식 당번이라”","r":"모두 할 수 없는 까닭"},{"l":"“복도 끝까지만 들어 줘도 될까?”","r":"할 수 있는 만큼"}],"mis":"K3-2-u4-X19","explanation":["지웅이는 한 번에 세 가지를 말했어요.","마음·까닭·할 수 있는 만큼이에요.","하나씩 이어요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#8','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',4,'mc','auto','들어줄 수 없는 부탁인데 아무 말 없이 억지로 들어주기만 하면 어떤 일이 생길까요?',ARRAY['K3-2-u4-X16','K3-2-u4-X19']::text[],false,'{"seq":8,"concept":"K3-2-u4-C15","difficulty":4,"kind":"mc","stem":"들어줄 수 없는 부탁인데 아무 말 없이 억지로 들어주기만 하면 어떤 일이 생길까요?","options":[{"t":"내가 해야 할 일을 못 하게 되고, 상대는 내 사정을 모른 채 지나간다","correct":true},{"t":"언제나 모두가 기분이 좋아진다","mis":"K3-2-u4-X16"},{"t":"예절을 가장 잘 지킨 것이 된다","mis":"K3-2-u4-X16"},{"t":"상대가 내 사정을 저절로 알게 된다","mis":"K3-2-u4-X19"}],"explanation":["억지로 들어주면 내 일이 밀려요.","말하지 않으면 상대는 몰라요.","마음과 까닭을 말해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#9','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C14',4,'essay','teacher','준오와 온서의 부탁에서 달랐던 세 가지를 쓰고, 준오의 부탁을 예절 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C14","difficulty":4,"kind":"essay","stem":"준오와 온서의 부탁에서 달랐던 세 가지를 쓰고, 준오의 부탁을 예절 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 부르는 말이 “야”와 “지웅아”로 달랐고, 부탁하는 말이 “이리 줘”와 “옮겨 줄 수 있을까?”로 달랐으며, 태도가 턱을 들고 말한 것과 상대를 보며 말한 것으로 달랐다. 고친 말 — (지웅이를 보며) “지웅아, 손이 비어 있으면 이 상자 좀 같이 옮겨 줄 수 있어?”","scoring_points":["부르는 말을 견주었는가","부탁하는 말과 태도를 견주었는가","세 가지를 살려 고쳐 썼는가"]},"explanation":["내용은 같았어요.","부르는 말·부탁하는 말·태도예요.","셋을 다 고쳐요."],"asset":{"type":"speech","turns":[{"who":"준오","text":"(턱을 들고) “야, 그거 이리 줘. 빨리.”"},{"who":"지웅","text":"“내가 왜? 나 지금 할 일 있어.”"},{"who":"준오","text":"“치사하게. 안 해 주면 그만이지.”"},{"who":"온서","text":"“지웅아, 혹시 손이 비어 있어? 이 상자를 같이 옮겨 줄 수 있을까?”"},{"who":"지웅","text":"“응, 그럴게. 그런데 나 곧 급식 당번이라 복도 끝까지만 들어 줘도 될까?”"},{"who":"온서","text":"“물론이지. 같이 들어 줘서 고마워.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L07_challenge#10','kor',3,2,'u4','L07','g3_2_kor_u4_L07_challenge','lesson_challenge','K3-2-u4-C15',4,'essay','teacher','부탁을 들어줄 수 없을 때 지킬 대화 예절을 쓰고, 친구가 “방과 후에 같이 놀자.”고 했는데 학원에 가야 할 때 할 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C15","difficulty":4,"kind":"essay","stem":"부탁을 들어줄 수 없을 때 지킬 대화 예절을 쓰고, 친구가 “방과 후에 같이 놀자.”고 했는데 학원에 가야 할 때 할 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 미안한 마음을 말하고 도와줄 수 없는 까닭을 함께 말한다. 할 말 — “미안해. 오늘은 방과 후에 학원에 가야 해서 놀 수가 없어. 내일 쉬는 시간에 같이 놀자.” 까닭을 말해야 친구가 내가 싫어서 거절했다고 생각하지 않기 때문이다.","scoring_points":["미안한 마음과 까닭을 말한다고 썼는가","상황에 맞는 말을 썼는가","그렇게 말하는 까닭을 썼는가"]},"explanation":["거절은 잘못이 아니에요.","마음과 까닭을 함께 말해요.","친구 마음을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#1','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',1,'mc','auto','목소리 크기는 같은데 지웅이의 반응이 달랐던 까닭은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X21','K3-2-u4-X18']::text[],false,'{"seq":1,"concept":"K3-2-u4-C16","difficulty":1,"kind":"mc","stem":"목소리 크기는 같은데 지웅이의 반응이 달랐던 까닭은 무엇인가요?","options":[{"t":"말하는 곳이 달라져서","correct":true},{"t":"지웅이의 기분이 달라져서","mis":"K3-2-u4-X22"},{"t":"목소리가 더 커져서","mis":"K3-2-u4-X21"},{"t":"부르는 말이 달라져서","mis":"K3-2-u4-X18"}],"explanation":["운동장과 도서관을 견줘요.","부르는 말도 목소리도 같았어요.","곳이 달라졌어요."],"asset":{"type":"speech","turns":[{"who":"운동장에서","text":"“지웅아, 모자 떨어졌어!” → “아, 고마워! 멀리서도 잘 들리네.”"},{"who":"도서관에서","text":"“지웅아, 이것 봐!” → “여기서는 조금 작게 말해 줘.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#2','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',1,'match','auto','상황을 이루는 것과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u4-C16","difficulty":1,"kind":"match","stem":"상황을 이루는 것과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"대화 상대","r":"누구와 말하는가"},{"l":"시간과 장소","r":"언제 어디에서 말하는가"},{"l":"목적과 방식","r":"무엇을 하려고, 어떻게 말하는가"}],"mis":"K3-2-u4-X22","explanation":["상황은 세 가지로 살펴요.","누구와·어디에서·무엇을 하려고.","이 셋이 바뀌면 예절도 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#3','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',1,'mc','auto','상황 ㉮에서 원준이가 예절에 어긋난 것은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X22']::text[],false,'{"seq":3,"concept":"K3-2-u4-C17","difficulty":1,"kind":"mc","stem":"상황 ㉮에서 원준이가 예절에 어긋난 것은 무엇인가요?","options":[{"t":"누운 채 보지도 않고 대충 대답한 것","correct":true},{"t":"말끝에 ‘요’를 붙이지 않은 것","mis":"K3-2-u4-X23"},{"t":"물뿌리개가 어디 있는지 몰랐던 것","mis":"K3-2-u4-X23"},{"t":"할머니께서 먼저 물으신 것","mis":"K3-2-u4-X22"}],"explanation":["원준이는 “있어요”라고 했어요.","말끝은 높였어요.","자세와 태도가 어긋났어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“원준아, 물뿌리개가 어디 있니?”"},{"who":"원준","text":"(소파에 누운 채, 화면만 보며) “거기 있어요.”"},{"who":"할머니","text":"“원준아, 할머니가 물었을 때에는…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#4','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C18',1,'ox','auto','전화를 걸면 내가 누구인지 먼저 밝혀요.',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":4,"concept":"K3-2-u4-C18","difficulty":1,"kind":"ox","stem":"전화를 걸면 내가 누구인지 먼저 밝혀요.","answer":"O","reason_options":[{"t":"상대가 얼굴을 볼 수 없어 누가 걸었는지 모르기 때문에","correct":true},{"t":"전화는 길게 할수록 좋기 때문에","mis":"K3-2-u4-X25"}],"mis":"K3-2-u4-X25","explanation":["전화는 얼굴이 안 보여요.","눈으로 알 것을 말로 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#5','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'mc','auto','상황 ㉯에서 원준이의 말이 알맞지 않았던 까닭은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X24','K3-2-u4-X18']::text[],false,'{"seq":5,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"상황 ㉯에서 원준이의 말이 알맞지 않았던 까닭은 무엇인가요?","options":[{"t":"함께 정하려는 것과 상관없는 말이라서","correct":true},{"t":"목소리가 너무 작아서","mis":"K3-2-u4-X21"},{"t":"물어보는 말을 써서","mis":"K3-2-u4-X24"},{"t":"혜온이의 이름을 불러서","mis":"K3-2-u4-X18"}],"explanation":["모둠은 그림 붙일 곳을 정하고 있었어요.","원준이는 몇 교시인지 물었어요.","상관없는 말이었어요."],"asset":{"type":"speech","turns":[{"who":"혜온","text":"“우리 모둠 그림은 어디에 붙일까?”"},{"who":"원준","text":"“혜온아, 그런데 오늘 몇 교시까지 하지?”"},{"who":"혜온","text":"“우리 지금 모둠 것 정하는 중이야.”"},{"who":"원준","text":"“아, 미안. 다시 얘기하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#6','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C17',2,'mc','auto','상황 ㉰에서 기현이는 어떤 마음이 들었을까요?',ARRAY['K3-2-u4-X24']::text[],false,'{"seq":6,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"상황 ㉰에서 기현이는 어떤 마음이 들었을까요?","options":[{"t":"함께 있는데 혼자 남겨진 마음","correct":true},{"t":"조용해져서 편안한 마음","mis":"K3-2-u4-X24"},{"t":"놀이가 빨리 정해져 신나는 마음","mis":"K3-2-u4-X24"},{"t":"귓속말이 들리지 않아 고마운 마음","mis":"K3-2-u4-X24"}],"explanation":["셋이 함께 고르던 중이었어요.","두 사람만 귓속말을 했어요.","기현이는 빠진 것 같았어요."],"asset":{"type":"passage","lines":["셋이 모여 무슨 놀이를 할지 고르고 있었어요.","두 사람이 서로에게 귓속말을 했어요.","기현 — “나만 빼고 무슨 얘기 해?”"],"title":"상황 ㉰ 셋이 함께 놀 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#7','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C18',2,'mc','auto','전화로 대화할 때 지킬 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"전화로 대화할 때 지킬 것으로 알맞은 것은 무엇인가요?","options":[{"t":"끊기 전에 끝인사 하기","correct":true},{"t":"받을 때까지 계속 다시 걸기","mis":"K3-2-u4-X25"},{"t":"할 말이 끝나면 바로 끊기","mis":"K3-2-u4-X25"},{"t":"받자마자 내 할 말부터 하기","mis":"K3-2-u4-X25"}],"explanation":["상대는 나를 볼 수 없어요.","끊는다는 것도 말로 알려요.","끝인사를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#8','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C19',2,'mc','auto','모둠 대화에서 지켜야 할 것은 무엇일까요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17','K3-2-u4-X21']::text[],false,'{"seq":8,"concept":"K3-2-u4-C19","difficulty":2,"kind":"mc","stem":"모둠 대화에서 지켜야 할 것은 무엇일까요?","options":[{"t":"끝까지 듣고, 내 생각도 말한다","correct":true},{"t":"내 생각이 옳으니 끝까지 밀고 간다","mis":"K3-2-u4-X26"},{"t":"다툼이 생기지 않게 아무 말도 안 한다","mis":"K3-2-u4-X17"},{"t":"가장 큰 목소리로 먼저 말한다","mis":"K3-2-u4-X21"}],"explanation":["모둠 대화는 함께 답을 찾는 거예요.","듣기만도, 말하기만도 아니에요.","둘 다 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#9','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C16',2,'ox','auto','운동장에서 알맞은 목소리는 도서관에서도 알맞아요.',ARRAY['K3-2-u4-X21']::text[],false,'{"seq":9,"concept":"K3-2-u4-C16","difficulty":2,"kind":"ox","stem":"운동장에서 알맞은 목소리는 도서관에서도 알맞아요.","answer":"X","reason_options":[{"t":"시간과 장소가 달라지면 알맞은 예절도 달라지기 때문에","correct":true},{"t":"큰 목소리는 어디서든 잘 들려 좋기 때문에","mis":"K3-2-u4-X21"}],"mis":"K3-2-u4-X21","explanation":["운동장은 넓고 시끄러워요.","도서관은 조용히 읽는 곳이에요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"운동장에서","text":"“지웅아, 모자 떨어졌어!” → “아, 고마워! 멀리서도 잘 들리네.”"},{"who":"도서관에서","text":"“지웅아, 이것 봐!” → “여기서는 조금 작게 말해 줘.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_basic#10','kor',3,2,'u4','L08','g3_2_kor_u4_L08_basic','lesson_basic','K3-2-u4-C19',3,'error','auto','모둠 대화를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X17','K3-2-u4-X26']::text[],false,'{"seq":10,"concept":"K3-2-u4-C19","difficulty":3,"kind":"error","stem":"모둠 대화를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「말을 안 하면 끼어들 일도 없으니 가장 예절 바른 거야.」","correct":true,"mis_target":"K3-2-u4-X17"},{"t":"친구 가 — 「다른 친구가 말할 때는 끝까지 들어.」","mis":"K3-2-u4-X26"},{"t":"친구 다 — 「내 생각도 한 번은 말해.」","mis":"K3-2-u4-X26"}],"explanation":["모둠 대화는 함께 답을 찾아요.","내 생각이 없으면 함께가 안 돼요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#1','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C16',2,'sa','auto','상황을 이루는 것은 대화 상대, 시간과 장소, 목적과 (　)예요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C16","difficulty":2,"kind":"sa","stem":"상황을 이루는 것은 대화 상대, 시간과 장소, 목적과 (　)예요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["방식"],"explanation":["어떻게 말하는가예요.","직접 만나서? 전화로?","‘방식’이에요."],"mis":"K3-2-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#2','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',2,'mc','auto','전화로 말할 때 눈으로 알 수 있던 것까지 말로 알려 주어야 하는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X25','K3-2-u4-X10']::text[],false,'{"seq":2,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"전화로 말할 때 눈으로 알 수 있던 것까지 말로 알려 주어야 하는 까닭은 무엇인가요?","options":[{"t":"상대가 내 모습을 볼 수 없어서","correct":true},{"t":"전화는 목소리가 크게 들려서","mis":"K3-2-u4-X21"},{"t":"전화는 짧게 끝내야 해서","mis":"K3-2-u4-X25"},{"t":"전화로는 높임말을 쓰지 않아서","mis":"K3-2-u4-X10"}],"explanation":["얼굴도 몸짓도 안 보여요.","누구인지도 안 보여요.","그래서 말로 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#3','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',3,'mc','auto','상황 ㉮의 원준이가 예절에 맞게 대답한 것은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X17']::text[],false,'{"seq":3,"concept":"K3-2-u4-C17","difficulty":3,"kind":"mc","stem":"상황 ㉮의 원준이가 예절에 맞게 대답한 것은 무엇인가요?","options":[{"t":"(일어나 할머니를 보며) “할머니, 물뿌리개는 베란다 문 옆에 있어요.”","correct":true},{"t":"(누운 채) “할머니, 물뿌리개는 베란다 문 옆에 있습니다.”","mis":"K3-2-u4-X23"},{"t":"(화면만 보며) “거기요, 거기.”","mis":"K3-2-u4-X23"},{"t":"대답하지 않고 물뿌리개를 가져다 놓는다","mis":"K3-2-u4-X17"}],"explanation":["말끝만으로는 모자라요.","자세와 눈길도 바꿔요.","어디 있는지 알려 드려요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“원준아, 물뿌리개가 어디 있니?”"},{"who":"원준","text":"(소파에 누운 채, 화면만 보며) “거기 있어요.”"},{"who":"할머니","text":"“원준아, 할머니가 물었을 때에는…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#4','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',3,'ox','auto','상황 ㉰의 귓속말은 다른 사람에게 들리지 않게 작게 말한 것이니 예절을 잘 지킨 거예요.',ARRAY['K3-2-u4-X24']::text[],false,'{"seq":4,"concept":"K3-2-u4-C17","difficulty":3,"kind":"ox","stem":"상황 ㉰의 귓속말은 다른 사람에게 들리지 않게 작게 말한 것이니 예절을 잘 지킨 거예요.","answer":"X","reason_options":[{"t":"셋이 함께 있는데 한 사람을 빼고 말해 혼자 남겨진 마음이 들게 하기 때문에","correct":true},{"t":"작은 목소리는 언제나 예절 바르기 때문에","mis":"K3-2-u4-X24"}],"mis":"K3-2-u4-X24","explanation":["셋이 함께 고르던 중이었어요.","기현이만 빠졌어요.","그래서 X예요."],"asset":{"type":"passage","lines":["셋이 모여 무슨 놀이를 할지 고르고 있었어요.","두 사람이 서로에게 귓속말을 했어요.","기현 — “나만 빼고 무슨 얘기 해?”"],"title":"상황 ㉰ 셋이 함께 놀 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#5','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C16',3,'mc','auto','쉬는 시간 운동장에서 짝과 말할 때와 학급 회의에서 짝과 말할 때 말이 달라지는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X22','K3-2-u4-X02','K3-2-u4-X21']::text[],false,'{"seq":5,"concept":"K3-2-u4-C16","difficulty":3,"kind":"mc","stem":"쉬는 시간 운동장에서 짝과 말할 때와 학급 회의에서 짝과 말할 때 말이 달라지는 까닭은 무엇인가요?","options":[{"t":"대화 상대는 같아도 장소와 목적이 달라 알맞은 말이 달라져서","correct":true},{"t":"짝이 같으니 말도 같아야 한다","mis":"K3-2-u4-X22"},{"t":"회의 때 짝의 나이가 많아져서","mis":"K3-2-u4-X02"},{"t":"회의에서는 목소리만 크게 하면 돼서","mis":"K3-2-u4-X21"}],"explanation":["상대는 같은 짝이에요.","장소와 하려는 일이 달라요.","그래서 말도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#6','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C18',3,'error','auto','전화 예절을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":6,"concept":"K3-2-u4-C18","difficulty":3,"kind":"error","stem":"전화 예절을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「안 받으면 받을 때까지 계속 다시 걸면 돼.」","correct":true,"mis_target":"K3-2-u4-X25"},{"t":"친구 가 — 「지금 통화해도 되는지 먼저 물어.」","mis":"K3-2-u4-X25"},{"t":"친구 나 — 「끊기 전에 끝인사를 해.」","mis":"K3-2-u4-X25"}],"explanation":["상대가 받기 어려운 때일 수 있어요.","다시 걸 때를 정하고 기다려요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#7','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',3,'match','auto','상황과 그때 어긋난 예절을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C17","difficulty":3,"kind":"match","stem":"상황과 그때 어긋난 예절을 알맞게 이으세요.","pairs":[{"l":"㉮ 할머니께서 물으셨을 때","r":"누운 채 보지도 않고 대답함"},{"l":"㉯ 모둠 활동을 하는 중에","r":"정하는 것과 상관없는 말을 함"},{"l":"㉰ 셋이 함께 놀 때","r":"한 사람을 빼고 귓속말을 함"}],"mis":"K3-2-u4-X24","explanation":["상황마다 어긋난 것이 달라요.","자세·상관없는 말·귓속말이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#8','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',4,'mc','auto','모둠에서 한 친구가 아무 말도 하지 않고 있어요. 내가 할 수 있는 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X24','K3-2-u4-X17']::text[],false,'{"seq":8,"concept":"K3-2-u4-C19","difficulty":4,"kind":"mc","stem":"모둠에서 한 친구가 아무 말도 하지 않고 있어요. 내가 할 수 있는 알맞은 말은 무엇인가요?","options":[{"t":"“너는 어떻게 생각해? 천천히 말해도 돼.”","correct":true},{"t":"“말 안 하면 우리끼리 정한다.”","mis":"K3-2-u4-X26"},{"t":"그 친구는 빼고 둘이서 귓속말로 정한다","mis":"K3-2-u4-X24"},{"t":"“조용히 있는 게 제일 예절 바른 거야.”","mis":"K3-2-u4-X17"}],"explanation":["모두의 생각이 필요해요.","말할 기회를 건네요.","기다려 주는 말도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#9','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C17',4,'essay','teacher','상황 ㉯와 ㉰에서 예절에 어긋난 점을 각각 쓰고, 그 상황에서 지켜야 할 대화 예절을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C17","difficulty":4,"kind":"essay","stem":"상황 ㉯와 ㉰에서 예절에 어긋난 점을 각각 쓰고, 그 상황에서 지켜야 할 대화 예절을 쓰세요.","answer_guide":{"answer":"예: ㉯에서 원준이는 모둠이 그림 붙일 곳을 정하는데 몇 교시까지 하는지처럼 상관없는 말을 했다. 함께 정하는 것과 이어지는 말을 해야 한다. ㉰에서 두 사람은 셋이 함께 있는데 기현이를 빼고 귓속말을 했다. 함께 있는 사람이 모두 들을 수 있게 말해야 한다.","scoring_points":["㉯의 어긋난 점을 썼는가","㉰의 어긋난 점을 썼는가","상황마다 지킬 예절을 썼는가"]},"explanation":["㉯는 모둠 활동 중이에요.","㉰는 셋이 함께 있어요.","어긋난 점과 지킬 것을 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L08_challenge#10','kor',3,2,'u4','L08','g3_2_kor_u4_L08_challenge','lesson_challenge','K3-2-u4-C19',4,'essay','teacher','「모둠 대화에서는 다른 사람 말을 끝까지 듣기만 하면 돼.」라는 말에 대한 내 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C19","difficulty":4,"kind":"essay","stem":"「모둠 대화에서는 다른 사람 말을 끝까지 듣기만 하면 돼.」라는 말에 대한 내 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 듣기만 하면 안 된다. 모둠 대화는 이기려는 것이 아니라 함께 답을 찾는 것이라, 다른 사람의 말을 끝까지 듣고 내 생각도 말해야 한다. 모두 듣기만 하면 생각이 모이지 않아 답을 찾을 수 없기 때문이다.","scoring_points":["듣기만 하면 안 된다고 썼는가","끝까지 듣고 내 생각도 말한다고 썼는가","함께 답을 찾는다는 까닭을 썼는가"]},"explanation":["말하지 않는 것은 예절이 아니에요.","듣기와 말하기 둘 다예요.","함께 답을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#1','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',1,'match','auto','상황 ㉯(할머니 화분)를 이루는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C20","difficulty":1,"kind":"match","stem":"상황 ㉯(할머니 화분)를 이루는 것을 알맞게 이으세요.","pairs":[{"l":"대화 상대","r":"할머니"},{"l":"대화 목적","r":"부탁을 거절하려고"},{"l":"대화 방식","r":"직접 만나서 주고받는 대화"}],"mis":"K3-2-u4-X22","explanation":["누구와 말하나요?","무엇을 하려고 말하나요?","어떻게 말하나요?"],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#2','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',1,'mc','auto','전화를 받은 기현이가 “여보세요?” 했어요. 온서가 먼저 해야 할 말은 무엇일까요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":2,"concept":"K3-2-u4-C20","difficulty":1,"kind":"mc","stem":"전화를 받은 기현이가 “여보세요?” 했어요. 온서가 먼저 해야 할 말은 무엇일까요?","options":[{"t":"“나 온서야. 지금 통화해도 돼?”","correct":true},{"t":"“그 책 몇 쪽까지 읽었어?”","mis":"K3-2-u4-X25"},{"t":"“빨리 정하자. 나 시간 없어.”","mis":"K3-2-u4-X25"},{"t":"아무 말 없이 기현이가 말하기를 기다린다","mis":"K3-2-u4-X25"}],"explanation":["기현이는 누가 걸었는지 몰라요.","먼저 누구인지 밝혀요.","통화해도 되는지 물어요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"온서가 함께 읽을 책을 정하려고 기현이에게 전화를 걸었어요."},{"who":"기현","text":"“여보세요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#3','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C15',1,'mc','auto','할머니의 부탁을 들어드릴 수 없는 은후는 어떻게 말하는 것이 좋을까요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19']::text[],false,'{"seq":3,"concept":"K3-2-u4-C15","difficulty":1,"kind":"mc","stem":"할머니의 부탁을 들어드릴 수 없는 은후는 어떻게 말하는 것이 좋을까요?","options":[{"t":"“죄송해요. 지금 나가 봐야 해서요. 다음에 꼭 도와드릴게요.”","correct":true},{"t":"못 해도 하겠다고 말씀드린다","mis":"K3-2-u4-X20"},{"t":"“안 돼요.”라고만 말하고 나간다","mis":"K3-2-u4-X19"},{"t":"못 들은 척하고 나간다","mis":"K3-2-u4-X19"}],"explanation":["웃어른이라 더 어려워요.","죄송한 마음을 말씀드려요.","까닭도 말씀드려요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#4','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',1,'ox','auto','같은 “고맙습니다.”라도 말투와 표정에 따라 듣는 사람의 마음이 달라져요.',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":4,"concept":"K3-2-u4-C21","difficulty":1,"kind":"ox","stem":"같은 “고맙습니다.”라도 말투와 표정에 따라 듣는 사람의 마음이 달라져요.","answer":"O","reason_options":[{"t":"말에 표정·몸짓·말투가 함께 실려 전해지기 때문에","correct":true},{"t":"낱말이 같으면 마음도 언제나 같게 전해지기 때문에","mis":"K3-2-u4-X27"}],"mis":"K3-2-u4-X27","explanation":["웃으며, 화난 목소리로, 딴 곳을 보며.","낱말은 같았어요.","마음은 달랐으니 O예요."],"asset":{"type":"passage","lines":["누군가 나에게 무언가를 내밀었어요.","세 사람이 똑같이 “고맙습니다.”라고 했어요.","① 웃으며 ② 화난 목소리로 ③ 딴 곳을 보며"],"title":"같은 말, 다른 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#5','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',2,'mc','auto','전화는 서로 보이지 않는데, 어떻게 듣고 있다고 알릴까요?',ARRAY['K3-2-u4-X27','K3-2-u4-X26']::text[],false,'{"seq":5,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"전화는 서로 보이지 않는데, 어떻게 듣고 있다고 알릴까요?","options":[{"t":"“응.”, “그렇구나.” 같은 짧은 말로 알린다","correct":true},{"t":"보이지 않으니 아무것도 하지 않는다","mis":"K3-2-u4-X27"},{"t":"보이지 않아도 아주 크게 웃어 보인다","mis":"K3-2-u4-X27"},{"t":"상대 말을 끊고 내 말을 한다","mis":"K3-2-u4-X26"}],"explanation":["상대는 내 고개를 볼 수 없어요.","고개 끄덕임을 말로 바꿔요.","짧은 말이 대신해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#6','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',2,'mc','auto','상황 ㉮(전화로 책 정하기)의 대본에 꼭 들어가야 할 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X26','K3-2-u4-X18']::text[],false,'{"seq":6,"concept":"K3-2-u4-C20","difficulty":2,"kind":"mc","stem":"상황 ㉮(전화로 책 정하기)의 대본에 꼭 들어가야 할 것은 무엇인가요?","options":[{"t":"끊기 전에 하는 끝인사","correct":true},{"t":"상대보다 더 크게 내는 목소리","mis":"K3-2-u4-X21"},{"t":"내 말만 먼저 다 하는 차례","mis":"K3-2-u4-X26"},{"t":"이름 대신 “야”라고 부르는 말","mis":"K3-2-u4-X18"}],"explanation":["전화라서 필요한 것이 있어요.","끊는다는 것도 말로 알려요.","끝인사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#7','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C22',2,'mc','auto','역할놀이 점검표에서 ‘보통’이 나오면 어떻게 할까요?',ARRAY['K3-2-u4-X28']::text[],false,'{"seq":7,"concept":"K3-2-u4-C22","difficulty":2,"kind":"mc","stem":"역할놀이 점검표에서 ‘보통’이 나오면 어떻게 할까요?","options":[{"t":"그 부분을 다음에는 어떻게 할지 생각한다","correct":true},{"t":"다시 ‘매우 잘함’으로 고쳐 적는다","mis":"K3-2-u4-X28"},{"t":"점검표를 덮고 넘어간다","mis":"K3-2-u4-X28"},{"t":"짝의 점검표와 점수를 견준다","mis":"K3-2-u4-X28"}],"explanation":["점검표는 채우려고 보지 않아요.","고칠 곳을 찾으려고 봐요.","다음을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#8','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C21',2,'mc','auto','직접 만나 이야기할 때 ‘듣고 있다’는 말이 되는 것은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X27']::text[],false,'{"seq":8,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"직접 만나 이야기할 때 ‘듣고 있다’는 말이 되는 것은 무엇인가요?","options":[{"t":"상대를 바라보고 하던 일을 멈추기","correct":true},{"t":"화면을 보면서 “응.” 하기","mis":"K3-2-u4-X23"},{"t":"팔짱을 끼고 다른 곳 보기","mis":"K3-2-u4-X27"},{"t":"상대 말이 끝나기 전에 일어나기","mis":"K3-2-u4-X27"}],"explanation":["몸짓도 말이에요.","바라보고, 끄덕이고, 멈춰요.","그것이 듣고 있다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#9','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C15',2,'ox','auto','웃어른의 부탁은 들어드릴 수 없어도 “네, 할게요.”라고 말씀드려야 해요.',ARRAY['K3-2-u4-X20']::text[],false,'{"seq":9,"concept":"K3-2-u4-C15","difficulty":2,"kind":"ox","stem":"웃어른의 부탁은 들어드릴 수 없어도 “네, 할게요.”라고 말씀드려야 해요.","answer":"X","reason_options":[{"t":"들어드릴 수 없으면 죄송한 마음과 까닭을 말씀드리는 것이 예절이기 때문에","correct":true},{"t":"웃어른의 부탁은 거절하면 안 되기 때문에","mis":"K3-2-u4-X20"}],"mis":"K3-2-u4-X20","explanation":["못 하는데 한다고 하면 거짓이 돼요.","할머니는 기다리시게 돼요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_basic#10','kor',3,2,'u4','L10','g3_2_kor_u4_L10_basic','lesson_basic','K3-2-u4-C20',3,'error','auto','상황 ㉮의 전화 대본을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":10,"concept":"K3-2-u4-C20","difficulty":3,"kind":"error","stem":"상황 ㉮의 전화 대본을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「친구끼리 전화니까 누구인지 안 밝혀도 목소리로 다 알아.」","correct":true,"mis_target":"K3-2-u4-X25"},{"t":"친구 가 — 「먼저 ‘나 온서야.’라고 밝혀.」","mis":"K3-2-u4-X25"},{"t":"친구 나 — 「책을 정하면 ‘그럼 내일 보자.’ 하고 끊어.」","mis":"K3-2-u4-X25"}],"explanation":["받는 사람은 누가 걸었는지 몰라요.","친구 사이라도 밝혀요.","친구 다가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"온서가 함께 읽을 책을 정하려고 기현이에게 전화를 걸었어요."},{"who":"기현","text":"“여보세요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#1','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',2,'sa','auto','같은 말이라도 표정·(　)·말투에 따라 듣는 사람의 마음이 달라져요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C21","difficulty":2,"kind":"sa","stem":"같은 말이라도 표정·(　)·말투에 따라 듣는 사람의 마음이 달라져요. 빈칸에 알맞은 두 글자 낱말을 쓰세요.","answer":["몸짓"],"explanation":["고개 끄덕이기, 바라보기.","몸으로 하는 말이에요.","‘몸짓’이에요."],"mis":"K3-2-u4-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#2','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C22',2,'mc','auto','역할놀이를 하고 나서 점검표를 살펴보는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X28']::text[],false,'{"seq":2,"concept":"K3-2-u4-C22","difficulty":2,"kind":"mc","stem":"역할놀이를 하고 나서 점검표를 살펴보는 까닭은 무엇인가요?","options":[{"t":"다음에 고칠 점을 찾으려고","correct":true},{"t":"칸을 빠짐없이 채우려고","mis":"K3-2-u4-X28"},{"t":"누가 잘했는지 등수를 매기려고","mis":"K3-2-u4-X28"},{"t":"선생님께 보여 칭찬받으려고","mis":"K3-2-u4-X28"}],"explanation":["점검표에는 점수가 없어요.","살펴보는 것은 나를 위해서예요.","고칠 점을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#3','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',3,'mc','auto','은후의 말 “죄송해요. 지금 나가 봐야 해서요. 다음에 꼭 도와드릴게요.”에 함께 들어 있는 두 가지는 무엇인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19','K3-2-u4-X16']::text[],false,'{"seq":3,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"은후의 말 “죄송해요. 지금 나가 봐야 해서요. 다음에 꼭 도와드릴게요.”에 함께 들어 있는 두 가지는 무엇인가요?","options":[{"t":"높임 표현과 거절할 때의 대화 예절","correct":true},{"t":"거짓말과 높임 표현","mis":"K3-2-u4-X20"},{"t":"짧은 거절과 반말","mis":"K3-2-u4-X19"},{"t":"부탁 들어주기와 끝인사","mis":"K3-2-u4-X16"}],"explanation":["죄송해요·도와드릴게요는 높임이에요.","마음과 까닭은 대화 예절이에요.","두 가지가 한 문장에 있어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#4','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',3,'ox','auto','전화는 서로 보이지 않으니 표정·말투는 아무 뜻이 없어요.',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":4,"concept":"K3-2-u4-C21","difficulty":3,"kind":"ox","stem":"전화는 서로 보이지 않으니 표정·말투는 아무 뜻이 없어요.","answer":"X","reason_options":[{"t":"목소리의 말투에 마음이 실리고, 짧은 말로 고개 끄덕임을 대신할 수 있기 때문에","correct":true},{"t":"상대가 볼 수 없으면 아무것도 전해지지 않기 때문에","mis":"K3-2-u4-X27"}],"mis":"K3-2-u4-X27","explanation":["목소리에도 표정이 있어요.","“응.”이 끄덕임을 대신해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#5','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',3,'mc','auto','상황 ㉯의 대화 방식이 ‘직접 만나서’라는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X22','K3-2-u4-X19']::text[],false,'{"seq":5,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"상황 ㉯의 대화 방식이 ‘직접 만나서’라는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"표정과 몸짓도 할머니께 그대로 보이니 함께 살펴야 한다","correct":true},{"t":"높임 표현을 쓰지 않아도 된다","mis":"K3-2-u4-X10"},{"t":"전화처럼 내가 누구인지 밝혀야 한다","mis":"K3-2-u4-X22"},{"t":"짧게 “안 돼요.”만 하면 된다","mis":"K3-2-u4-X19"}],"explanation":["할머니와 마주 보고 있어요.","얼굴과 몸짓이 다 보여요.","말과 함께 살펴요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#6','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C22',3,'error','auto','점검표에서 ‘보통’이 나온 뒤에 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X28']::text[],false,'{"seq":6,"concept":"K3-2-u4-C22","difficulty":3,"kind":"error","stem":"점검표에서 ‘보통’이 나온 뒤에 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「‘매우 잘함’으로 고쳐 적으면 끝이야.」","correct":true,"mis_target":"K3-2-u4-X28"},{"t":"친구 나 — 「다음 역할놀이에서는 상대를 보며 말해 볼래.」","mis":"K3-2-u4-X28"},{"t":"친구 다 — 「어느 부분이 보통이었는지 짝에게 물어볼래.」","mis":"K3-2-u4-X28"}],"explanation":["고쳐 적는다고 바뀌지 않아요.","다음에 할 것을 생각해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#7','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C21',3,'match','auto','“고맙습니다.”를 말한 모습과 듣는 사람에게 전해지는 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C21","difficulty":3,"kind":"match","stem":"“고맙습니다.”를 말한 모습과 듣는 사람에게 전해지는 마음을 알맞게 이으세요.","pairs":[{"l":"① 웃으며","r":"고마운 마음이 잘 전해진다"},{"l":"② 화난 목소리로","r":"화가 난 것처럼 들린다"},{"l":"③ 딴 곳을 보며","r":"건성으로 하는 말처럼 들린다"}],"mis":"K3-2-u4-X27","explanation":["낱말은 똑같아요.","말투·표정·눈길이 달라요.","마음도 다르게 전해져요."],"asset":{"type":"passage","lines":["누군가 나에게 무언가를 내밀었어요.","세 사람이 똑같이 “고맙습니다.”라고 했어요.","① 웃으며 ② 화난 목소리로 ③ 딴 곳을 보며"],"title":"같은 말, 다른 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#8','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',4,'mc','auto','온서가 기현이에게 전화한 대본으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X27','K3-2-u4-X26']::text[],false,'{"seq":8,"concept":"K3-2-u4-C20","difficulty":4,"kind":"mc","stem":"온서가 기현이에게 전화한 대본으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“나 온서야. 지금 통화해도 돼?” → (기현이 말에) “응, 그렇구나.” → “그럼 그 책으로 하자. 끊을게, 안녕!”","correct":true},{"t":"“그 책 정했어?” → (기현이 말에) “응.” → 바로 끊는다","mis":"K3-2-u4-X25"},{"t":"“나 온서야.” → 기현이 말에 아무 대꾸 없이 듣기만 한다 → “안녕!”","mis":"K3-2-u4-X27"},{"t":"“나 온서야. 내가 고른 책으로 해. 끝!”","mis":"K3-2-u4-X26"}],"explanation":["누구인지 밝히고 물어요.","짧은 말로 듣고 있다고 알려요.","끝인사를 하고 끊어요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"온서가 함께 읽을 책을 정하려고 기현이에게 전화를 걸었어요."},{"who":"기현","text":"“여보세요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#9','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C15',4,'essay','teacher','상황 ㉯에서 은후와 할머니가 두 번 이상 말을 주고받는 짧은 대본을 쓰세요. 높임 표현과 거절할 때의 대화 예절이 함께 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C15","difficulty":4,"kind":"essay","stem":"상황 ㉯에서 은후와 할머니가 두 번 이상 말을 주고받는 짧은 대본을 쓰세요. 높임 표현과 거절할 때의 대화 예절이 함께 드러나게 쓰세요.","answer_guide":{"answer":"예: 할머니 — “은후야, 화분 옮기는 것 좀 도와줄 수 있니?” 은후 — “할머니, 죄송해요. 지금 친구와 만나기로 한 때가 다 되어서 나가 봐야 해요.” 할머니 — “그렇구나. 어서 다녀오렴.” 은후 — “다녀와서 꼭 도와드릴게요. 화분은 무거우니 혼자 옮기지 마세요.”","scoring_points":["말을 두 번 이상 주고받았는가","할머니께 높임 표현을 바르게 썼는가","죄송한 마음과 까닭을 함께 말했는가"]},"explanation":["상대는 할머니예요.","거절할 때도 높임을 써요.","마음과 까닭을 함께 넣어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"“은후야, 화분 옮기는 것 좀 도와줄 수 있니?”"},{"who":"상황","text":"은후는 곧 친구와 만나기로 한 때가 다 되었어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L10_challenge#10','kor',3,2,'u4','L10','g3_2_kor_u4_L10_challenge','lesson_challenge','K3-2-u4-C20',4,'essay','teacher','상황 ㉮처럼 친구에게 전화로 무언가를 정할 때 대본에 꼭 넣어야 할 것 세 가지를 쓰고, 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C20","difficulty":4,"kind":"essay","stem":"상황 ㉮처럼 친구에게 전화로 무언가를 정할 때 대본에 꼭 넣어야 할 것 세 가지를 쓰고, 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: 첫째, 내가 누구인지 밝히는 말. 둘째, 지금 통화해도 되는지 묻는 말. 셋째, 끊기 전에 하는 끝인사. 전화는 서로의 얼굴이 보이지 않아서 누가 걸었는지, 상대가 통화할 수 있는 때인지, 이제 끊는지를 눈으로 알 수 없으니 말로 알려 주어야 하기 때문이다.","scoring_points":["넣어야 할 것 세 가지를 썼는가","얼굴이 보이지 않는다는 까닭을 썼는가","말로 알려 주어야 한다고 썼는가"]},"explanation":["전화는 얼굴이 안 보여요.","처음·중간·끝을 떠올려요.","눈으로 알 것을 말로 해요."],"asset":{"type":"speech","turns":[{"who":"상황","text":"온서가 함께 읽을 책을 정하려고 기현이에게 전화를 걸었어요."},{"who":"기현","text":"“여보세요?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#1','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C6',1,'match','auto','낱말 기억 놀이를 하려고 해요. 보통 쓰는 말과 높임의 뜻이 있는 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C6","difficulty":1,"kind":"match","stem":"낱말 기억 놀이를 하려고 해요. 보통 쓰는 말과 높임의 뜻이 있는 말을 알맞게 이으세요.","pairs":[{"l":"사람","r":"분"},{"l":"아프다","r":"편찮으시다"},{"l":"묻다","r":"여쭈어보다"},{"l":"보다","r":"뵙다"}],"mis":"K3-2-u4-X07","explanation":["3~4차시에 본 넷과 다른 넷이에요.","웃어른께 쓰는 말을 떠올려요.","짝을 알아야 놀이를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#2','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',1,'mc','auto','다짐 카드에 적기 좋은 문장은 무엇일까요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":2,"concept":"K3-2-u4-C23","difficulty":1,"kind":"mc","stem":"다짐 카드에 적기 좋은 문장은 무엇일까요?","options":[{"t":"“친구가 말할 때 끝까지 듣고 나서 말하겠습니다.”","correct":true},{"t":"“말을 잘하겠습니다.”","mis":"K3-2-u4-X29"},{"t":"“우리 반에서 가장 예절 바른 사람이 되겠습니다.”","mis":"K3-2-u4-X29"},{"t":"“모든 예절을 다 지키겠습니다.”","mis":"K3-2-u4-X29"}],"explanation":["내일 바로 해 볼 수 있어야 해요.","언제·무엇을 할지 드러나요.","한 가지만 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#3','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C25',1,'mc','auto','방언에 대한 설명으로 알맞은 것은 무엇일까요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":3,"concept":"K3-2-u4-C25","difficulty":1,"kind":"mc","stem":"방언에 대한 설명으로 알맞은 것은 무엇일까요?","options":[{"t":"어느 한 지역에서 쓰는 말이고 틀린 말이 아니다","correct":true},{"t":"잘못 배워서 틀리게 쓰는 말","mis":"K3-2-u4-X31"},{"t":"옛날에만 쓰고 지금은 없는 말","mis":"K3-2-u4-X31"},{"t":"웃어른께만 쓰는 높임말","mis":"K3-2-u4-X31"}],"explanation":["같은 것을 지역마다 다르게 불러요.","표준어가 아닐 뿐이에요.","틀린 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#4','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C26',1,'blank','auto','“설날 아침, 어른께 (　)를 드려요.”의 빈칸에 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":4,"concept":"K3-2-u4-C26","difficulty":1,"kind":"blank","stem":"“설날 아침, 어른께 (　)를 드려요.”의 빈칸에 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"세배","correct":true},{"t":"새배","mis":"K3-2-u4-X32"},{"t":"세베","mis":"K3-2-u4-X32"},{"t":"새베","mis":"K3-2-u4-X32"}],"explanation":["ㅔ와 ㅐ는 가로획 자리가 달라요.","세(ㅔ) 배(ㅐ)예요.","‘세배’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#5','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C24',2,'mc','auto','우리 반에서 할 실천 활동을 정할 때 무엇을 먼저 볼까요?',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":5,"concept":"K3-2-u4-C24","difficulty":2,"kind":"mc","stem":"우리 반에서 할 실천 활동을 정할 때 무엇을 먼저 볼까요?","options":[{"t":"이 단원에서 배운 것을 실제로 써 보는 활동인지","correct":true},{"t":"가장 재미있어 보이는 활동인지","mis":"K3-2-u4-X30"},{"t":"가장 빨리 끝나는 활동인지","mis":"K3-2-u4-X30"},{"t":"준비물이 가장 적은 활동인지","mis":"K3-2-u4-X30"}],"explanation":["실천 시간은 배운 것을 써 보는 시간이에요.","재미와 빠르기가 먼저가 아니에요.","배운 것과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#6','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',2,'mc','auto','다짐 카드를 적는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":6,"concept":"K3-2-u4-C23","difficulty":2,"kind":"mc","stem":"다짐 카드를 적는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"언제, 무엇을 할지 한 가지만 적는다","correct":true},{"t":"지킬 것을 여러 개 한꺼번에 적는다","mis":"K3-2-u4-X29"},{"t":"멋진 말로 크게만 적는다","mis":"K3-2-u4-X29"},{"t":"친구와 똑같은 다짐을 적어야 한다","mis":"K3-2-u4-X29"}],"explanation":["여러 개는 지키기 어려워요.","언제·무엇을이 드러나야 해요.","고르는 것은 사람마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#7','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C6',2,'blank','auto','“선생님, 내일 다시 (　).”의 빈칸에 가장 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X07','K3-2-u4-X11']::text[],false,'{"seq":7,"concept":"K3-2-u4-C6","difficulty":2,"kind":"blank","stem":"“선생님, 내일 다시 (　).”의 빈칸에 가장 알맞은 말은 무엇인가요?","options":[{"t":"뵙겠습니다","correct":true},{"t":"보겠습니다","mis":"K3-2-u4-X07"},{"t":"보시겠습니다","mis":"K3-2-u4-X11"},{"t":"계시겠습니다","mis":"K3-2-u4-X07"}],"explanation":["내가 선생님을 보는 거예요.","‘보다’의 높임 낱말을 써요.","‘뵙겠습니다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#8','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C18',2,'mc','auto','전화로 말할 때 “받자마자 내 할 말부터 한다”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":8,"concept":"K3-2-u4-C18","difficulty":2,"kind":"mc","stem":"전화로 말할 때 “받자마자 내 할 말부터 한다”를 바르게 고친 것은 무엇인가요?","options":[{"t":"통화해도 되는 때인지 먼저 묻는다","correct":true},{"t":"더 빨리 말한다","mis":"K3-2-u4-X25"},{"t":"끝인사를 하지 않는다","mis":"K3-2-u4-X25"},{"t":"받을 때까지 다시 건다","mis":"K3-2-u4-X25"}],"explanation":["상대가 바쁠 수도 있어요.","얼굴이 안 보여 모르니 물어요.","먼저 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#9','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C25',2,'ox','auto','방언은 표준어가 아니니 틀린 말이에요.',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":9,"concept":"K3-2-u4-C25","difficulty":2,"kind":"ox","stem":"방언은 표준어가 아니니 틀린 말이에요.","answer":"X","reason_options":[{"t":"같은 것을 지역마다 다르게 부르는 말이라 틀린 말이 아니기 때문에","correct":true},{"t":"표준어가 아닌 말은 모두 틀린 말이기 때문에","mis":"K3-2-u4-X31"}],"mis":"K3-2-u4-X31","explanation":["표준어가 아니라는 것과 틀렸다는 것은 달라요.","다른 것은 틀린 것이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_basic#10','kor',3,2,'u4','L12','g3_2_kor_u4_L12_basic','lesson_basic','K3-2-u4-C23',3,'error','auto','다짐 카드를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":10,"concept":"K3-2-u4-C23","difficulty":3,"kind":"error","stem":"다짐 카드를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘언제나 착하게 살겠습니다’가 제일 좋은 다짐이야.」","correct":true,"mis_target":"K3-2-u4-X29"},{"t":"친구 가 — 「‘부탁을 들어줄 수 없을 때 까닭을 말하겠습니다’는 지킬 수 있어.」","mis":"K3-2-u4-X29"},{"t":"친구 나 — 「무엇을 고를지는 사람마다 달라도 돼.」","mis":"K3-2-u4-X29"}],"explanation":["언제·무엇을이 드러나야 해요.","‘언제나 착하게’는 지켰는지 알 수 없어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#1','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C6',2,'sa','auto','‘묻다’를 높여 이르는 낱말을 ‘-다’로 끝나게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u4-C6","difficulty":2,"kind":"sa","stem":"‘묻다’를 높여 이르는 낱말을 ‘-다’로 끝나게 쓰세요.","answer":["여쭈어보다","여쭈다","여쭤보다"],"explanation":["웃어른께 무엇을 물을 때 써요.","“선생님께 ○○○○○.”","‘여쭈어보다’예요."],"mis":"K3-2-u4-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#2','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C26',2,'mc','auto','ㅐ와 ㅔ의 모양이 다른 점은 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":2,"concept":"K3-2-u4-C26","difficulty":2,"kind":"mc","stem":"ㅐ와 ㅔ의 모양이 다른 점은 무엇인가요?","options":[{"t":"가로획의 자리가 다르다","correct":true},{"t":"짧은 획이 두 개인 것과 하나인 것","mis":"K3-2-u4-X32"},{"t":"소리가 같으니 아무렇게나 써도 된다","mis":"K3-2-u4-X32"},{"t":"ㅐ는 받침에만 쓴다","mis":"K3-2-u4-X32"}],"explanation":["ㅐ는 짧은 가로획이 안쪽을 향해요.","ㅔ는 바깥쪽을 향해요.","가로획 자리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#3','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C23',3,'mc','auto','실제로 지킬 수 있는 다짐끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":3,"concept":"K3-2-u4-C23","difficulty":3,"kind":"mc","stem":"실제로 지킬 수 있는 다짐끼리 묶은 것은 무엇인가요?","options":[{"t":"「웃어른을 만나면 서서 인사드리겠습니다」 · 「모둠 활동을 할 때 한 번은 내 생각을 말하겠습니다」","correct":true},{"t":"「언제나 착하게 살겠습니다」 · 「모든 사람과 친하게 지내겠습니다」","mis":"K3-2-u4-X29"},{"t":"「말을 잘하겠습니다」 · 「웃어른을 만나면 서서 인사드리겠습니다」","mis":"K3-2-u4-X29"},{"t":"「가장 예절 바른 사람이 되겠습니다」 · 「모둠 활동을 할 때 한 번은 내 생각을 말하겠습니다」","mis":"K3-2-u4-X29"}],"explanation":["둘 다 지킬 수 있어야 해요.","언제·무엇을이 드러난 것을 골라요.","막연한 것이 섞이면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#4','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C24',3,'ox','auto','우리 반 실천 활동은 가장 빨리 끝나는 것으로 골라야 다른 공부를 더 할 수 있어요.',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":4,"concept":"K3-2-u4-C24","difficulty":3,"kind":"ox","stem":"우리 반 실천 활동은 가장 빨리 끝나는 것으로 골라야 다른 공부를 더 할 수 있어요.","answer":"X","reason_options":[{"t":"실천 시간은 배운 것을 실제로 써 보려고 있는 시간이기 때문에","correct":true},{"t":"활동은 짧을수록 좋기 때문에","mis":"K3-2-u4-X30"}],"mis":"K3-2-u4-X30","explanation":["실천은 써 보는 거예요.","빨리 끝나면 써 볼 수 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#5','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',3,'mc','auto','방언을 알아보는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":5,"concept":"K3-2-u4-C25","difficulty":3,"kind":"mc","stem":"방언을 알아보는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"집이나 둘레 어른께 여쭈어보고, 표준어로는 무엇인지 함께 적는다","correct":true},{"t":"그럴듯한 낱말을 지어 방언 목록을 만든다","mis":"K3-2-u4-X31"},{"t":"방언은 틀린 말이니 알아볼 필요가 없다","mis":"K3-2-u4-X31"},{"t":"친구에게 아무 말이나 방언이라고 알려 준다","mis":"K3-2-u4-X31"}],"explanation":["지어내면 없는 방언을 배우게 돼요.","실제로 쓰는 분께 들어요.","표준어와 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#6','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C6',3,'error','auto','낱말 기억 놀이를 하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":6,"concept":"K3-2-u4-C6","difficulty":3,"kind":"error","stem":"낱말 기억 놀이를 하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「‘묻다’와 ‘여쭈어보다’는 뜻이 반대인 짝이야.」","correct":true,"mis_target":"K3-2-u4-X07"},{"t":"친구 가 — 「웃어른께는 ‘사람’ 대신 ‘분’이라고 해.」","mis":"K3-2-u4-X07"},{"t":"친구 다 — 「‘아프다’는 ‘편찮으시다’로 높여.」","mis":"K3-2-u4-X07"}],"explanation":["높임 낱말 짝은 뜻이 같아요.","웃어른께 쓰는 말일 뿐이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#7','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C26',3,'mc','auto','바르게 쓴 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":7,"concept":"K3-2-u4-C26","difficulty":3,"kind":"mc","stem":"바르게 쓴 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"새해 · 세배 · 얘들아 · 계절","correct":true},{"t":"세해 · 새배 · 애들아 · 게절","mis":"K3-2-u4-X32"},{"t":"새해 · 세배 · 예들아 · 계절","mis":"K3-2-u4-X32"},{"t":"새해 · 새배 · 얘들아 · 게절","mis":"K3-2-u4-X32"}],"explanation":["ㅐ·ㅔ는 가로획 자리를 봐요.","ㅒ·ㅖ는 짧은 획이 두 개예요.","넷 다 바른 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#8','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C18',4,'mc','auto','은후가 기현이네 집에 전화했는데 기현이 어머니께서 받으셨어요. 가장 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X11','K3-2-u4-X25']::text[],false,'{"seq":8,"concept":"K3-2-u4-C18","difficulty":4,"kind":"mc","stem":"은후가 기현이네 집에 전화했는데 기현이 어머니께서 받으셨어요. 가장 알맞은 말은 무엇인가요?","options":[{"t":"“안녕하세요? 저는 기현이와 같은 반인 은후입니다. 기현이 집에 있어요?”","correct":true},{"t":"“기현이 있어?”","mis":"K3-2-u4-X10"},{"t":"“안녕하세요? 기현이 집에 계세요?”","mis":"K3-2-u4-X11"},{"t":"“나 은후야. 기현이 바꿔.”","mis":"K3-2-u4-X25"}],"explanation":["받으신 분은 어머니예요.","누구인지 밝히고 높여 말해요.","친구 기현이는 높이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#9','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C23',4,'essay','teacher','이 단원에서 배운 대화 예절 가운데 꼭 지키고 싶은 것 하나를 골라 다짐 카드 문장을 쓰고, 그 문장이 실천할 수 있는 다짐인 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u4-C23","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 대화 예절 가운데 꼭 지키고 싶은 것 하나를 골라 다짐 카드 문장을 쓰고, 그 문장이 실천할 수 있는 다짐인 까닭을 쓰세요.","answer_guide":{"answer":"예: 다짐 — “부탁을 들어줄 수 없을 때에는 미안하다고 말하고 까닭을 말하겠습니다.” 이 다짐은 언제(부탁을 들어줄 수 없을 때) 무엇을(미안하다고 말하고 까닭을 말하기) 할지 한 가지가 드러나 있어서, 하루를 지내고 지켰는지 스스로 알 수 있다.","scoring_points":["다짐 카드 문장을 썼는가","언제·무엇을이 드러났는가","지켰는지 알 수 있다는 까닭을 썼는가"]},"explanation":["고르는 것은 내 마음대로예요.","언제·무엇을 한 가지만.","지켰는지 알 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_L12_challenge#10','kor',3,2,'u4','L12','g3_2_kor_u4_L12_challenge','lesson_challenge','K3-2-u4-C25',4,'essay','teacher','방언이 틀린 말이 아닌 까닭을 쓰고, 방언을 알아보려면 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u4-C25","difficulty":4,"kind":"essay","stem":"방언이 틀린 말이 아닌 까닭을 쓰고, 방언을 알아보려면 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 방언은 어느 한 지역에서 같은 것을 다르게 부르는 말일 뿐, 표준어가 아니라고 해서 틀린 말은 아니다. 방언을 알아보려면 그럴듯하게 지어내지 말고, 집이나 둘레 어른께 “여기에서만 쓰는 말이 있나요?” 하고 여쭈어본 뒤 그 말이 표준어로 무엇인지 함께 적는다.","scoring_points":["방언이 틀린 말이 아닌 까닭을 썼는가","어른께 여쭈어본다고 썼는가","지어내지 않는다는 점이 드러났는가"]},"explanation":["다른 것은 틀린 것이 아니에요.","실제로 쓰는 분께 들어요.","지어내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#1','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C2',1,'mc','auto','높임 표현에는 어떤 마음이 담겨 있나요?',ARRAY['K3-2-u4-X04','K3-2-u4-X02']::text[],false,'{"seq":1,"concept":"K3-2-u4-C2","difficulty":1,"kind":"mc","stem":"높임 표현에는 어떤 마음이 담겨 있나요?","options":[{"t":"상대를 존중하는 마음","correct":true},{"t":"말을 길게 하고 싶은 마음","mis":"K3-2-u4-X04"},{"t":"어려운 낱말을 자랑하는 마음","mis":"K3-2-u4-X04"},{"t":"나이를 알리고 싶은 마음","mis":"K3-2-u4-X02"}],"explanation":["높임 표현은 상대를 높여요.","그 안에 마음이 있어요.","존중하는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#2','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C4',1,'mc','auto','“선생님께서 읽으신다”에서 ‘-시-’가 높이는 사람은 누구인가요?',ARRAY['K3-2-u4-X05','K3-2-u4-X09','K3-2-u4-X08']::text[],false,'{"seq":2,"concept":"K3-2-u4-C4","difficulty":1,"kind":"mc","stem":"“선생님께서 읽으신다”에서 ‘-시-’가 높이는 사람은 누구인가요?","options":[{"t":"읽는 일을 하는 선생님","correct":true},{"t":"말하는 나","mis":"K3-2-u4-X05"},{"t":"선생님께서 읽으시는 책","mis":"K3-2-u4-X09"},{"t":"이 말을 듣는 친구","mis":"K3-2-u4-X08"}],"explanation":["‘-시-’는 움직임 안에 있어요.","읽는 사람이 누구인지 봐요.","선생님을 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#3','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C5',1,'blank','auto','“이 그림을 선생님(　) 드리려고 해요.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X06']::text[],false,'{"seq":3,"concept":"K3-2-u4-C5","difficulty":1,"kind":"blank","stem":"“이 그림을 선생님(　) 드리려고 해요.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"께","correct":true},{"t":"에게","mis":"K3-2-u4-X06"},{"t":"이","mis":"K3-2-u4-X06"},{"t":"께서","mis":"K3-2-u4-X06"}],"explanation":["그림을 받는 분은 선생님이에요.","‘에게’ 대신 쓰는 말이에요.","‘께’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#4','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C6',1,'mc','auto','‘이름’을 높여 이르는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"‘이름’을 높여 이르는 낱말은 무엇인가요?","options":[{"t":"성함","correct":true},{"t":"연세","mis":"K3-2-u4-X07"},{"t":"분","mis":"K3-2-u4-X07"},{"t":"댁","mis":"K3-2-u4-X07"}],"explanation":["웃어른의 이름을 물을 때 써요.","“○○이 어떻게 되세요?”","‘성함’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#5','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C7',1,'mc','auto','“제가 하겠다”를 듣는 사람을 높여 바꾼 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X10']::text[],false,'{"seq":5,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"“제가 하겠다”를 듣는 사람을 높여 바꾼 것은 무엇인가요?","options":[{"t":"“제가 하겠습니다”","correct":true},{"t":"“제가 하시겠다”","mis":"K3-2-u4-X11"},{"t":"“제가 하겠어”","mis":"K3-2-u4-X10"},{"t":"“저께서 하겠다”","mis":"K3-2-u4-X11"}],"explanation":["하는 사람은 나예요.","나는 높이지 않아요.","말끝으로 듣는 사람을 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#6','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C13',1,'mc','auto','대화 예절에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X17','K3-2-u4-X21']::text[],false,'{"seq":6,"concept":"K3-2-u4-C13","difficulty":1,"kind":"mc","stem":"대화 예절에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"상대의 마음을 살피며 말하고 듣는 것","correct":true},{"t":"남의 부탁을 모두 들어주는 것","mis":"K3-2-u4-X16"},{"t":"내 생각은 말하지 않는 것","mis":"K3-2-u4-X17"},{"t":"가장 큰 목소리로 말하는 것","mis":"K3-2-u4-X21"}],"explanation":["예절은 살피는 일이에요.","들어주기가 아니에요.","말하고 듣기 둘 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#7','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C18',1,'mc','auto','전화를 건 사람이 먼저 할 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X21']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"mc","stem":"전화를 건 사람이 먼저 할 말로 알맞은 것은 무엇인가요?","options":[{"t":"내가 누구인지 밝히고 통화해도 되는지 묻는 말","correct":true},{"t":"바로 내 할 말","mis":"K3-2-u4-X25"},{"t":"상대 이름만 크게 부르는 말","mis":"K3-2-u4-X21"},{"t":"아무 말 없이 기다리기","mis":"K3-2-u4-X25"}],"explanation":["상대는 나를 볼 수 없어요.","누구인지 밝혀요.","통화해도 되는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#8','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C25',1,'mc','auto','방언은 무엇인가요?',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":8,"concept":"K3-2-u4-C25","difficulty":1,"kind":"mc","stem":"방언은 무엇인가요?","options":[{"t":"어느 한 지역에서만 쓰는, 표준어가 아닌 말","correct":true},{"t":"틀리게 배운 말","mis":"K3-2-u4-X31"},{"t":"옛날에만 쓰던 말","mis":"K3-2-u4-X31"},{"t":"웃어른께만 쓰는 말","mis":"K3-2-u4-X31"}],"explanation":["같은 것을 지역마다 다르게 불러요.","표준어가 아닐 뿐이에요.","틀린 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#9','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C9',2,'mc','auto','시우의 쪽지 2번 “할머니가 아파서”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X10','K3-2-u4-X09']::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우의 쪽지 2번 “할머니가 아파서”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“할머니께서 편찮으셔서”","correct":true},{"t":"“할머니가 편찮아서”","mis":"K3-2-u4-X06"},{"t":"“할머니가 아파서” 그대로 둔다","mis":"K3-2-u4-X10"},{"t":"“할머니께서 아파서 계세요”","mis":"K3-2-u4-X09"}],"explanation":["할머니를 높여요.","‘께서’와 높임 낱말을 써요.","‘편찮으셔서’예요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#10','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C8',2,'ox','auto','“선생님, 숙제가 많으시네요.”는 바르게 쓴 말이에요.',ARRAY['K3-2-u4-X09']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"ox","stem":"“선생님, 숙제가 많으시네요.”는 바르게 쓴 말이에요.","answer":"X","reason_options":[{"t":"많은 것은 숙제라 사람이 아닌 일에 ‘-시-’를 붙였기 때문에","correct":true},{"t":"선생님 앞에서는 모든 말에 ‘-시-’를 붙여야 하기 때문에","mis":"K3-2-u4-X09"}],"mis":"K3-2-u4-X09","explanation":["많은 것은 무엇인가요?","숙제는 사람이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#11','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C11',2,'mc','auto','담임 선생님께서 “하람이는 교무실로 오렴.”이라고 하셨어요. 하람이에게 옮길 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X03']::text[],false,'{"seq":11,"concept":"K3-2-u4-C11","difficulty":2,"kind":"mc","stem":"담임 선생님께서 “하람이는 교무실로 오렴.”이라고 하셨어요. 하람이에게 옮길 때 알맞은 것은 무엇인가요?","options":[{"t":"“하람아, 선생님께서 교무실로 오라고 하셔.”","correct":true},{"t":"“하람아, 선생님이 교무실로 오래.”","mis":"K3-2-u4-X14"},{"t":"“하람아, 선생님께서 교무실로 오시래.”","mis":"K3-2-u4-X14"},{"t":"“하람아, 선생님께서 교무실로 오라고 하셔요.”","mis":"K3-2-u4-X03"}],"explanation":["말씀하신 분은 선생님이에요.","오는 사람은 하람이에요.","친구에게는 말끝을 높이지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#12','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C12',2,'mc','auto','한 낱말이 다른 낱말의 뜻을 포함하는 짝은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":12,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"한 낱말이 다른 낱말의 뜻을 포함하는 짝은 무엇인가요?","options":[{"t":"신발 — 운동화","correct":true},{"t":"묻다 — 대답하다","mis":"K3-2-u4-X15"},{"t":"돕다 — 거들다","mis":"K3-2-u4-X15"},{"t":"크다 — 작다","mis":"K3-2-u4-X15"}],"explanation":["운동화는 신발의 한 가지예요.","신발이 운동화를 품어요.","포함하는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#13','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C15',2,'mc','auto','하람이가 나윤이의 부탁을 들어줄 수 없는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X33']::text[],false,'{"seq":13,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"하람이가 나윤이의 부탁을 들어줄 수 없는 까닭은 무엇인가요?","options":[{"t":"점심시간에 도서관 당번이라서","correct":true},{"t":"나윤이가 싫어서","mis":"K3-2-u4-X33"},{"t":"줄넘기를 못해서","mis":"K3-2-u4-X33"},{"t":"점심을 먹어야 해서","mis":"K3-2-u4-X33"}],"explanation":["하람이의 말을 다시 읽어요.","까닭을 말했어요.","도서관 당번이에요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"“하람아, 점심시간에 줄넘기 연습 같이 해 줄 수 있어?”"},{"who":"하람","text":"“미안해. 오늘 점심시간에는 도서관 당번이라 갈 수가 없어. 내일은 같이 할 수 있어.”"},{"who":"나윤","text":"“그렇구나. 그럼 내일 하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#14','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C16',2,'mc','auto','도서관에서 멀리 있는 친구를 부를 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X18']::text[],false,'{"seq":14,"concept":"K3-2-u4-C16","difficulty":2,"kind":"mc","stem":"도서관에서 멀리 있는 친구를 부를 때 알맞은 것은 무엇인가요?","options":[{"t":"다가가서 작은 목소리로 부른다","correct":true},{"t":"운동장에서처럼 크게 부른다","mis":"K3-2-u4-X21"},{"t":"들릴 때까지 여러 번 크게 부른다","mis":"K3-2-u4-X21"},{"t":"부르지 않고 어깨를 세게 친다","mis":"K3-2-u4-X18"}],"explanation":["도서관은 조용히 읽는 곳이에요.","곳에 맞게 말해요.","다가가서 작게 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#15','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C19',2,'mc','auto','모둠 대화에서 도율이의 말에 어떤 문제가 있었나요?',ARRAY['K3-2-u4-X21','K3-2-u4-X03','K3-2-u4-X17']::text[],false,'{"seq":15,"concept":"K3-2-u4-C19","difficulty":2,"kind":"mc","stem":"모둠 대화에서 도율이의 말에 어떤 문제가 있었나요?","options":[{"t":"다른 생각을 듣지 않고 내 생각만 밀고 갔다","correct":true},{"t":"목소리가 너무 작았다","mis":"K3-2-u4-X21"},{"t":"친구에게 높임말을 쓰지 않았다","mis":"K3-2-u4-X03"},{"t":"아무 말도 하지 않았다","mis":"K3-2-u4-X17"}],"explanation":["“무조건 그림이야.”","“다른 건 다 별로야.”","내 생각만 밀었어요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#16','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C21',2,'mc','auto','직접 만나 이야기할 때 ‘잘 듣고 있다’는 것을 보여 주는 것은 무엇인가요?',ARRAY['K3-2-u4-X23','K3-2-u4-X27']::text[],false,'{"seq":16,"concept":"K3-2-u4-C21","difficulty":2,"kind":"mc","stem":"직접 만나 이야기할 때 ‘잘 듣고 있다’는 것을 보여 주는 것은 무엇인가요?","options":[{"t":"상대를 바라보며 고개를 끄덕인다","correct":true},{"t":"휴대 기기 화면을 보며 “응.”만 한다","mis":"K3-2-u4-X23"},{"t":"팔짱을 끼고 다른 곳을 본다","mis":"K3-2-u4-X27"},{"t":"말이 끝나기 전에 일어선다","mis":"K3-2-u4-X27"}],"explanation":["몸짓도 말이에요.","바라보고 끄덕여요.","듣고 있다는 뜻이 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#17','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C3',3,'error','auto','친구에게 쓰는 높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X02','K3-2-u4-X03']::text[],false,'{"seq":17,"concept":"K3-2-u4-C3","difficulty":3,"kind":"error","stem":"친구에게 쓰는 높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「우리 반 친구에게는 어떤 때에도 높임말을 쓰지 않아.」","correct":true,"mis_target":"K3-2-u4-X02"},{"t":"친구 나 — 「학급 회의 때는 친구에게도 높임말을 써.」","mis":"K3-2-u4-X02"},{"t":"친구 다 — 「쉬는 시간에 짝과 놀 때는 높임말을 안 써도 돼.」","mis":"K3-2-u4-X03"}],"explanation":["곳에 따라 달라져요.","회의 때는 친구에게도 써요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#18','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C8',3,'error','auto','높임 표현을 바르게 쓰는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":18,"concept":"K3-2-u4-C8","difficulty":3,"kind":"error","stem":"높임 표현을 바르게 쓰는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「말끝마다 ‘-시-’를 붙이면 틀릴 일이 없어.」","correct":true,"mis_target":"K3-2-u4-X09"},{"t":"친구 가 — 「높이는 것은 사람이야.」","mis":"K3-2-u4-X09"},{"t":"친구 나 — 「어렵다고 아예 안 쓰면 안 돼.」","mis":"K3-2-u4-X10"}],"explanation":["물건까지 높이면 어색해요.","많이 붙인다고 바른 말이 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#19','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C15',3,'error','auto','들어드릴 수 없는 웃어른의 부탁을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19']::text[],false,'{"seq":19,"concept":"K3-2-u4-C15","difficulty":3,"kind":"error","stem":"들어드릴 수 없는 웃어른의 부탁을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「웃어른 부탁은 못 해도 “네, 할게요.”라고 해야 해.」","correct":true,"mis_target":"K3-2-u4-X20"},{"t":"친구 가 — 「거절할 때는 “죄송해요.”부터 말씀드려.」","mis":"K3-2-u4-X19"},{"t":"친구 다 — 「왜 도와드릴 수 없는지도 말씀드려.」","mis":"K3-2-u4-X19"}],"explanation":["못 하는데 한다고 하면 거짓이에요.","죄송한 마음과 까닭을 말씀드려요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#20','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C18',3,'mc','auto','하람이가 전화에서 처음에 잘한 점은 무엇인가요?',ARRAY['K3-2-u4-X25','K3-2-u4-X11']::text[],false,'{"seq":20,"concept":"K3-2-u4-C18","difficulty":3,"kind":"mc","stem":"하람이가 전화에서 처음에 잘한 점은 무엇인가요?","options":[{"t":"받으신 분께 인사하고 자기가 누구인지 밝혔다","correct":true},{"t":"받자마자 할 말부터 했다","mis":"K3-2-u4-X25"},{"t":"아무 말 없이 기다렸다","mis":"K3-2-u4-X25"},{"t":"나윤이를 높여 불렀다","mis":"K3-2-u4-X11"}],"explanation":["어머니께서 받으셨어요.","하람이는 먼저 인사했어요.","같은 반 하람이라고 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#21','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C19',3,'error','auto','이안이네 모둠 대화를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17']::text[],false,'{"seq":21,"concept":"K3-2-u4-C19","difficulty":3,"kind":"error","stem":"이안이네 모둠 대화를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「도율이처럼 내 생각을 끝까지 밀고 가야 모둠이 빨리 정해.」","correct":true,"mis_target":"K3-2-u4-X26"},{"t":"친구 나 — 「이안이는 다른 생각을 끝까지 들었어.」","mis":"K3-2-u4-X26"},{"t":"친구 다 — 「서아도 생각을 말해서 좋은 생각이 나왔어.」","mis":"K3-2-u4-X17"}],"explanation":["모둠 대화는 이기는 일이 아니에요.","함께 답을 찾아요.","친구 가가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#22','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C23',3,'mc','auto','다짐 카드로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X29']::text[],false,'{"seq":22,"concept":"K3-2-u4-C23","difficulty":3,"kind":"mc","stem":"다짐 카드로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“모둠 활동을 할 때 친구가 말을 마친 뒤에 내 생각을 말하겠습니다.”","correct":true},{"t":"“좋은 사람이 되겠습니다.”","mis":"K3-2-u4-X29"},{"t":"“모든 예절을 다 지키겠습니다.”","mis":"K3-2-u4-X29"},{"t":"“말을 예쁘게 하겠습니다.”","mis":"K3-2-u4-X29"}],"explanation":["언제·무엇을이 드러나야 해요.","한 가지만 적어요.","내일 지켰는지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#23','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C9',4,'mc','auto','시우가 쪽지의 2~5번을 고쳐 다시 썼어요. 가장 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10','K3-2-u4-X11']::text[],false,'{"seq":23,"concept":"K3-2-u4-C9","difficulty":4,"kind":"mc","stem":"시우가 쪽지의 2~5번을 고쳐 다시 썼어요. 가장 바르게 고친 것은 무엇인가요?","options":[{"t":"“할머니께서 편찮으셔서 병원에 같이 가야 해요. 공책은 책상 위에 있어요. 집에 가면 할머니께 말씀드릴게요. 내일 뵙겠습니다.”","correct":true},{"t":"“할머니께서 편찮으셔서 병원에 같이 가야 해요. 공책은 책상 위에 계세요. 집에 가시면 할머니께 말씀드릴게요. 내일 뵙겠습니다.”","mis":"K3-2-u4-X09"},{"t":"“할머니가 아파서 병원에 같이 가야 해. 공책은 책상 위에 있어. 집에 가면 할머니한테 말할게. 내일 봐.”","mis":"K3-2-u4-X10"},{"t":"“할머니께서 편찮으셔서 병원에 같이 가야 해요. 공책은 책상 위에 있어요. 집에 가시면 할머니께 말씀드릴게요. 내일 봐요.”","mis":"K3-2-u4-X11"}],"explanation":["할머니와 선생님을 높여요.","공책과 나는 높이지 않아요.","넷 다 맞은 것을 골라요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#24','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C9',4,'essay','teacher','시우의 쪽지에서 고쳐야 할 곳 네 군데를 찾아 바르게 고치고, 각각 누구를 높여야(높이지 않아야) 하기 때문인지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C9","difficulty":4,"kind":"essay","stem":"시우의 쪽지에서 고쳐야 할 곳 네 군데를 찾아 바르게 고치고, 각각 누구를 높여야(높이지 않아야) 하기 때문인지 쓰세요.","answer_guide":{"answer":"예: 2번 “할머니가 아파서” → “할머니께서 편찮으셔서” — 말 속의 할머니를 높여야 하기 때문이다. 3번 “공책은 책상 위에 계세요” → “공책은 책상 위에 있어요” — 공책은 사람이 아니라 높이지 않기 때문이다. 4번 “집에 가시면” → “집에 가면” — 집에 가는 사람은 시우 자신이라 높이지 않기 때문이다. 5번 “내일 봐요” → “내일 뵙겠습니다” — 선생님을 뵙는 것이라 높임의 뜻이 있는 낱말을 써야 하기 때문이다.","scoring_points":["고칠 곳 네 군데를 찾았는가","바르게 고쳤는가","누구를 높이는지(높이지 않는지)로 까닭을 썼는가"]},"explanation":["줄마다 누구를 높일지 봐요.","물건과 나는 높이지 않아요.","높임 낱말도 떠올려요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_a#25','kor',3,2,'u4','','g3_2_kor_u4_review_a','unit_review','K3-2-u4-C18',4,'essay','teacher','하람이의 통화에서 지킨 전화 예절 세 가지를 쓰고, 전화에서 그것이 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C18","difficulty":4,"kind":"essay","stem":"하람이의 통화에서 지킨 전화 예절 세 가지를 쓰고, 전화에서 그것이 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 받으신 어머니께 인사하고 같은 반 하람이라고 밝혔다. 둘째, 나윤이에게 지금 통화해도 되는지 물었다. 셋째, 이야기를 마치고 “그럼 내일 보자. 안녕!” 하고 끝인사를 했다. 전화는 서로의 얼굴이 보이지 않아 누가 걸었는지, 지금 통화할 수 있는지, 이제 끊는지를 눈으로 알 수 없으니 말로 알려 주어야 하기 때문이다.","scoring_points":["지킨 전화 예절 세 가지를 썼는가","얼굴이 보이지 않는다는 까닭을 썼는가","말로 알려 주어야 한다고 썼는가"]},"explanation":["처음·중간·끝을 봐요.","전화는 얼굴이 안 보여요.","눈으로 알 것을 말로 해요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#1','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C3',1,'ox','auto','처음 만난 사람과 이야기할 때에도 높임 표현을 써요.',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":1,"concept":"K3-2-u4-C3","difficulty":1,"kind":"ox","stem":"처음 만난 사람과 이야기할 때에도 높임 표현을 써요.","answer":"O","reason_options":[{"t":"아직 가깝지 않은 사이라 존중을 나타내기 때문에","correct":true},{"t":"처음 만난 사람은 언제나 나보다 나이가 많기 때문에","mis":"K3-2-u4-X02"}],"mis":"K3-2-u4-X02","explanation":["은후가 처음 인사한 날을 떠올려요.","처음 만난 사이였어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#2','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C4',1,'blank','auto','“할아버지께서 마당을 (　).”의 빈칸에 가장 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X08']::text[],false,'{"seq":2,"concept":"K3-2-u4-C4","difficulty":1,"kind":"blank","stem":"“할아버지께서 마당을 (　).”의 빈칸에 가장 알맞은 말은 무엇인가요?","options":[{"t":"쓰신다","correct":true},{"t":"쓴다","mis":"K3-2-u4-X10"},{"t":"써라","mis":"K3-2-u4-X08"},{"t":"쓰는구나","mis":"K3-2-u4-X08"}],"explanation":["마당을 쓰는 분은 할아버지예요.","움직임에 ‘-시-’를 넣어요.","‘쓰신다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#3','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C5',1,'blank','auto','“어머니(　) 웃으셨어요.”의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X06']::text[],false,'{"seq":3,"concept":"K3-2-u4-C5","difficulty":1,"kind":"blank","stem":"“어머니(　) 웃으셨어요.”의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"께서","correct":true},{"t":"가","mis":"K3-2-u4-X06"},{"t":"께","mis":"K3-2-u4-X06"},{"t":"에게","mis":"K3-2-u4-X06"}],"explanation":["웃으신 분은 어머니예요.","‘이/가’ 대신 쓰는 말이에요.","‘께서’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#4','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C6',1,'mc','auto','‘있다’를 높여 이르는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"‘있다’를 높여 이르는 낱말은 무엇인가요?","options":[{"t":"계시다","correct":true},{"t":"주무시다","mis":"K3-2-u4-X07"},{"t":"뵙다","mis":"K3-2-u4-X07"},{"t":"여쭈어보다","mis":"K3-2-u4-X07"}],"explanation":["“할머니께서 방에 ○○○.”","웃어른이 있을 때 써요.","‘계시다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#5','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C7',1,'ox','auto','말끝의 ‘요’는 말 속에 나오는 사람을 높이고, ‘-시-’는 말을 듣는 사람을 높여요.',ARRAY['K3-2-u4-X08']::text[],false,'{"seq":5,"concept":"K3-2-u4-C7","difficulty":1,"kind":"ox","stem":"말끝의 ‘요’는 말 속에 나오는 사람을 높이고, ‘-시-’는 말을 듣는 사람을 높여요.","answer":"X","reason_options":[{"t":"거꾸로 — ‘요’는 듣는 사람을, ‘-시-’는 움직임을 하는 사람을 높이기 때문에","correct":true},{"t":"둘 다 말 속의 사람을 높이기 때문에","mis":"K3-2-u4-X08"}],"mis":"K3-2-u4-X08","explanation":["말끝은 듣는 사람 쪽이에요.","‘-시-’는 움직이는 사람 쪽이에요.","거꾸로 말했으니 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#6','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C14',1,'mc','auto','대화 예절이 드러나는 세 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u4-X18','K3-2-u4-X21','K3-2-u4-X02']::text[],false,'{"seq":6,"concept":"K3-2-u4-C14","difficulty":1,"kind":"mc","stem":"대화 예절이 드러나는 세 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"부르는 말 · 부탁하는 말 · 말하는 태도","correct":true},{"t":"부탁하는 물건 · 시간 · 장소","mis":"K3-2-u4-X18"},{"t":"목소리 크기 · 빠르기 · 길이","mis":"K3-2-u4-X21"},{"t":"나이 · 키 · 힘","mis":"K3-2-u4-X02"}],"explanation":["지웅아 / 야.","줄 수 있을까? / 이리 줘.","상대를 보며 / 턱을 들고."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#7','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C18',1,'ox','auto','전화를 받지 않으면 받을 때까지 계속 다시 걸어요.',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"ox","stem":"전화를 받지 않으면 받을 때까지 계속 다시 걸어요.","answer":"X","reason_options":[{"t":"상대가 받기 어려운 때일 수 있어 다시 걸 때를 정하고 기다려야 하기 때문에","correct":true},{"t":"계속 걸어야 내 말을 빨리 전할 수 있기 때문에","mis":"K3-2-u4-X25"}],"mis":"K3-2-u4-X25","explanation":["상대에게 사정이 있을 수 있어요.","기다렸다 다시 걸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#8','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C25',1,'ox','auto','방언을 쓰는 사람에게는 「틀린 말이야.」라고 고쳐 주어야 해요.',ARRAY['K3-2-u4-X31']::text[],false,'{"seq":8,"concept":"K3-2-u4-C25","difficulty":1,"kind":"ox","stem":"방언을 쓰는 사람에게는 「틀린 말이야.」라고 고쳐 주어야 해요.","answer":"X","reason_options":[{"t":"방언은 지역마다 다르게 부르는 말이지 틀린 말이 아니기 때문에","correct":true},{"t":"표준어가 아니면 틀린 말이기 때문에","mis":"K3-2-u4-X31"}],"mis":"K3-2-u4-X31","explanation":["다른 것은 틀린 것이 아니에요.","그 지역에서 쓰는 말이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#9','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C9',2,'mc','auto','시우의 쪽지 3번 “공책은 책상 위에 계세요.”가 어색한 까닭은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X08','K3-2-u4-X06']::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우의 쪽지 3번 “공책은 책상 위에 계세요.”가 어색한 까닭은 무엇인가요?","options":[{"t":"사람이 아닌 공책을 높였기 때문에","correct":true},{"t":"선생님을 높였기 때문에","mis":"K3-2-u4-X10"},{"t":"말끝에 ‘요’를 붙였기 때문에","mis":"K3-2-u4-X08"},{"t":"‘께’를 썼기 때문에","mis":"K3-2-u4-X06"}],"explanation":["‘계세요’의 주인을 찾아요.","책상 위에 있는 것은 공책이에요.","물건은 높이지 않아요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#10','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C8',2,'mc','auto','바르지 않게 높인 문장은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X09','K3-2-u4-X06']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"바르지 않게 높인 문장은 무엇인가요?","options":[{"t":"“할머니, 물이 끓으셨어요.”","correct":true},{"t":"“할머니께서 물을 끓이셨어요.”","mis":"K3-2-u4-X10"},{"t":"“할머니, 물이 끓었어요.”","mis":"K3-2-u4-X09"},{"t":"“할머니께 물을 갖다드렸어요.”","mis":"K3-2-u4-X06"}],"explanation":["끓는 것은 물이에요.","물은 높이지 않아요.","‘끓으셨어요’가 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#11','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C11',2,'ox','auto','할머니께서 하신 말씀을 동생에게 옮길 때에는 할머니를 높이지 않아도 돼요.',ARRAY['K3-2-u4-X14']::text[],false,'{"seq":11,"concept":"K3-2-u4-C11","difficulty":2,"kind":"ox","stem":"할머니께서 하신 말씀을 동생에게 옮길 때에는 할머니를 높이지 않아도 돼요.","answer":"X","reason_options":[{"t":"말을 옮길 때에도 높여야 할 분은 그대로 높이기 때문에","correct":true},{"t":"듣는 사람이 동생이면 말 속의 사람도 높이지 않기 때문에","mis":"K3-2-u4-X14"}],"mis":"K3-2-u4-X14","explanation":["듣는 사람은 동생이에요.","말씀하신 분은 할머니예요.","할머니를 높이니 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#12','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C12',2,'mc','auto','서로 뜻이 반대인 짝은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":12,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"서로 뜻이 반대인 짝은 무엇인가요?","options":[{"t":"묻다 — 대답하다","correct":true},{"t":"운동화 — 신발","mis":"K3-2-u4-X15"},{"t":"돕다 — 거들다","mis":"K3-2-u4-X15"},{"t":"기쁘다 — 즐겁다","mis":"K3-2-u4-X15"}],"explanation":["묻는 쪽과 대답하는 쪽이 있어요.","서로 반대예요.","반대인 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#13','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C15',2,'ox','auto','하람이는 나윤이의 부탁을 거절했으니 대화 예절을 지키지 않은 거예요.',ARRAY['K3-2-u4-X16']::text[],false,'{"seq":13,"concept":"K3-2-u4-C15","difficulty":2,"kind":"ox","stem":"하람이는 나윤이의 부탁을 거절했으니 대화 예절을 지키지 않은 거예요.","answer":"X","reason_options":[{"t":"미안한 마음과 까닭, 할 수 있는 때를 함께 말했기 때문에","correct":true},{"t":"예절을 지키려면 부탁은 모두 들어주어야 하기 때문에","mis":"K3-2-u4-X16"}],"mis":"K3-2-u4-X16","explanation":["하람이는 “미안해.”라고 했어요.","까닭과 내일도 말했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"“하람아, 점심시간에 줄넘기 연습 같이 해 줄 수 있어?”"},{"who":"하람","text":"“미안해. 오늘 점심시간에는 도서관 당번이라 갈 수가 없어. 내일은 같이 할 수 있어.”"},{"who":"나윤","text":"“그렇구나. 그럼 내일 하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#14','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C17',2,'mc','auto','모둠이 그림 붙일 곳을 정하는 중이에요. 이때 하기 알맞은 말은 무엇인가요?',ARRAY['K3-2-u4-X24','K3-2-u4-X26']::text[],false,'{"seq":14,"concept":"K3-2-u4-C17","difficulty":2,"kind":"mc","stem":"모둠이 그림 붙일 곳을 정하는 중이에요. 이때 하기 알맞은 말은 무엇인가요?","options":[{"t":"“우리 모둠 그림은 창문 옆에 붙이면 어떨까?”","correct":true},{"t":"“그런데 오늘 급식 뭐야?”","mis":"K3-2-u4-X24"},{"t":"두 사람만 귓속말로 정한다","mis":"K3-2-u4-X24"},{"t":"“아무 데나 붙여. 난 몰라.”","mis":"K3-2-u4-X26"}],"explanation":["지금 정하는 것이 무엇인지 봐요.","그것과 이어지는 말을 해요.","모두 들을 수 있게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#15','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C19',2,'mc','auto','이안이가 서아에게 “서아는 어떻게 생각해?”라고 물은 것이 좋은 까닭은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X03','K3-2-u4-X17']::text[],false,'{"seq":15,"concept":"K3-2-u4-C19","difficulty":2,"kind":"mc","stem":"이안이가 서아에게 “서아는 어떻게 생각해?”라고 물은 것이 좋은 까닭은 무엇인가요?","options":[{"t":"말하지 않던 친구도 생각을 말할 수 있게 물어 주어서","correct":true},{"t":"도율이의 말을 막아서","mis":"K3-2-u4-X26"},{"t":"서아에게 높임말을 써서","mis":"K3-2-u4-X03"},{"t":"서아가 계속 조용히 있게 해서","mis":"K3-2-u4-X17"}],"explanation":["서아는 고개만 숙이고 있었어요.","이안이가 기회를 건넸어요.","서아도 생각을 말했어요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#16','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C22',2,'mc','auto','모둠 대화를 마치고 되돌아보기 표를 보는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X28']::text[],false,'{"seq":16,"concept":"K3-2-u4-C22","difficulty":2,"kind":"mc","stem":"모둠 대화를 마치고 되돌아보기 표를 보는 까닭은 무엇인가요?","options":[{"t":"다음에 고칠 점을 찾으려고","correct":true},{"t":"빈칸 없이 채우려고","mis":"K3-2-u4-X28"},{"t":"점수를 높게 받으려고","mis":"K3-2-u4-X28"},{"t":"친구와 누가 잘했는지 견주려고","mis":"K3-2-u4-X28"}],"explanation":["표에는 점수가 없어요.","나를 돌아보는 표예요.","고칠 점을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#17','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C9',3,'mc','auto','하람이가 나윤이 어머니께 “나윤이 집에 있어요?”라고 여쭌 말에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X10','K3-2-u4-X08']::text[],false,'{"seq":17,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"하람이가 나윤이 어머니께 “나윤이 집에 있어요?”라고 여쭌 말에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"듣는 분인 어머니는 ‘요’로 높이고, 친구인 나윤이는 높이지 않아 알맞다","correct":true},{"t":"“나윤이 집에 계세요?”로 고쳐야 한다","mis":"K3-2-u4-X11"},{"t":"“나윤이 집에 있어?”로 고쳐야 한다","mis":"K3-2-u4-X10"},{"t":"높임 표현을 하나도 쓰지 않았다","mis":"K3-2-u4-X08"}],"explanation":["듣는 분은 어머니예요.","집에 있는 사람은 친구 나윤이에요.","높일 사람만 높였어요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#18','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C9',3,'mc','auto','시우의 쪽지에서 고쳐야 할 줄을 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X10','K3-2-u4-X08']::text[],false,'{"seq":18,"concept":"K3-2-u4-C9","difficulty":3,"kind":"mc","stem":"시우의 쪽지에서 고쳐야 할 줄을 바르게 모은 것은 무엇인가요?","options":[{"t":"2번·3번·4번·5번","correct":true},{"t":"2번과 5번만","mis":"K3-2-u4-X11"},{"t":"3번과 4번만","mis":"K3-2-u4-X10"},{"t":"1번·2번·3번","mis":"K3-2-u4-X08"}],"explanation":["줄마다 누구를 높이는지 봐요.","할머니·공책·나·선생님.","1번만 그대로 둬요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#19','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C15',3,'mc','auto','이모께서 “지금 장 보러 같이 갈래?”라고 하셨는데 숙제를 마저 해야 해요. 가장 알맞은 대답은 무엇인가요?',ARRAY['K3-2-u4-X20','K3-2-u4-X19']::text[],false,'{"seq":19,"concept":"K3-2-u4-C15","difficulty":3,"kind":"mc","stem":"이모께서 “지금 장 보러 같이 갈래?”라고 하셨는데 숙제를 마저 해야 해요. 가장 알맞은 대답은 무엇인가요?","options":[{"t":"“죄송해요, 숙제를 마저 해야 해서요. 다음에 같이 갈게요.”","correct":true},{"t":"“네.” 해 놓고 가지 않는다","mis":"K3-2-u4-X20"},{"t":"“안 가요.”","mis":"K3-2-u4-X19"},{"t":"대답하지 않고 방에 들어간다","mis":"K3-2-u4-X19"}],"explanation":["웃어른께 거절할 때예요.","죄송한 마음과 까닭을 말씀드려요.","높임 표현도 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#20','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C20',3,'mc','auto','통화 중에 대화 상대가 바뀌자 하람이의 말은 어떻게 달라졌나요?',ARRAY['K3-2-u4-X22','K3-2-u4-X03','K3-2-u4-X10']::text[],false,'{"seq":20,"concept":"K3-2-u4-C20","difficulty":3,"kind":"mc","stem":"통화 중에 대화 상대가 바뀌자 하람이의 말은 어떻게 달라졌나요?","options":[{"t":"어머니께는 높임 표현을, 친구 나윤이에게는 높이지 않는 말을 썼다","correct":true},{"t":"끝까지 똑같은 말을 썼다","mis":"K3-2-u4-X22"},{"t":"친구에게 더 높여 말했다","mis":"K3-2-u4-X03"},{"t":"어머니께 반말을 했다","mis":"K3-2-u4-X10"}],"explanation":["처음 상대는 어머니예요.","다음 상대는 나윤이예요.","상대에 맞게 말이 바뀌었어요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#21','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C19',3,'mc','auto','도율이의 “무조건 그림이야. 다른 건 다 별로야.”를 알맞게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17','K3-2-u4-X24']::text[],false,'{"seq":21,"concept":"K3-2-u4-C19","difficulty":3,"kind":"mc","stem":"도율이의 “무조건 그림이야. 다른 건 다 별로야.”를 알맞게 고친 것은 무엇인가요?","options":[{"t":"“나는 그림을 붙이고 싶어. 너희 생각은 어때?”","correct":true},{"t":"“그림 아니면 안 할래.”","mis":"K3-2-u4-X26"},{"t":"아무 말도 하지 않는다","mis":"K3-2-u4-X17"},{"t":"“서아는 몰라도 돼.”","mis":"K3-2-u4-X24"}],"explanation":["내 생각은 말해도 돼요.","다른 생각도 물어요.","함께 정할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#22','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C10',3,'mc','auto','「서툰 인사」에서 민결이가 끝에 알게 된 것은 무엇인가요?',ARRAY['K3-2-u4-X12','K3-2-u4-X13']::text[],false,'{"seq":22,"concept":"K3-2-u4-C10","difficulty":3,"kind":"mc","stem":"「서툰 인사」에서 민결이가 끝에 알게 된 것은 무엇인가요?","options":[{"t":"조금 서툴러도 말을 건네는 것이 상대를 살피는 일이라는 것","correct":true},{"t":"틀릴 것 같으면 말하지 않는 것이 낫다는 것","mis":"K3-2-u4-X12"},{"t":"한 글자도 틀리지 않아야 인사할 수 있다는 것","mis":"K3-2-u4-X13"},{"t":"어른께는 고개만 숙이면 된다는 것","mis":"K3-2-u4-X12"}],"explanation":["민결이는 다시 말을 건넸어요.","어른은 고맙다고 하셨어요.","서툴러도 괜찮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#23','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C17',4,'mc','auto','도서관에서 짝이 큰 소리로 “이것 봐!” 하고 불렀어요. 짝에게 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X19']::text[],false,'{"seq":23,"concept":"K3-2-u4-C17","difficulty":4,"kind":"mc","stem":"도서관에서 짝이 큰 소리로 “이것 봐!” 하고 불렀어요. 짝에게 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“여기서는 조금 작게 말해 줘. 밖에 나가서 같이 보자.”","correct":true},{"t":"“시끄러워! 조용히 해!” 하고 크게 말한다","mis":"K3-2-u4-X21"},{"t":"못 들은 척한다","mis":"K3-2-u4-X19"},{"t":"짝보다 더 크게 “뭔데?” 하고 묻는다","mis":"K3-2-u4-X21"}],"explanation":["도서관은 조용한 곳이에요.","짝의 마음도 살펴요.","곳에 맞게 부드럽게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#24','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C3',4,'essay','teacher','「높임 표현은 나이표가 아니다」라는 말을 이 단원에서 본 장면 두 가지를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C3","difficulty":4,"kind":"essay","stem":"「높임 표현은 나이표가 아니다」라는 말을 이 단원에서 본 장면 두 가지를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 높임 표현은 나이만 보고 쓰는 것이 아니라 어떤 곳에서 어떤 사이로 말하는지를 살펴 쓴다. 「서툰 인사」에서 민결이는 나이가 같은 혜온이에게 학급 회의라는 곳이라서 높임말을 썼다. 또 원준이의 할머니께서는 할머니보다 나이가 어린 담임 선생님께 존중을 나타내려고 높임 표현을 쓰셨다.","scoring_points":["나이만 보지 않는다고 썼는가","곳·사이를 살핀다고 썼는가","단원 속 장면 두 가지를 예로 들었는가"]},"explanation":["나이표는 나이만 보는 표예요.","회의 장면을 떠올려요.","할머니와 선생님 장면도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_b#25','kor',3,2,'u4','','g3_2_kor_u4_review_b','unit_review','K3-2-u4-C8',4,'essay','teacher','「높임말은 많이 붙일수록 공손해.」라고 말하는 친구에게 해 줄 말을 쓰고, 시우의 쪽지 3번이나 4번을 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C8","difficulty":4,"kind":"essay","stem":"「높임말은 많이 붙일수록 공손해.」라고 말하는 친구에게 해 줄 말을 쓰고, 시우의 쪽지 3번이나 4번을 예로 들어 설명하세요.","answer_guide":{"answer":"예: 많이 붙인다고 공손해지는 것이 아니라 높여야 할 사람에게만 알맞게 쓰는 것이 바르게 쓰는 것이다. 시우의 쪽지 3번 “공책은 책상 위에 계세요”는 사람이 아닌 공책을 높여서 어색하다. 4번 “집에 가시면”은 집에 가는 사람이 시우 자신인데 높여서 어색하다. “있어요”, “가면”으로 고쳐야 한다.","scoring_points":["많이 붙인다고 공손한 것이 아니라고 썼는가","높일 사람에게만 쓴다고 썼는가","3번이나 4번을 예로 들어 고쳤는가"]},"explanation":["높이는 것은 사람이에요.","나도 높이지 않아요.","쪽지 속 예로 설명해요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#1','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C3',1,'mc','auto','높임 표현을 쓰면 좋은 때는 언제인가요?',ARRAY['K3-2-u4-X03','K3-2-u4-X11','K3-2-u4-X02']::text[],false,'{"seq":1,"concept":"K3-2-u4-C3","difficulty":1,"kind":"mc","stem":"높임 표현을 쓰면 좋은 때는 언제인가요?","options":[{"t":"학급 회의에서 의견을 말할 때","correct":true},{"t":"쉬는 시간에 짝과 놀 때","mis":"K3-2-u4-X03"},{"t":"동생에게 심부름을 부탁할 때","mis":"K3-2-u4-X11"},{"t":"나보다 키가 큰 친구에게 말할 때","mis":"K3-2-u4-X02"}],"explanation":["곳·사이·마음을 살펴요.","회의는 여러 사람 앞이에요.","친구에게도 높임말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#2','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C4',1,'ox','auto','“동생이 오신다”는 바르게 높인 말이에요.',ARRAY['K3-2-u4-X11']::text[],false,'{"seq":2,"concept":"K3-2-u4-C4","difficulty":1,"kind":"ox","stem":"“동생이 오신다”는 바르게 높인 말이에요.","answer":"X","reason_options":[{"t":"오는 사람이 동생이라 높이지 않아도 되기 때문에","correct":true},{"t":"‘-시-’는 아무에게나 붙여도 공손해지기 때문에","mis":"K3-2-u4-X11"}],"mis":"K3-2-u4-X11","explanation":["오는 사람이 누구인지 봐요.","동생은 높이지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#3','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C5',1,'mc','auto','‘이/가’ 대신 써서 높이는 말은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X07']::text[],false,'{"seq":3,"concept":"K3-2-u4-C5","difficulty":1,"kind":"mc","stem":"‘이/가’ 대신 써서 높이는 말은 무엇인가요?","options":[{"t":"께서","correct":true},{"t":"께","mis":"K3-2-u4-X06"},{"t":"에게","mis":"K3-2-u4-X06"},{"t":"님","mis":"K3-2-u4-X07"}],"explanation":["“형이 말했다”를 떠올려요.","“아버지○○ 말씀하셨다.”","‘께서’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#4','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C6',1,'mc','auto','‘나이’를 높여 이르는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"‘나이’를 높여 이르는 낱말은 무엇인가요?","options":[{"t":"연세","correct":true},{"t":"성함","mis":"K3-2-u4-X07"},{"t":"편찮으시다","mis":"K3-2-u4-X07"},{"t":"분","mis":"K3-2-u4-X07"}],"explanation":["웃어른의 나이를 물을 때 써요.","“○○가 어떻게 되세요?”","‘연세’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#5','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C7',1,'mc','auto','“먼저 갈게요”에서 높임을 받는 사람은 누구인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X09','K3-2-u4-X08']::text[],false,'{"seq":5,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"“먼저 갈게요”에서 높임을 받는 사람은 누구인가요?","options":[{"t":"이 말을 듣는 사람","correct":true},{"t":"먼저 가는 나","mis":"K3-2-u4-X11"},{"t":"내가 가는 곳","mis":"K3-2-u4-X09"},{"t":"말 속에 나오는 친구","mis":"K3-2-u4-X08"}],"explanation":["말끝에 ‘요’가 붙었어요.","‘요’는 듣는 사람을 높여요.","듣는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#6','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C14',1,'ox','auto','같은 부탁이라도 부르는 말과 말하는 태도에 따라 듣는 사람의 대답이 달라질 수 있어요.',ARRAY['K3-2-u4-X18']::text[],false,'{"seq":6,"concept":"K3-2-u4-C14","difficulty":1,"kind":"ox","stem":"같은 부탁이라도 부르는 말과 말하는 태도에 따라 듣는 사람의 대답이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"예절은 내용뿐 아니라 부르는 말·부탁하는 말·태도에 드러나기 때문에","correct":true},{"t":"부탁하는 내용이 같으면 대답도 언제나 같기 때문에","mis":"K3-2-u4-X18"}],"mis":"K3-2-u4-X18","explanation":["준오와 온서를 떠올려요.","부탁 내용은 같았어요.","대답이 달랐으니 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#7','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C18',1,'mc','auto','통화를 마칠 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"mc","stem":"통화를 마칠 때 알맞은 것은 무엇인가요?","options":[{"t":"끝인사를 하고 끊는다","correct":true},{"t":"할 말이 끝나면 바로 끊는다","mis":"K3-2-u4-X25"},{"t":"상대가 끊을 때까지 아무 말도 하지 않는다","mis":"K3-2-u4-X25"},{"t":"처음부터 다시 말한다","mis":"K3-2-u4-X25"}],"explanation":["끊는다는 것도 눈에 안 보여요.","말로 알려요.","끝인사를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#8','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C26',1,'blank','auto','“(　), 같이 놀자!”의 빈칸에 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":8,"concept":"K3-2-u4-C26","difficulty":1,"kind":"blank","stem":"“(　), 같이 놀자!”의 빈칸에 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"얘들아","correct":true},{"t":"애들아","mis":"K3-2-u4-X32"},{"t":"예들아","mis":"K3-2-u4-X32"},{"t":"에들아","mis":"K3-2-u4-X32"}],"explanation":["ㅒ는 짧은 획이 두 개예요.","‘이 아이들아’가 줄었어요.","‘얘들아’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#9','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C9',2,'mc','auto','시우의 쪽지 4번 “집에 가시면”을 고쳐야 하는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X06','K3-2-u4-X10','K3-2-u4-X09']::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우의 쪽지 4번 “집에 가시면”을 고쳐야 하는 까닭은 무엇인가요?","options":[{"t":"집에 가는 사람이 시우 자신인데 높였기 때문에","correct":true},{"t":"할머니를 높이지 않았기 때문에","mis":"K3-2-u4-X06"},{"t":"말끝을 낮췄기 때문에","mis":"K3-2-u4-X10"},{"t":"고칠 필요 없다 — 높임은 많을수록 좋다","mis":"K3-2-u4-X09"}],"explanation":["집에 가는 사람이 누구인지 봐요.","시우 자신이에요.","나는 높이지 않아요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#10','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C8',2,'mc','auto','“칠판이 깨끗하시네요”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X10']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"“칠판이 깨끗하시네요”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“칠판이 깨끗하네요”","correct":true},{"t":"“칠판님이 깨끗하시네요”","mis":"K3-2-u4-X09"},{"t":"“칠판이 깨끗하셔요”","mis":"K3-2-u4-X09"},{"t":"“칠판 깨끗해”","mis":"K3-2-u4-X10"}],"explanation":["칠판은 높이지 않아요.","듣는 분은 말끝으로 높여요.","‘깨끗하네요’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#11','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C11',2,'mc','auto','아버지께서 “다 같이 마당으로 나오너라.”라고 하신 말씀을 누나에게 옮길 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X11']::text[],false,'{"seq":11,"concept":"K3-2-u4-C11","difficulty":2,"kind":"mc","stem":"아버지께서 “다 같이 마당으로 나오너라.”라고 하신 말씀을 누나에게 옮길 때 알맞은 것은 무엇인가요?","options":[{"t":"“누나, 아버지께서 다 같이 마당으로 나오라고 하셔.”","correct":true},{"t":"“누나, 아버지가 다 같이 마당으로 나오래.”","mis":"K3-2-u4-X14"},{"t":"“누나, 아버지께서 다 같이 마당으로 나오시래.”","mis":"K3-2-u4-X14"},{"t":"“누나께서 마당으로 나오시래요.”","mis":"K3-2-u4-X11"}],"explanation":["말씀하신 분은 아버지예요.","나오는 사람은 누나와 우리예요.","아버지를 높여 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#12','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C12',2,'mc','auto','서로 뜻이 비슷한 짝은 무엇인가요?',ARRAY['K3-2-u4-X15']::text[],false,'{"seq":12,"concept":"K3-2-u4-C12","difficulty":2,"kind":"mc","stem":"서로 뜻이 비슷한 짝은 무엇인가요?","options":[{"t":"기쁘다 — 즐겁다","correct":true},{"t":"꽃 — 장미","mis":"K3-2-u4-X15"},{"t":"열다 — 닫다","mis":"K3-2-u4-X15"},{"t":"과일 — 사과","mis":"K3-2-u4-X15"}],"explanation":["두 낱말을 바꾸어 넣어 봐요.","뜻이 크게 달라지지 않아요.","비슷한 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#13','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C15',2,'match','auto','하람이가 한 말과 그 말에 담긴 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u4-C15","difficulty":2,"kind":"match","stem":"하람이가 한 말과 그 말에 담긴 것을 알맞게 이으세요.","pairs":[{"l":"“미안해.”","r":"미안한 마음"},{"l":"“도서관 당번이라 갈 수가 없어.”","r":"도와줄 수 없는 까닭"},{"l":"“내일은 같이 할 수 있어.”","r":"할 수 있는 때"}],"mis":"K3-2-u4-X19","explanation":["하람이는 세 가지를 말했어요.","마음·까닭·할 수 있는 때예요.","하나씩 이어요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"“하람아, 점심시간에 줄넘기 연습 같이 해 줄 수 있어?”"},{"who":"하람","text":"“미안해. 오늘 점심시간에는 도서관 당번이라 갈 수가 없어. 내일은 같이 할 수 있어.”"},{"who":"나윤","text":"“그렇구나. 그럼 내일 하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#14','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C17',2,'ox','auto','할머니께 “거기 있어요.”라고 말끝을 높였으니 누운 채 대답해도 예절을 지킨 거예요.',ARRAY['K3-2-u4-X23']::text[],false,'{"seq":14,"concept":"K3-2-u4-C17","difficulty":2,"kind":"ox","stem":"할머니께 “거기 있어요.”라고 말끝을 높였으니 누운 채 대답해도 예절을 지킨 거예요.","answer":"X","reason_options":[{"t":"말끝뿐 아니라 자세와 대답하는 태도에도 예절이 드러나기 때문에","correct":true},{"t":"말끝에 ‘요’만 붙이면 예절을 다 지킨 것이기 때문에","mis":"K3-2-u4-X23"}],"mis":"K3-2-u4-X23","explanation":["원준이를 떠올려요.","말끝은 높였지만 누워 있었어요.","자세도 예절이라 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#15','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C19',2,'ox','auto','서아처럼 아무 말도 하지 않으면 다툼이 없으니 모둠 대화를 가장 잘한 거예요.',ARRAY['K3-2-u4-X17']::text[],false,'{"seq":15,"concept":"K3-2-u4-C19","difficulty":2,"kind":"ox","stem":"서아처럼 아무 말도 하지 않으면 다툼이 없으니 모둠 대화를 가장 잘한 거예요.","answer":"X","reason_options":[{"t":"모둠 대화는 함께 답을 찾는 것이라 내 생각도 말해야 하기 때문에","correct":true},{"t":"말하지 않으면 끼어들지 않으니 가장 예절 바르기 때문에","mis":"K3-2-u4-X17"}],"mis":"K3-2-u4-X17","explanation":["서아가 말하자 좋은 생각이 나왔어요.","말하지 않으면 그 생각이 묻혀요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#16','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C21',2,'ox','auto','전화로 이야기할 때 “응.”, “그렇구나.” 같은 짧은 말은 하지 않는 편이 좋아요.',ARRAY['K3-2-u4-X27']::text[],false,'{"seq":16,"concept":"K3-2-u4-C21","difficulty":2,"kind":"ox","stem":"전화로 이야기할 때 “응.”, “그렇구나.” 같은 짧은 말은 하지 않는 편이 좋아요.","answer":"X","reason_options":[{"t":"고개 끄덕임을 대신해 듣고 있다는 것을 알려 주기 때문에","correct":true},{"t":"짧은 말은 상대의 말을 끊는 일이기 때문에","mis":"K3-2-u4-X27"}],"mis":"K3-2-u4-X27","explanation":["전화는 고개가 안 보여요.","짧은 말이 끄덕임 대신이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#17','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C3',3,'ox','auto','나이가 같은 친구에게는 어떤 곳에서도 높임 표현을 쓰지 않아요.',ARRAY['K3-2-u4-X02']::text[],false,'{"seq":17,"concept":"K3-2-u4-C3","difficulty":3,"kind":"ox","stem":"나이가 같은 친구에게는 어떤 곳에서도 높임 표현을 쓰지 않아요.","answer":"X","reason_options":[{"t":"학급 회의처럼 여러 사람 앞에서 말하는 곳에서는 친구에게도 높임 표현을 쓰기 때문에","correct":true},{"t":"높임 표현은 나이가 많은 사람에게만 쓰기 때문에","mis":"K3-2-u4-X02"}],"mis":"K3-2-u4-X02","explanation":["민결이와 혜온이를 떠올려요.","회의 때 높임말을 썼어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#18','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C9',3,'ox','auto','시우의 쪽지 4번 “집에 가시면”은 쪽지를 받는 분이 선생님이니 그대로 두어도 돼요.',ARRAY['K3-2-u4-X11']::text[],false,'{"seq":18,"concept":"K3-2-u4-C9","difficulty":3,"kind":"ox","stem":"시우의 쪽지 4번 “집에 가시면”은 쪽지를 받는 분이 선생님이니 그대로 두어도 돼요.","answer":"X","reason_options":[{"t":"집에 가는 사람은 시우 자신이라 나를 높이면 안 되기 때문에","correct":true},{"t":"쪽지를 받는 분이 선생님이면 모든 말을 높여야 하기 때문에","mis":"K3-2-u4-X11"}],"mis":"K3-2-u4-X11","explanation":["가는 사람은 시우예요.","나는 높이지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#19','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C15',3,'ox','auto','부탁을 들어줄 수 없을 때에는 까닭은 말하지 않고 “안 돼.”라고 짧게 말하는 것이 좋아요.',ARRAY['K3-2-u4-X19']::text[],false,'{"seq":19,"concept":"K3-2-u4-C15","difficulty":3,"kind":"ox","stem":"부탁을 들어줄 수 없을 때에는 까닭은 말하지 않고 “안 돼.”라고 짧게 말하는 것이 좋아요.","answer":"X","reason_options":[{"t":"까닭을 말해야 상대가 나를 싫어해서 그런 것이 아님을 알 수 있기 때문에","correct":true},{"t":"짧게 말할수록 예절 바르기 때문에","mis":"K3-2-u4-X19"}],"mis":"K3-2-u4-X19","explanation":["짧은 거절은 오해를 낳아요.","까닭을 함께 말해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#20','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C18',3,'ox','auto','하람이가 마지막에 “그럼 내일 보자. 안녕!” 하고 끊은 것은 알맞아요.',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":20,"concept":"K3-2-u4-C18","difficulty":3,"kind":"ox","stem":"하람이가 마지막에 “그럼 내일 보자. 안녕!” 하고 끊은 것은 알맞아요.","answer":"O","reason_options":[{"t":"통화를 마칠 때 끝인사를 했기 때문에","correct":true},{"t":"할 말이 끝나면 바로 끊는 것이 예절이기 때문에","mis":"K3-2-u4-X25"}],"mis":"K3-2-u4-X25","explanation":["끊는다는 것을 말로 알렸어요.","끝인사를 했어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#21','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C17',3,'mc','auto','이안이와 도율이가 서아를 빼고 귓속말로 정했다면 서아는 어땠을까요?',ARRAY['K3-2-u4-X24','K3-2-u4-X17']::text[],false,'{"seq":21,"concept":"K3-2-u4-C17","difficulty":3,"kind":"mc","stem":"이안이와 도율이가 서아를 빼고 귓속말로 정했다면 서아는 어땠을까요?","options":[{"t":"함께 있는데 혼자 남겨진 마음이 들고 생각을 말할 기회도 없었을 것이다","correct":true},{"t":"조용히 생각할 수 있어 편했을 것이다","mis":"K3-2-u4-X24"},{"t":"빨리 정해져서 모두 좋았을 것이다","mis":"K3-2-u4-X24"},{"t":"예절을 더 잘 지키게 되었을 것이다","mis":"K3-2-u4-X17"}],"explanation":["기현이의 귓속말 장면을 떠올려요.","한 사람만 빠졌어요.","서아의 생각도 묻혀요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#22','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C24',3,'error','auto','우리 반 실천 활동을 고르며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X30']::text[],false,'{"seq":22,"concept":"K3-2-u4-C24","difficulty":3,"kind":"error","stem":"우리 반 실천 활동을 고르며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가장 빨리 끝나는 활동이 제일 좋아.」","correct":true,"mis_target":"K3-2-u4-X30"},{"t":"친구 가 — 「배운 높임 표현을 실제로 써 보는 활동이면 좋겠어.」","mis":"K3-2-u4-X30"},{"t":"친구 다 — 「재미도 있으면서 대화 예절을 연습하는 활동을 고르자.」","mis":"K3-2-u4-X30"}],"explanation":["실천은 배운 것을 써 보는 거예요.","빠르기가 기준이 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#23','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C19',4,'mc','auto','모둠에서 생각이 둘로 갈렸어요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u4-X21','K3-2-u4-X24','K3-2-u4-X17']::text[],false,'{"seq":23,"concept":"K3-2-u4-C19","difficulty":4,"kind":"mc","stem":"모둠에서 생각이 둘로 갈렸어요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"두 생각의 좋은 점을 끝까지 듣고, 하나를 고르거나 둘을 합칠 수 있는지 함께 이야기한다","correct":true},{"t":"목소리가 큰 쪽으로 정한다","mis":"K3-2-u4-X21"},{"t":"말이 없는 친구 생각은 빼고 정한다","mis":"K3-2-u4-X24"},{"t":"다툼이 없게 아무도 말하지 않는다","mis":"K3-2-u4-X17"}],"explanation":["이안이네 모둠을 떠올려요.","둘 다 붙이기로 했어요.","함께 답을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#24','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C15',4,'essay','teacher','하람이의 거절에서 잘한 점 세 가지를 쓰고, 같은 부탁을 웃어른께 거절해야 한다면 어떻게 말씀드릴지 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C15","difficulty":4,"kind":"essay","stem":"하람이의 거절에서 잘한 점 세 가지를 쓰고, 같은 부탁을 웃어른께 거절해야 한다면 어떻게 말씀드릴지 바꾸어 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — “미안해.”라고 미안한 마음을 말했고, 도서관 당번이라는 까닭을 말했으며, 내일은 같이 할 수 있다고 할 수 있는 때를 말했다. 웃어른께 — “죄송해요. 오늘 점심시간에는 도서관 당번이라서 도와드릴 수가 없어요. 내일은 꼭 도와드릴게요.”","scoring_points":["잘한 점 세 가지를 썼는가","웃어른께 높임 표현으로 바꾸어 썼는가","죄송한 마음과 까닭이 드러났는가"]},"explanation":["마음·까닭·할 수 있는 때예요.","웃어른께는 높임 표현을 써요.","거절 예절은 그대로예요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"“하람아, 점심시간에 줄넘기 연습 같이 해 줄 수 있어?”"},{"who":"하람","text":"“미안해. 오늘 점심시간에는 도서관 당번이라 갈 수가 없어. 내일은 같이 할 수 있어.”"},{"who":"나윤","text":"“그렇구나. 그럼 내일 하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_c#25','kor',3,2,'u4','','g3_2_kor_u4_review_c','unit_review','K3-2-u4-C25',4,'essay','teacher','친구가 「다른 지역 말은 틀린 말이야.」라고 했어요. 이 친구에게 방언이 무엇인지 설명하고, 방언을 알아보는 바른 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C25","difficulty":4,"kind":"essay","stem":"친구가 「다른 지역 말은 틀린 말이야.」라고 했어요. 이 친구에게 방언이 무엇인지 설명하고, 방언을 알아보는 바른 방법을 쓰세요.","answer_guide":{"answer":"예: 방언은 어느 한 지역에서 같은 것을 다르게 부르는 말이라 표준어가 아닐 뿐 틀린 말이 아니다. 방언을 알아보려면 그럴듯하게 지어내지 말고, 그 말을 실제로 쓰시는 집이나 둘레 어른께 여쭈어본 뒤 표준어로는 무엇인지 함께 적는 것이 좋다.","scoring_points":["방언의 뜻을 썼는가","틀린 말이 아니라고 썼는가","어른께 여쭈어보는 바른 방법을 썼는가"]},"explanation":["다른 것은 틀린 것이 아니에요.","표준어가 아닐 뿐이에요.","실제로 쓰는 분께 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#1','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C1',1,'mc','auto','이 단원에서 높임 표현과 대화 예절을 함께 배우는 까닭은 무엇인가요?',ARRAY['K3-2-u4-X04','K3-2-u4-X16','K3-2-u4-X01']::text[],false,'{"seq":1,"concept":"K3-2-u4-C1","difficulty":1,"kind":"mc","stem":"이 단원에서 높임 표현과 대화 예절을 함께 배우는 까닭은 무엇인가요?","options":[{"t":"둘 다 상대를 존중하는 일이라서","correct":true},{"t":"둘 다 말을 길게 하는 방법이라서","mis":"K3-2-u4-X04"},{"t":"둘 다 부탁을 다 들어주는 방법이라서","mis":"K3-2-u4-X16"},{"t":"둘 다 말하는 내용만 살피는 일이라서","mis":"K3-2-u4-X01"}],"explanation":["하나는 상대를 높여요.","하나는 상대를 살펴요.","둘 다 존중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#2','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C4',1,'mc','auto','‘-시-’를 넣어 높이는 낱말은 어떤 낱말인가요?',ARRAY['K3-2-u4-X09','K3-2-u4-X05','K3-2-u4-X08']::text[],false,'{"seq":2,"concept":"K3-2-u4-C4","difficulty":1,"kind":"mc","stem":"‘-시-’를 넣어 높이는 낱말은 어떤 낱말인가요?","options":[{"t":"움직임을 나타내는 말","correct":true},{"t":"물건의 이름","mis":"K3-2-u4-X09"},{"t":"장소를 나타내는 말","mis":"K3-2-u4-X05"},{"t":"말을 듣는 사람의 이름","mis":"K3-2-u4-X08"}],"explanation":["오다 → 오시다.","읽다 → 읽으시다.","움직임을 나타내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#3','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C5',1,'ox','auto','“형이 말했다”를 “아버지께서 말씀하셨다”로 바꾸면 ‘께서’와 ‘-시-’가 함께 아버지를 높여요.',ARRAY['K3-2-u4-X08']::text[],false,'{"seq":3,"concept":"K3-2-u4-C5","difficulty":1,"kind":"ox","stem":"“형이 말했다”를 “아버지께서 말씀하셨다”로 바꾸면 ‘께서’와 ‘-시-’가 함께 아버지를 높여요.","answer":"O","reason_options":[{"t":"말하는 일을 하는 아버지를 두 방법으로 높였기 때문에","correct":true},{"t":"‘께서’는 듣는 사람을 높이는 말이기 때문에","mis":"K3-2-u4-X08"}],"mis":"K3-2-u4-X08","explanation":["‘께서’가 들어갔어요.","‘-시-’도 들어갔어요.","둘 다 아버지를 높이니 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#4','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C6',1,'mc','auto','‘아프다’를 높여 이르는 낱말은 무엇인가요?',ARRAY['K3-2-u4-X07']::text[],false,'{"seq":4,"concept":"K3-2-u4-C6","difficulty":1,"kind":"mc","stem":"‘아프다’를 높여 이르는 낱말은 무엇인가요?","options":[{"t":"편찮으시다","correct":true},{"t":"주무시다","mis":"K3-2-u4-X07"},{"t":"계시다","mis":"K3-2-u4-X07"},{"t":"뵙다","mis":"K3-2-u4-X07"}],"explanation":["웃어른이 아프실 때 써요.","“할머니께서 ○○○○○.”","‘편찮으시다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#5','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C7',1,'mc','auto','높임을 나타내는 네 가지 방법 가운데 듣는 사람을 높이는 것은 무엇인가요?',ARRAY['K3-2-u4-X08']::text[],false,'{"seq":5,"concept":"K3-2-u4-C7","difficulty":1,"kind":"mc","stem":"높임을 나타내는 네 가지 방법 가운데 듣는 사람을 높이는 것은 무엇인가요?","options":[{"t":"말끝에 ‘-습니다’나 ‘요’ 붙이기","correct":true},{"t":"‘-시-’ 넣기","mis":"K3-2-u4-X08"},{"t":"‘께서’ 쓰기","mis":"K3-2-u4-X08"},{"t":"‘성함’ 같은 낱말 쓰기","mis":"K3-2-u4-X08"}],"explanation":["셋은 말 속의 사람을 높여요.","하나만 듣는 사람을 높여요.","말끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#6','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C13',1,'sa','auto','말하는 사람과 듣는 사람이 말을 주고받을 때 지키는 것을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u4-C13","difficulty":1,"kind":"sa","stem":"말하는 사람과 듣는 사람이 말을 주고받을 때 지키는 것을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["대화 예절","대화예절"],"explanation":["말을 주고받는 것은 대화예요.","그때 지키는 것이에요.","‘대화 예절’이에요."],"mis":"K3-2-u4-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#7','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C18',1,'match','auto','전화로 말할 때 알맞지 않은 말버릇과 바르게 고친 것을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u4-C18","difficulty":1,"kind":"match","stem":"전화로 말할 때 알맞지 않은 말버릇과 바르게 고친 것을 이으세요.","pairs":[{"l":"받을 때까지 계속 다시 건다","r":"다시 걸 때를 정하고 기다린다"},{"l":"할 말이 끝나면 바로 끊는다","r":"끝인사를 하고 끊는다"},{"l":"받자마자 내 할 말부터 한다","r":"통화해도 되는 때인지 먼저 묻는다"}],"mis":"K3-2-u4-X25","explanation":["상대가 볼 수 없는 것을 떠올려요.","말로 알려 주면 돼요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#8','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C26',1,'blank','auto','봄·여름·가을·겨울을 (　)이라고 해요. 빈칸에 바르게 쓴 낱말은 무엇인가요?',ARRAY['K3-2-u4-X32']::text[],false,'{"seq":8,"concept":"K3-2-u4-C26","difficulty":1,"kind":"blank","stem":"봄·여름·가을·겨울을 (　)이라고 해요. 빈칸에 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"계절","correct":true},{"t":"게절","mis":"K3-2-u4-X32"},{"t":"개절","mis":"K3-2-u4-X32"},{"t":"걔절","mis":"K3-2-u4-X32"}],"explanation":["ㅖ는 짧은 획이 두 개예요.","‘계’를 바르게 써요.","‘계절’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#9','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C9',2,'mc','auto','시우의 쪽지 5번 “그럼 내일 봐요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X11','K3-2-u4-X10']::text[],false,'{"seq":9,"concept":"K3-2-u4-C9","difficulty":2,"kind":"mc","stem":"시우의 쪽지 5번 “그럼 내일 봐요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“그럼 내일 뵙겠습니다.”","correct":true},{"t":"“그럼 내일 보세요.”","mis":"K3-2-u4-X11"},{"t":"“그럼 내일 봐.”","mis":"K3-2-u4-X10"},{"t":"“그럼 내일 보셔요.”","mis":"K3-2-u4-X11"}],"explanation":["내가 선생님을 보는 거예요.","‘보다’의 높임 낱말을 써요.","‘뵙겠습니다’예요."],"asset":{"type":"passage","lines":["1 선생님, 저 시우예요. 오늘 일찍 가 봐야 해서 쪽지를 써요.","2 할머니가 아파서 제가 병원에 같이 가야 해요.","3 선생님께 드릴 받아쓰기 공책은 책상 위에 계세요.","4 집에 가시면 할머니께 꼭 말씀드릴게요.","5 그럼 내일 봐요."],"title":"시우가 담임 선생님께 남긴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#10','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C8',2,'mc','auto','“선생님께서 주신 책이 재미있으세요.”를 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X09']::text[],false,'{"seq":10,"concept":"K3-2-u4-C8","difficulty":2,"kind":"mc","stem":"“선생님께서 주신 책이 재미있으세요.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"“선생님께서 주신 책이 재미있어요.”","correct":true},{"t":"“선생님이 준 책이 재미있어요.”","mis":"K3-2-u4-X10"},{"t":"“선생님께서 주신 책께서 재미있으세요.”","mis":"K3-2-u4-X09"},{"t":"“선생님께서 주신 책이 재미있으셔요.”","mis":"K3-2-u4-X09"}],"explanation":["주신 분은 선생님이라 높여요.","재미있는 것은 책이에요.","책은 높이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#11','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C11',2,'mc','auto','웃어른의 말씀을 다른 사람에게 옮길 때 높이는 사람은 누구인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X11','K3-2-u4-X10']::text[],false,'{"seq":11,"concept":"K3-2-u4-C11","difficulty":2,"kind":"mc","stem":"웃어른의 말씀을 다른 사람에게 옮길 때 높이는 사람은 누구인가요?","options":[{"t":"그 말을 처음 하신 웃어른","correct":true},{"t":"말을 옮겨 받는 친구","mis":"K3-2-u4-X14"},{"t":"말을 옮기는 나","mis":"K3-2-u4-X11"},{"t":"아무도 높이지 않는다","mis":"K3-2-u4-X10"}],"explanation":["“선생님께서 오라고 하셔.”","높인 분은 선생님이에요.","말씀하신 분을 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#12','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C12',2,'match','auto','새로운 낱말 짝과 그 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K3-2-u4-C12","difficulty":2,"kind":"match","stem":"새로운 낱말 짝과 그 관계를 알맞게 이으세요.","pairs":[{"l":"과일 — 사과","r":"한 낱말이 다른 낱말의 뜻을 포함하는 관계"},{"l":"열다 — 닫다","r":"서로 뜻이 반대인 관계"},{"l":"기쁘다 — 즐겁다","r":"서로 뜻이 비슷한 관계"}],"mis":"K3-2-u4-X15","explanation":["사과는 과일의 한 가지예요.","열고 닫는 것은 반대예요.","기쁘다와 즐겁다는 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#13','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C15',2,'mc','auto','하람이가 “싫어.”라고만 말했다면 어떤 일이 생길 수 있을까요?',ARRAY['K3-2-u4-X19']::text[],false,'{"seq":13,"concept":"K3-2-u4-C15","difficulty":2,"kind":"mc","stem":"하람이가 “싫어.”라고만 말했다면 어떤 일이 생길 수 있을까요?","options":[{"t":"나윤이는 하람이가 자기를 싫어해서 그런가 하고 생각할 수 있다","correct":true},{"t":"예절을 더 잘 지킨 것이 된다","mis":"K3-2-u4-X19"},{"t":"아무 일도 생기지 않는다","mis":"K3-2-u4-X19"},{"t":"나윤이가 까닭을 저절로 안다","mis":"K3-2-u4-X19"}],"explanation":["까닭이 없으면 상대는 몰라요.","오해가 생길 수 있어요.","그래서 까닭을 말해요."],"asset":{"type":"speech","turns":[{"who":"나윤","text":"“하람아, 점심시간에 줄넘기 연습 같이 해 줄 수 있어?”"},{"who":"하람","text":"“미안해. 오늘 점심시간에는 도서관 당번이라 갈 수가 없어. 내일은 같이 할 수 있어.”"},{"who":"나윤","text":"“그렇구나. 그럼 내일 하자.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#14','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C16',2,'mc','auto','상황을 살필 때 함께 보는 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['K3-2-u4-X22']::text[],false,'{"seq":14,"concept":"K3-2-u4-C16","difficulty":2,"kind":"mc","stem":"상황을 살필 때 함께 보는 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"내 옷 색깔","correct":true},{"t":"대화 상대","mis":"K3-2-u4-X22"},{"t":"시간과 장소","mis":"K3-2-u4-X22"},{"t":"목적과 방식","mis":"K3-2-u4-X22"}],"explanation":["상황은 세 가지로 살펴요.","상대·장소·목적이에요.","옷 색깔은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#15','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C19',2,'mc','auto','이 모둠이 마지막에 둘 다 붙이기로 한 것에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u4-X26','K3-2-u4-X17']::text[],false,'{"seq":15,"concept":"K3-2-u4-C19","difficulty":2,"kind":"mc","stem":"이 모둠이 마지막에 둘 다 붙이기로 한 것에서 알 수 있는 것은 무엇인가요?","options":[{"t":"끝까지 듣고 서로 생각을 말하니 함께 답을 찾았다","correct":true},{"t":"도율이가 말다툼에서 이겼다","mis":"K3-2-u4-X26"},{"t":"서아가 하고 싶은 말을 참았다","mis":"K3-2-u4-X17"},{"t":"이안이가 혼자 정했다","mis":"K3-2-u4-X26"}],"explanation":["그림도, 책 이야기도 붙여요.","두 생각이 모였어요.","함께 답을 찾았어요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#16','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C22',2,'ox','auto','다짐을 지키지 못한 날에는 무엇 때문이었는지 적어 두면 다음을 바꾸는 데 도움이 돼요.',ARRAY['K3-2-u4-X28']::text[],false,'{"seq":16,"concept":"K3-2-u4-C22","difficulty":2,"kind":"ox","stem":"다짐을 지키지 못한 날에는 무엇 때문이었는지 적어 두면 다음을 바꾸는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"무엇 때문에 못 지켰는지 알아야 다음에 고칠 수 있기 때문에","correct":true},{"t":"못 지킨 날은 지워야 표가 깔끔하기 때문에","mis":"K3-2-u4-X28"}],"mis":"K3-2-u4-X28","explanation":["못 지킨 날이 있어도 괜찮아요.","까닭을 적어 두어요.","다음을 바꾸니 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#17','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C3',3,'mc','auto','「높임 표현은 나이표가 아니다」라는 말의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X10','K3-2-u4-X03','K3-2-u4-X02']::text[],false,'{"seq":17,"concept":"K3-2-u4-C3","difficulty":3,"kind":"mc","stem":"「높임 표현은 나이표가 아니다」라는 말의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"나이만이 아니라 곳·사이·마음을 함께 살펴 높임 표현을 고른다는 뜻","correct":true},{"t":"나이가 많은 사람에게도 높임말을 쓰지 않는다는 뜻","mis":"K3-2-u4-X10"},{"t":"누구에게나 언제나 높임말을 쓴다는 뜻","mis":"K3-2-u4-X03"},{"t":"키나 힘으로 높임말을 고른다는 뜻","mis":"K3-2-u4-X02"}],"explanation":["나이표는 나이만 보는 표예요.","높임은 나이만 보지 않아요.","곳·사이·마음을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#18','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C8',3,'mc','auto','높임 표현을 바르게 쓰려면 가장 먼저 무엇을 해야 할까요?',ARRAY['K3-2-u4-X09','K3-2-u4-X04','K3-2-u4-X10']::text[],false,'{"seq":18,"concept":"K3-2-u4-C8","difficulty":3,"kind":"mc","stem":"높임 표현을 바르게 쓰려면 가장 먼저 무엇을 해야 할까요?","options":[{"t":"높여야 할 사람이 누구인지 찾는다","correct":true},{"t":"‘-시-’를 몇 번 넣을지 센다","mis":"K3-2-u4-X09"},{"t":"어려운 낱말을 고른다","mis":"K3-2-u4-X04"},{"t":"높임을 아예 빼 버린다","mis":"K3-2-u4-X10"}],"explanation":["높이는 것은 사람이에요.","그 사람을 먼저 찾아요.","그다음 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#19','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C15',3,'mc','auto','거절과 대화 예절에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u4-X16','K3-2-u4-X20','K3-2-u4-X19']::text[],false,'{"seq":19,"concept":"K3-2-u4-C15","difficulty":3,"kind":"mc","stem":"거절과 대화 예절에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"거절하더라도 미안한 마음과 까닭을 말하면 예절을 지키는 것이다","correct":true},{"t":"거절하면 언제나 예절을 어긴 것이다","mis":"K3-2-u4-X16"},{"t":"웃어른께는 거짓으로라도 하겠다고 한다","mis":"K3-2-u4-X20"},{"t":"거절할 때는 말없이 피하는 것이 낫다","mis":"K3-2-u4-X19"}],"explanation":["거절은 잘못이 아니에요.","거짓으로 대답하지 않아요.","마음과 까닭을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#20','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C20',3,'error','auto','하람이의 통화를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u4-X25']::text[],false,'{"seq":20,"concept":"K3-2-u4-C20","difficulty":3,"kind":"error","stem":"하람이의 통화를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「어머니가 받으셨으니 “하람인데, 나윤이 바꿔.” 하면 돼.」","correct":true,"mis_target":"K3-2-u4-X25"},{"t":"친구 가 — 「나윤이에게 지금 통화해도 되는지 물었어.」","mis":"K3-2-u4-X25"},{"t":"친구 나 — 「어머니께는 같은 반 하람이라고 밝혔어.」","mis":"K3-2-u4-X25"}],"explanation":["받으신 분은 어머니예요.","인사하고 높여 말해야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"나윤이 어머니","text":"“여보세요?”"},{"who":"하람","text":"“안녕하세요? 저는 나윤이와 같은 반인 하람입니다. 나윤이 집에 있어요?”"},{"who":"나윤이 어머니","text":"“그래, 잠깐만 기다리렴.”"},{"who":"나윤","text":"“하람아, 무슨 일이야?”"},{"who":"하람","text":"“내일 모둠 발표 준비물을 정하려고 전화했어. 지금 통화해도 돼?”"},{"who":"하람","text":"(이야기를 마치고) “그럼 내일 보자. 안녕!”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#21','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C19',3,'ox','auto','이안이처럼 말하지 않는 친구에게 생각을 물어보는 것은 그 친구를 귀찮게 하는 일이에요.',ARRAY['K3-2-u4-X17']::text[],false,'{"seq":21,"concept":"K3-2-u4-C19","difficulty":3,"kind":"ox","stem":"이안이처럼 말하지 않는 친구에게 생각을 물어보는 것은 그 친구를 귀찮게 하는 일이에요.","answer":"X","reason_options":[{"t":"모둠 대화는 함께 답을 찾는 것이라 모두의 생각을 듣는 일이기 때문에","correct":true},{"t":"말하지 않는 친구는 그대로 두는 것이 예절이기 때문에","mis":"K3-2-u4-X17"}],"mis":"K3-2-u4-X17","explanation":["서아에게도 생각이 있었어요.","물어보니 말했어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#22','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C10',3,'ox','auto','서툰 인사는 인사를 하지 않는 것보다 나빠요.',ARRAY['K3-2-u4-X12']::text[],false,'{"seq":22,"concept":"K3-2-u4-C10","difficulty":3,"kind":"ox","stem":"서툰 인사는 인사를 하지 않는 것보다 나빠요.","answer":"X","reason_options":[{"t":"서툴러도 말을 건네면 상대를 살피는 마음이 전해지기 때문에","correct":true},{"t":"틀린 인사는 상대를 언짢게 하기 때문에","mis":"K3-2-u4-X12"}],"mis":"K3-2-u4-X12","explanation":["민결이는 인사를 그만두었다가 불편했어요.","다시 건네자 어른이 고마워하셨어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#23','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C11',4,'mc','auto','짝이 “보건 선생님이 너 아프면 오래.”라고 전해 주었어요. 이 말을 바르게 고친 것은 무엇인가요?',ARRAY['K3-2-u4-X14','K3-2-u4-X03','K3-2-u4-X11']::text[],false,'{"seq":23,"concept":"K3-2-u4-C11","difficulty":4,"kind":"mc","stem":"짝이 “보건 선생님이 너 아프면 오래.”라고 전해 주었어요. 이 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"“보건 선생님께서 너 아프면 오라고 하셨어.”","correct":true},{"t":"“보건 선생님께서 너 아프면 오시래.”","mis":"K3-2-u4-X14"},{"t":"“보건 선생님께서 너 아프면 오라고 하셨어요.”","mis":"K3-2-u4-X03"},{"t":"“보건 선생님이 너 편찮으시면 오래.”","mis":"K3-2-u4-X11"}],"explanation":["말씀하신 분은 보건 선생님이에요.","아프고 가는 사람은 친구예요.","친구는 높이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#24','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C19',4,'essay','teacher','이안이네 모둠 대화에서 이안·도율·서아가 각각 어떻게 말했는지 쓰고, 모둠 대화에서 지켜야 할 것을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u4-C19","difficulty":4,"kind":"essay","stem":"이안이네 모둠 대화에서 이안·도율·서아가 각각 어떻게 말했는지 쓰고, 모둠 대화에서 지켜야 할 것을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도율이는 다른 생각을 듣지 않고 그림만 붙이자고 밀고 갔다. 서아는 처음에 아무 말도 하지 않았다. 이안이는 도율이의 말을 끝까지 듣고 서아에게 생각을 물었다. 모둠 대화에서는 다른 사람의 말을 끝까지 듣고 내 생각도 말해야 한다. 함께 답을 찾는 것이라 모두의 생각이 모여야 하기 때문이다.","scoring_points":["세 친구의 말을 바르게 썼는가","끝까지 듣고 내 생각도 말한다고 썼는가","함께 답을 찾는다는 까닭을 썼는가"]},"explanation":["세 친구가 다 달랐어요.","이안이를 떠올려요.","듣기와 말하기 둘 다예요."],"asset":{"type":"speech","turns":[{"who":"이안","text":"“우리 모둠 게시판에 무엇을 붙일지 정하자.”"},{"who":"도율","text":"“무조건 그림이야. 다른 건 다 별로야.”"},{"who":"서아","text":"(아무 말도 하지 않고 고개만 숙인다)"},{"who":"이안","text":"“도율이는 그림이 좋구나. 서아는 어떻게 생각해?”"},{"who":"서아","text":"“나는…… 우리가 읽은 책 이야기를 붙여도 좋을 것 같아.”"},{"who":"도율","text":"“아, 그것도 괜찮다. 둘 다 붙일까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u4_review_d#25','kor',3,2,'u4','','g3_2_kor_u4_review_d','unit_review','K3-2-u4-C1',4,'essay','teacher','이 단원에서 남길 두 가지를 쓰고, 높임 표현과 대화 예절이 한 대화 안에서 함께 쓰이는 말을 하나 만들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u4-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 남길 두 가지를 쓰고, 높임 표현과 대화 예절이 한 대화 안에서 함께 쓰이는 말을 하나 만들어 쓰세요.","answer_guide":{"answer":"예: 첫째, 높임 표현은 나이표가 아니라 곳과 사이를 살펴 쓰는 것이다. 둘째, 대화 예절은 시키는 대로 하는 것이 아니라 상대를 살피며 말하고 듣는 것이다. 만든 말 — 선생님께서 심부름을 부탁하셨는데 급식 당번일 때: “선생님, 죄송해요. 지금 급식 당번이라서 바로 갈 수가 없어요. 끝나고 바로 가겠습니다.”","scoring_points":["남길 두 가지를 썼는가","높임 표현을 바르게 넣었는가","대화 예절(마음·까닭)이 함께 드러났는가"]},"explanation":["높임 표현과 대화 예절이에요.","둘 다 존중이에요.","한 문장 안에 함께 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
